    bytes32 private constant _POINTER_ARTWORK_FINALITY_RECOVERY =
        0xead6d91d79d13e47343aa9d24c2198c5e4fcd612fdd9531d8b2549bab7651474;
    bytes32 private constant _POINTER_ROYALTY_RESOLVER =
