    bytes32 private constant _MODULE_REVENUE_RESOLVER =
        0x217d16181cfb7c9bb7e1687d0b13ef4b864e9154dc37b60f75a88bec454b5467;
    bytes32 private constant _MODULE_ARTWORK_FINALITY_RECOVERY =
