// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/modules/IStreamModuleRegistry.sol";

/// @notice Exact retained NFTDelegation grants for bid-for-vault and delegate-triggered claims.
/// @dev The host owns immutable configuration, GGP selection, original sale admission and
/// deposit/claim effects. This helper never spends funds or writes a delivery binding.
library StreamNativeAuctionDelegation {
    address internal constant ALL_COLLECTIONS = 0x8888888888888888888888888888888888888888;
    bytes32 internal constant GAS_PARAMETER =
        keccak256("6529STREAM_GGP_DELEGATE_REGISTRY_GAS_LIMIT");
    bytes32 private constant MANIFEST =
        keccak256("6529STREAM_NATIVE_AUCTION_NFTDELEGATION_MANIFEST_V1");
    bytes4 private constant ROW = bytes4(keccak256("globalDelegationHashes(bytes32,uint256)"));

    struct Configuration {
        uint256 chainId;
        address core;
        address delegateRegistry;
        bytes32 delegateRegistryCodeHash;
        uint256 delegationUsecase;
        bytes32 baseManifestHash;
        address moduleRegistry;
        bytes32 moduleRegistryCodeHash;
    }

    /// @dev A locator into the pinned original registry, never caller-supplied authority facts.
    struct Witness {
        bool walletWide;
        uint256 index;
    }

    error DelegationConfigurationInvalid();
    error DelegationRegistryUnavailable(address registry);
    error DelegationReadGas(uint256 available, uint256 required);
    error DelegationReadFailed(address registry);
    error DelegationReadMalformed(address registry, uint256 length);
    error DelegationNotFound(address vault, address delegate);
    error DelegationManifestMismatch();
    error BidDeliveryAlreadyBound(address originalRecipient, address suppliedRecipient);

    /// @notice Complete compact declaration bytes committed by this profile's module record.
    /// @dev baseManifestHash retains the rest of the module's original declared meaning.
    function manifestBytes(Configuration memory c) public view returns (bytes memory) {
        return abi.encode(
            MANIFEST,
            c.chainId,
            address(this),
            c.baseManifestHash,
            c.core,
            c.delegateRegistry,
            c.delegateRegistryCodeHash,
            c.delegationUsecase
        );
    }

    function validateConfiguration(Configuration memory c) public view {
        if (
            c.chainId != block.chainid || c.core == address(0) || c.core == ALL_COLLECTIONS
                || c.baseManifestHash == 0 || c.delegationUsecase == 0
                || (c.delegationUsecase == 998 || c.delegationUsecase == 999)
                || c.moduleRegistry == address(0) || c.moduleRegistryCodeHash == 0
                || c.moduleRegistry.codehash != c.moduleRegistryCodeHash
        ) revert DelegationConfigurationInvalid();
        _registry(c);
    }

    /// @notice Resolve a bid recipient before the host atomically writes its original binding.
    /// @dev Exact repeat bids use the saved binding without reauthorizing it. The host must
    /// retain its ordinary current sale/module checks and emit/write only after a valid bid.
    function resolveDelivery(
        mapping(bytes32 => mapping(address => address)) storage bindings,
        Configuration memory c,
        bytes32 auctionId,
        address bidder,
        address requested,
        Witness memory witness,
        uint256 readGas
    ) public view returns (address recipient) {
        if (auctionId == 0 || bidder == address(0) || bidder == address(this)) {
            revert DelegationConfigurationInvalid();
        }
        recipient = requested == address(0) ? bidder : requested;
        if (recipient == address(this)) revert DelegationConfigurationInvalid();
        address original = bindings[auctionId][bidder];
        if (original != address(0)) {
            if (original != recipient) revert BidDeliveryAlreadyBound(original, recipient);
            return original;
        }
        if (recipient == bidder) return recipient;
        requireManifest(c, readGas);
        requireDelegated(c, recipient, bidder, witness, readGas);
    }

    /// @notice Live delegate authority can trigger a claim only to the credited account itself.
    /// @dev Own-account claims keep their existing caller-chosen destination. No module
    /// status, pause, artist, phase or payment authorization is replayed on this claim read.
    function claimRecipient(
        Configuration memory c,
        address account,
        address caller,
        address requested,
        Witness memory witness,
        uint256 readGas
    ) public view returns (address recipient) {
        if (account == address(0) || caller == address(0)) {
            revert DelegationConfigurationInvalid();
        }
        if (caller == account) {
            if (requested == address(0) || requested == address(this)) {
                revert DelegationConfigurationInvalid();
            }
            return requested;
        }
        if (requested != account || account == address(this)) {
            revert DelegationNotFound(account, caller);
        }
        requireDelegated(c, account, caller, witness, readGas);
        return account;
    }

    /// @notice Check one actual still-retained all-token grant, including its expiry and scope.
    /// @dev NFTDelegation's boolean global getter checks only array length, so it cannot
    /// replace this full record check. Its packed key is an exact upstream protocol preimage.
    function requireDelegated(
        Configuration memory c,
        address vault,
        address delegate,
        Witness memory witness,
        uint256 readGas
    ) public view {
        _registry(c);
        if (vault == address(0) || delegate == address(0) || vault == delegate) {
            revert DelegationNotFound(vault, delegate);
        }
        address scope = witness.walletWide ? ALL_COLLECTIONS : c.core;
        bytes32 key = keccak256(abi.encodePacked(vault, scope, delegate, c.delegationUsecase));
        bytes memory data = abi.encodeWithSelector(ROW, key, witness.index);
        uint256[6] memory row;
        bool ok;
        uint256 size;
        address target = c.delegateRegistry;
        _gas(readGas);
        assembly ("memory-safe") {
            ok := staticcall(readGas, target, add(data, 32), mload(data), row, 192)
            size := returndatasize()
        }
        if (!ok) revert DelegationReadFailed(target);
        if (size != 192) revert DelegationReadMalformed(target, size);
        if (
            row[0] != uint256(uint160(vault)) || row[1] != uint256(uint160(delegate))
                || row[2] > block.timestamp || row[3] <= block.timestamp || row[4] != 1
                || row[5] != 0
        ) revert DelegationNotFound(vault, delegate);
    }

    /// @notice Bind registry address/runtime/usecase to the actual adapter's registered manifest.
    /// @dev Ordinary original-sale lifecycle admission remains the host's responsibility.
    function requireManifest(Configuration memory c, uint256 readGas) public view {
        validateConfiguration(c);
        bytes memory data = abi.encodeCall(IStreamModuleRegistry.moduleRecord, (address(this)));
        uint256[14] memory words;
        bool ok;
        uint256 size;
        address target = c.moduleRegistry;
        _gas(readGas);
        assembly ("memory-safe") {
            ok := staticcall(readGas, target, add(data, 32), mload(data), words, 448)
            size := returndatasize()
        }
        if (!ok) revert DelegationReadFailed(target);
        if (
            size < 448 || words[0] != 32 || words[1] > 3 || words[5] > type(uint32).max
                || words[9] != 384 || words[10] > type(uint64).max || words[11] > type(uint64).max
                || words[12] > type(uint64).max || words[13] > size - 448
                || size - 448 != ((words[13] + 31) / 32) * 32
        ) revert DelegationReadMalformed(target, size);
        if (
            words[1] != 1 || bytes32(words[6]) != address(this).codehash || words[7] == 0
                || bytes32(words[8]) != keccak256(manifestBytes(c)) || words[10] == 0
                || words[10] > block.timestamp || words[11] < words[10]
                || words[11] > block.timestamp || words[12] == 0
        ) revert DelegationManifestMismatch();
    }

    function _registry(Configuration memory c) private view {
        if (
            c.chainId != block.chainid || c.core == address(0) || c.core == ALL_COLLECTIONS
                || c.delegationUsecase == 0
                || (c.delegationUsecase == 998 || c.delegationUsecase == 999)
        ) revert DelegationConfigurationInvalid();
        if (
            c.delegateRegistry == address(0) || c.delegateRegistry.code.length == 0
                || c.delegateRegistryCodeHash == 0
                || c.delegateRegistry.codehash != c.delegateRegistryCodeHash
        ) revert DelegationRegistryUnavailable(c.delegateRegistry);
    }

    function _gas(uint256 cap) private view {
        uint256 available = gasleft();
        if (
            cap == 0 || cap > available
                || available - cap < cap / 63 + (cap % 63 == 0 ? 0 : 1) + 30000
        ) {
            revert DelegationReadGas(available, cap);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/auctions/IStreamNativeEnglishAuction.sol";
import "../mint/StreamRefundWindowSupport.sol";
import "../mint/StreamRefundClock.sol";
import "../mint/StreamPreparedNativeContentReads.sol";
import "../revenue/StreamPreparedNativeSettlementValidation.sol";
import "../revenue/StreamPreparedNativeSettlementHash.sol";
import "../../interfaces/stream/mint/IStreamPreparedNativeMint.sol";

/// @notice Original creation/bid authorization and exact prepared-mint projection.
/// @dev New versioned entry domains leave historical auction and mint preimages unchanged.
library StreamNativeEnglishAuctionSupport {
    bytes32 private constant CREATION = keccak256(
        "NativeAuctionCreation(bytes32 configHash,address artist,bytes32 nonce,uint64 deadline)"
    );
    bytes32 private constant BID = keccak256(
        "NativeAuctionBid(bytes32 auctionId,bytes32 configHash,address payer,address executor,address deliverTo,uint256 amount,uint256 maxRevealFee,bytes32 nonce,uint64 deadline,uint64 finalizeBy)"
    );

    function configHash(IStreamNativeEnglishAuction.Configuration memory c)
        public
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_NATIVE_ENGLISH_AUCTION_CONFIG_V1"),
                block.chainid,
                address(this),
                c
            )
        );
    }

    function creationDigest(IStreamNativeEnglishAuction.CreationAuthorization memory a)
        public
        view
        returns (bytes32)
    {
        return digest(keccak256(abi.encode(CREATION, a)));
    }

    function bidDigest(IStreamNativeEnglishAuction.BidAuthorization memory a)
        public
        view
        returns (bytes32)
    {
        return digest(keccak256(abi.encode(BID, a)));
    }

    function digest(bytes32 body) private view returns (bytes32) {
        bytes32 domain = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256("6529StreamNativeEnglishAuction"),
                keccak256("1"),
                block.chainid,
                address(this)
            )
        );
        return keccak256(abi.encodePacked(hex"1901", domain, body));
    }

    function validateCreation(
        StreamRefundWindowSupport.Context memory x,
        IStreamNativeEnglishAuction.Configuration memory c,
        bytes memory artwork,
        IStreamNativeEnglishAuction.CreationAuthorization memory authorization,
        bytes memory platformSignature,
        bytes memory artistSignature
    )
        public
        view
        returns (bytes32 hash, StreamRefundWindowSupport.ArtistAssociation memory association)
    {
        if (!c.mintAtSettlement || c.tokenId != 0 || c.contentManifestRoot != 0) {
            revert IStreamNativeEnglishAuction.UnsupportedNativeAuctionProfile();
        }
        if (
            c.collectionId == 0 || c.phaseId == 0 || c.poster == address(0)
                || c.poster == address(this) || c.artworkCommitment == 0
                || c.artworkCommitment != keccak256(artwork) || artwork.length > 8192
                || c.mintCommitment == 0 || c.primaryPolicyMode != 1
                || c.expectedPrimaryPolicyHash == 0 || c.settlementWindow < 86400
                || c.settlementWindow > 7776000 || c.mintPolicyHash == 0 || authorization.nonce == 0
                || authorization.deadline < block.timestamp || authorization.artist == address(0)
                || authorization.configHash != configHash(c)
        ) revert IStreamNativeEnglishAuction.InvalidNativeAuction();
        StreamEnglishAuctionClock.initialize(c.clock, c.reservePrice, StreamRefundClock.now64());
        StreamEnglishAuctionClock.minimumBid(
            0, c.reservePrice, c.minIncrementBps, c.incrementFloorWaived
        );
        requirePhase(x, c, false);
        if (profilePolicy(x.resolver, c.collectionId) != c.expectedPrimaryPolicyHash) {
            revert IStreamNativeEnglishAuction.InvalidNativeAuction();
        }
        StreamRefundWindowSupport.revealPolicy(x, c.collectionId);
        association = StreamRefundWindowSupport.artistAssociation(x, c.collectionId);
        if (
            association.state != 2 || association.authorityStatus != 1 || association.artistId == 0
                || association.generation == 0 || association.bindingHash == 0
                || acceptedArtist(x, c.collectionId) != authorization.artist
        ) revert IStreamNativeEnglishAuction.InvalidNativeAuction();
        hash = creationDigest(authorization);
        requireSignature(x.platform, hash, platformSignature, x.signatureGas);
        requireSignature(authorization.artist, hash, artistSignature, x.signatureGas);
    }

    function requireSignature(address signer, bytes32 hash, bytes memory signature, uint256 cap)
        public
        view
    {
        if (!StreamNativeSettlementSupport.validSignature(signer, hash, signature, cap)) {
            revert IStreamNativeEnglishAuction.NativeAuctionAuthorizationInvalid(signer);
        }
    }

    function acceptedArtist(StreamRefundWindowSupport.Context memory x, uint256 collectionId)
        private
        view
        returns (address artist)
    {
        uint256 cap = x.artistGas;
        uint256 available = gasleft();
        if (cap > available || available - cap < cap / 63 + (cap % 63 == 0 ? 0 : 1) + 30000) {
            revert IStreamNativeEnglishAuction.NativeAuctionDeliveryGas(available, cap);
        }
        bytes memory data = abi.encodeCall(IStreamArtistAttribution.acceptedArtist, (collectionId));
        address target = address(x.artists);
        bool ok;
        uint256 size;
        uint256 word;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            word := mload(0)
        }
        if (!ok || size != 32 || word > type(uint160).max) {
            revert IStreamNativeEnglishAuction.InvalidNativeAuction();
        }
        return address(uint160(word));
    }

    function requirePhase(
        StreamRefundWindowSupport.Context memory x,
        IStreamNativeEnglishAuction.Configuration memory c,
        bool live
    ) public view {
        IStreamMintReads manager = IStreamMintReads(address(x.manager));
        (bool exists, IStreamMintManager.MintPhaseConfig memory phase) =
            manager.phase(c.collectionId, c.phaseId);
        if (
            !exists || phase.paused
                || !manager.phaseExecutor(c.collectionId, c.phaseId, address(this))
                || (c.contentManifestRoot == 0
                    && manager.phaseGate(c.collectionId, c.phaseId).gate != address(0))
        ) revert IStreamNativeEnglishAuction.UnsupportedNativeAuctionProfile();
        if (c.contentManifestRoot != 0) {
            address gate = manager.phaseGate(c.collectionId, c.phaseId).gate;
            StreamPreparedNativeContentTypes.Publication memory p =
                IStreamNativeAuctionContentGate(gate).publication();
            StreamPreparedNativeContentReads.requirePublication(
                address(x.manager),
                StreamPreparedNativeSettlementValidation.addressWord(
                    address(x.manager), "moduleRegistry()"
                ),
                address(this),
                c.collectionId,
                c.phaseId,
                p.saleId,
                c.contentManifestRoot
            );
        }
        bytes32 current = manager.phasePolicyHash(c.collectionId, c.phaseId);
        if (current != c.mintPolicyHash) {
            (bytes32 prior, uint64 until) = manager.phasePolicyGrace(c.collectionId, c.phaseId);
            if (!live || prior != c.mintPolicyHash || block.timestamp > until) {
                revert IStreamNativeEnglishAuction.InvalidNativeAuction();
            }
        }
        if (
            live
                && (block.timestamp < phase.startTime
                    || (phase.endTime != 0 && block.timestamp > phase.endTime))
        ) revert IStreamNativeEnglishAuction.InvalidNativeAuction();
    }

    function profilePolicy(IStreamRevenueResolver resolver, uint256 collectionId)
        public
        view
        returns (bytes32)
    {
        IStreamRevenueResolver.ResolvedPrimaryAssignment memory a =
            resolver.resolvePrimaryAssignment(collectionId, 0, keccak256("PRIMARY_SALE"));
        if (
            !a.exists || a.assignmentType != 1 || a.scope != 1 || a.scopeId != collectionId
                || a.profileId == 0 || a.templateId != 0 || a.assignmentHash == 0
                || a.policyHash != 0
        ) revert IStreamNativeEnglishAuction.UnsupportedNativeAuctionProfile();
        return StreamSaleTemplate.policyHash(
            resolver, collectionId, StreamNativeSettlementSupport.rights(resolver, collectionId)
        );
    }

    function intent(IStreamNativeEnglishAuction.Auction memory a)
        public
        view
        returns (StreamPreparedNativeSettlementTypes.Intent memory i)
    {
        i.collectionId = a.config.collectionId;
        i.phaseId = a.config.phaseId;
        i.saleId = a.saleId;
        i.saleNonce = a.saleNonce;
        i.executor = a.winner.executor;
        i.payer = a.winner.payer;
        i.poster = a.config.poster;
        i.beneficiary = a.winner.deliverTo;
        i.amount = a.winner.amount;
        i.primaryPolicyMode = a.config.primaryPolicyMode;
        i.originalPrimaryPolicyHash = a.config.expectedPrimaryPolicyHash;
        i.executionNonce = a.winner.bidIndex;
        i.authorityMode = a.winner.signed ? 1 : 2;
        i.saleAuthorizationDigest = a.winner.authorizationDigest;
        i.saleExecutionHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_NATIVE_ENGLISH_AUCTION_EXECUTION_V1"),
                block.chainid,
                address(this),
                a.configHash,
                a.creationDigest,
                a.saleId,
                a.winner
            )
        );
        i.contentSelectionHash = a.config.artworkCommitment;
        i.mintCommitment = a.config.mintCommitment;
        i.boundMintPolicyHash = a.config.mintPolicyHash;
    }

    function batch(
        address manager,
        address recorder,
        StreamPreparedNativeSettlementTypes.Intent memory i,
        bytes memory artwork
    ) public view returns (IStreamMintManager.MintBatch memory b, bytes32 hash) {
        if (keccak256(artwork) != i.contentSelectionHash) {
            revert IStreamNativeEnglishAuction.NativeAuctionArtworkMismatch();
        }
        hash = StreamPreparedNativeSettlementHash.intentHash(address(this), recorder, i);
        b.collectionId = i.collectionId;
        b.phaseId = i.phaseId;
        b.payer = i.payer;
        b.initialRecipients = new address[](1);
        b.initialRecipients[0] = address(this);
        b.beneficiaries = new address[](1);
        b.beneficiaries[0] = i.beneficiary;
        b.tokenData = new bytes[](1);
        b.tokenData[0] = artwork;
        b.mintCommitments = new bytes32[](1);
        b.mintCommitments[0] = i.mintCommitment;
        b.expectedPolicyHash = i.boundMintPolicyHash;
        b.authorizationId = hash;
        b.contextHash = StreamPreparedNativeSettlementHash.mintContext(manager, address(this), hash);
    }
}

