// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/StreamDirectPrimaryConservationTypes.sol";

/// @notice Fixed linked storage and reconstruction worker for complete DIRECT floor history.
/// @dev Runs in the ledger's storage context. It does not authenticate a sale or read a former
/// adapter, Manager or provider; the ledger supplies authenticated evidence and immutable links.
library StreamConservationDirectHistory {
    // Member order and types preserve the original ledger's DirectPreparation storage layout.
    struct Preparation {
        bool exists;
        StreamDirectPrimaryConservationTypes.Receipt seed;
        bytes32 collectionEvidence;
        bytes32 releaseEvidence;
    }

    function persist(
        mapping(bytes32 => Preparation) storage preparations,
        Preparation memory p,
        uint256 chainId,
        address core
    ) public returns (bytes32 key) {
        key = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONSERVATION_DIRECT_PREPARED_V1"),
                chainId,
                core,
                address(this),
                p
            )
        );
        preparations[key] = p;
    }

    function receipt(
        Preparation storage p,
        uint64 recordedAt,
        bytes32 firstReceiptHash,
        bytes32 releaseReceiptHash,
        uint256 chainId,
        address core
    ) public view returns (StreamDirectPrimaryConservationTypes.Receipt memory r) {
        r = p.seed;
        r.recordedAt = recordedAt;
        r.firstSaleReceiptHash = firstReceiptHash;
        r.releaseReceiptHash = releaseReceiptHash;
        r.receiptHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONSERVATION_DIRECT_RECEIPT_V1"),
                chainId,
                core,
                address(this),
                r
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamConservationFloorReads.sol";
import "../revenue/StreamDirectPrimarySaleHash.sol";
import "../../interfaces/stream/revenue/IStreamDirectPrimarySaleReceipt.sol";
import "../../interfaces/stream/metadata/IStreamDirectPrimaryConservationFloor.sol";
import "../../interfaces/stream/mint/IStreamMintManager.sol";

/// @notice Bounded authentication of an original DIRECT adapter's actual immutable paid outcome.
/// @dev The admitted runtime validates the mint-returned vector before publishing its receipt.
/// Core exposes no token-to-operation getter: its independent proof here is completed collection
/// identity, joined with the original code-pinned Manager's used operation root.
library StreamConservationDirectReads {
    function requireReceipt(
        StreamConservationFloorReads.Context memory x,
        address adapter,
        bytes32 authorizationId
    )
        public
        view
        returns (
            StreamDirectPrimarySaleTypes.Bindings memory bindings,
            StreamDirectPrimarySaleTypes.Receipt memory sale,
            bytes32 key,
            bytes32 receiptHash
        )
    {
        (address registry,) = StreamConservationFloorReads.selected(x, keccak256("MODULE_REGISTRY"));
        uint256[14] memory row = _record(registry, adapter, x.readGas);
        _identity(adapter, row, x.readGas);
        bytes memory raw = StreamConservationFloorReads.read(
            adapter,
            abi.encodeCall(IStreamDirectPrimarySaleReceipt.directPrimaryBindings, ()),
            192,
            x.readGas
        );
        bindings = abi.decode(raw, (StreamDirectPrimarySaleTypes.Bindings));
        if (
            keccak256(raw) != keccak256(abi.encode(bindings)) || bindings.core != x.core
                || bindings.coreCodeHash != x.coreCodeHash
                || bindings.deploymentChainId != x.chainId
                || !StreamSettlementAdmission.isContract(bindings.mintManager)
                || bindings.mintManager.codehash != bindings.mintManagerCodeHash
                || StreamConservationFloorReads.word(
                        bindings.mintManager, abi.encodeWithSignature("core()"), x.readGas
                    ) != uint160(x.core)
                || (bindings.productKind != StreamDirectPrimarySaleTypes.NATIVE_FIXED_PRICE
                    && bindings.productKind != StreamDirectPrimarySaleTypes.ERC20_FIXED_PRICE
                    && bindings.productKind != StreamDirectPrimarySaleTypes.ENGLISH_AUCTION)
        ) revert IStreamConservationFloor.ConservationFloorAuthority(adapter);
        raw = StreamConservationFloorReads.read(
            adapter,
            abi.encodeCall(
                IStreamDirectPrimarySaleReceipt.directPrimarySaleReceipt, (authorizationId)
            ),
            512,
            x.readGas
        );
        sale = abi.decode(raw, (StreamDirectPrimarySaleTypes.Receipt));
        if (keccak256(raw) != keccak256(abi.encode(sale))) _mismatch(adapter, authorizationId);
        _paid(x, adapter, authorizationId, bindings, sale);
        if (
            sale.createdAt < row[10] || sale.createdAt > block.timestamp
                || sale.registryRevision > row[12]
                || (row[1] == 2
                    && (bindings.productKind != StreamDirectPrimarySaleTypes.ENGLISH_AUCTION
                        || sale.createdAt >= row[11]
                        || sale.registryRevision >= row[12]))
        ) revert IStreamConservationFloor.ConservationFloorAuthority(adapter);
        key = StreamDirectPrimarySaleHash.settlementKey(bindings, adapter, authorizationId);
        receiptHash =
            StreamDirectPrimarySaleHash.receiptHash(bindings, adapter, authorizationId, sale);
        if (
            bytes32(
                    StreamConservationFloorReads.word(
                        adapter,
                        abi.encodeCall(
                            IStreamDirectPrimarySaleReceipt.directPrimarySaleReceiptHash,
                            (authorizationId)
                        ),
                        x.readGas
                    )
                ) != receiptHash
        ) _mismatch(adapter, authorizationId);
    }

    function _paid(
        StreamConservationFloorReads.Context memory x,
        address adapter,
        bytes32 authorizationId,
        StreamDirectPrimarySaleTypes.Bindings memory bindings,
        StreamDirectPrimarySaleTypes.Receipt memory sale
    ) private view {
        if (
            authorizationId == 0 || sale.authorizationDigest == 0 || sale.collectionId == 0
                || sale.tokenId == 0 || sale.operationRoot == 0 || sale.operationId == 0
                || sale.boundMintPolicyHash == 0 || sale.expectedPrimaryPolicyHash == 0
                || sale.profileId == 0 || sale.wallet == address(0) || sale.payer == address(0)
                || sale.beneficiary == address(0) || sale.amount == 0 || sale.createdAt == 0
                || sale.registryRevision == 0
                || (bindings.productKind == StreamDirectPrimarySaleTypes.ERC20_FIXED_PRICE
                        ? !StreamSettlementAdmission.isContract(sale.asset)
                        : sale.asset != address(0))
                || StreamConservationFloorReads.word(
                        x.core,
                        abi.encodeCall(
                            IStreamCoreCollectionView.collectionExists, (sale.collectionId)
                        ),
                        x.readGas
                    ) != 1
                || StreamConservationFloorReads.word(
                        bindings.mintManager,
                        abi.encodeCall(
                            IStreamMintManager.isOperationRootUsed, (sale.operationRoot)
                        ),
                        x.readGas
                    ) != 1
                || StreamConservationFloorReads.word(
                        bindings.mintManager,
                        abi.encodeCall(IStreamMintManager.isAuthorizationUsed, (authorizationId)),
                        x.readGas
                    ) != 1
        ) _mismatch(adapter, authorizationId);
        StreamConservationFloorReads.requireToken(x, sale.collectionId, sale.tokenId, true);
    }

    function _identity(address adapter, uint256[14] memory row, uint256 cap) private view {
        bytes4 id = type(IStreamDirectPrimarySaleReceipt).interfaceId;
        if (
            bytes32(row[2]) != StreamDirectPrimarySaleTypes.MODULE_TYPE
                || bytes32(row[3]) != StreamDirectPrimarySaleTypes.MODULE_VERSION
                || row[4] != uint256(uint32(id)) << 224
                || StreamConservationFloorReads.word(
                        adapter, abi.encodeCall(IERC165.supportsInterface, (id)), cap
                    ) != 1
                || StreamConservationFloorReads.word(
                        adapter,
                        abi.encodeCall(IERC165.supportsInterface, (bytes4(0x01ffc9a7))),
                        cap
                    ) != 1
                || StreamConservationFloorReads.word(
                        adapter,
                        abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff))),
                        cap
                    ) != 0
        ) revert IStreamConservationFloor.ConservationFloorAuthority(adapter);
    }

    function _record(address registry, address adapter, uint256 cap)
        private
        view
        returns (uint256[14] memory row)
    {
        if (!StreamSettlementAdmission.isContract(adapter)) {
            revert IStreamConservationFloor.ConservationFloorAuthority(adapter);
        }
        bytes memory input = abi.encodeCall(IStreamModuleRegistry.moduleRecord, (adapter));
        if (cap == 0 || cap > type(uint64).max || gasleft() <= cap + cap / 63 + 10000) {
            revert IStreamConservationFloor.ConservationFloorRead(registry, bytes4(input));
        }
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, registry, add(input, 32), mload(input), row, 448)
            size := returndatasize()
        }
        // Bound the dynamic URI without copying its tail into the caller's memory.
        if (
            !ok || size < 448 || size > 4096 || row[0] != 32 || row[9] != 384
                || row[13] > size - 448 || size - 448 != ((row[13] + 31) / 32) * 32
                || (row[1] != 1 && row[1] != 2) || row[5] > type(uint32).max
                || bytes32(row[6]) != adapter.codehash || row[7] == 0 || row[8] == 0 || row[10] == 0
                || row[10] > block.timestamp || row[10] > type(uint64).max || row[11] < row[10]
                || row[11] > block.timestamp || row[11] > type(uint64).max || row[12] == 0
                || row[12] > type(uint64).max
        ) revert IStreamConservationFloor.ConservationFloorAuthority(adapter);
    }

    function _mismatch(address adapter, bytes32 authorizationId) private pure {
        revert IStreamDirectPrimaryConservationFloor.ConservationDirectSaleMismatch(
            adapter, authorizationId
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/IStreamConservationFloor.sol";
import "../../interfaces/stream/metadata/IStreamConservationFloorProvider.sol";
import "../../interfaces/stream/metadata/IStreamConservationFloorPreparation.sol";
import "../../interfaces/stream/metadata/IStreamDirectPrimaryConservationFloor.sol";
import "../../interfaces/stream/core/IStreamCoreConservationTier.sol";
import "../parameters/StreamGasParameterHost.sol";
import "./StreamMetadataGovernance.sol";
import "./StreamConservationTiers.sol";
import "./StreamConservationFloorReads.sol";
import "./StreamConservationFloorSupplemental.sol";
import "./StreamConservationDirectReads.sol";
import "./StreamConservationDirectHistory.sol";

/// @notice Permanent owner of successful first-sale and release-floor receipts.
/// @dev The current native source graph is admitted by exact delayed governance, never selected by
/// a payer or recorder. Historical source rows/receipts remain readable after every replacement.
contract StreamConservationFloor is
    StreamGasParameterHost,
    IStreamConservationFloor,
    IStreamConservationFloorPreparation,
    IStreamDirectPrimaryConservationFloor
{
    address public immutable override core;
    bytes32 public immutable override coreCodeHash;
    bytes32 public immutable override executorCodeHash;
    uint256 public immutable override deploymentChainId;
    bytes32 public constant READ_GAS = keccak256("6529STREAM_GGP_CONSERVATION_FLOOR_READ_GAS");
    bytes32 public constant PRODUCER_GAS =
        keccak256("6529STREAM_GGP_CONSERVATION_FLOOR_PRODUCER_GAS");
    bytes32 public constant CALL_GAS = keccak256("6529STREAM_GGP_CONSERVATION_FLOOR_CALL_GAS");
    bytes32 private constant SOURCE_DOMAIN = keccak256("6529STREAM_CONSERVATION_FLOOR_SOURCES_V1");
    bytes32 private constant WAIVED = keccak256("CONSERVATION_WAIVED");
    bytes32 private constant FULL = keccak256("MUSEUM_GRADE");
    uint8 private constant UNIVERSAL = 1;
    uint8 private constant DIRECT = 2;

    StreamConservationFloorTypes.Source[] private _sources;
    bytes32[] private _heads;

    struct CollectionPreparation {
        bool exists;
        uint256 collectionId;
        bytes32 tier;
        uint64 sourceId;
        bytes32 sourceSetHash;
        StreamConservationFloorTypes.CollectionFacts facts;
    }

    struct ReleasePreparation {
        bool exists;
        uint256 collectionId;
        bytes32 tier;
        uint64 sourceId;
        bytes32 sourceSetHash;
        bytes32 releaseKey;
        StreamConservationFloorTypes.ReleaseContext context;
        StreamConservationFloorTypes.ReleaseFacts facts;
    }

    struct SalePreparation {
        bool exists;
        StreamConservationFloorTypes.SettlementReceipt seed;
        bytes32 collectionEvidence;
        bytes32 releaseEvidence;
    }

    struct SaleLink {
        bytes32 preparation;
        uint64 recordedAt;
        uint8 family;
    }

    mapping(bytes32 => CollectionPreparation) private _collectionPreparations;
    mapping(bytes32 => ReleasePreparation) private _releasePreparations;
    mapping(bytes32 => SalePreparation) private _salePreparations;
    mapping(bytes32 => SaleLink) private _saleLinks;
    mapping(uint256 => bytes32) private _first;
    mapping(bytes32 => bytes32) private _release;
    bool private _entered;
    mapping(bytes32 => StreamConservationDirectHistory.Preparation) private _directPreparations;

    constructor(
        address core_,
        address executor_,
        GasParameterConfig memory readGas,
        GasParameterConfig memory producerGas,
        GasParameterConfig memory settlementCallGas
    ) StreamGasParameterHost(executor_) {
        if (
            !StreamSettlementAdmission.isContract(core_)
                || !StreamSettlementAdmission.isContract(executor_) || readGas.failureClass != 2
                || producerGas.failureClass != 2 || settlementCallGas.failureClass != 2
                || _registerGasParameter(readGas) != READ_GAS
                || _registerGasParameter(producerGas) != PRODUCER_GAS
                || _registerGasParameter(settlementCallGas) != CALL_GAS
        ) {
            revert InvalidConservationFloorConfiguration();
        }
        core = core_;
        coreCodeHash = core_.codehash;
        executorCodeHash = executor_.codehash;
        deploymentChainId = block.chainid;
        _heads.push(keccak256(abi.encode(SOURCE_DOMAIN, block.chainid, core_, address(this))));
    }

    modifier guarded() {
        if (_entered) revert ConservationFloorReentrant();
        _entered = true;
        _;
        _entered = false;
    }

    function supportsInterface(bytes4 id) external pure override returns (bool) {
        return id == type(IStreamConservationFloor).interfaceId
            || id == type(IStreamConservationFloorPreparation).interfaceId
            || id == type(IStreamDirectPrimaryConservationFloor).interfaceId
            || id == type(IStreamGasParameterHost).interfaceId || id == 0x01ffc9a7;
    }

    function sourceCount() public view override returns (uint64) {
        return uint64(_sources.length);
    }

    function sourceAt(uint64 id)
        external
        view
        override
        returns (StreamConservationFloorTypes.Source memory)
    {
        if (id == 0 || id > _sources.length) revert ConservationFloorSourceUnavailable();
        return _sources[id - 1];
    }

    function sourceSetHashAt(uint64 count) external view override returns (bytes32) {
        if (count > _sources.length) revert ConservationFloorSourceUnavailable();
        return _heads[count];
    }

    function sourceSetHead() public view override returns (uint64 count, bytes32 head) {
        count = sourceCount();
        head = _heads[count];
    }

    function sourceTransition(address metadata_, address provider, uint64 predecessor)
        public
        view
        override
        returns (bytes32 scope, bytes32 oldHash, bytes32 newHash)
    {
        StreamConservationFloorTypes.Source memory s =
            _validateSource(metadata_, provider, predecessor);
        scope = StreamMetadataGovernance.configurationScope(
            governanceAuthority, executorCodeHash, _gasParameterValue(READ_GAS), SOURCE_DOMAIN
        );
        (uint64 count, bytes32 head) = sourceSetHead();
        oldHash = _sourceState(count, head);
        newHash = _sourceState(count + 1, _nextSource(head, count + 1, s));
    }

    function appendSource(address metadata_, address provider, uint64 predecessor)
        external
        override
        guarded
    {
        (bytes32 scope, bytes32 oldHash, bytes32 newHash) =
            sourceTransition(metadata_, provider, predecessor);
        bytes32 actionId = StreamMetadataGovernance.requireTransition(
            governanceAuthority,
            executorCodeHash,
            _gasParameterValue(READ_GAS),
            scope,
            oldHash,
            newHash
        );
        StreamConservationFloorTypes.Source memory s =
            _validateSource(metadata_, provider, predecessor);
        uint64 id = sourceCount() + 1;
        bytes32 head = _nextSource(_heads[id - 1], id, s);
        s.admittedAt = uint64(block.timestamp);
        s.actionId = actionId;
        _sources.push(s);
        _heads.push(head);
        emit ConservationFloorSourceAdded(id, metadata_, provider, head, s, 1);
    }

    function firstSale(uint256 cid)
        external
        view
        override
        returns (StreamConservationFloorTypes.FirstSaleReceipt memory)
    {
        return _firstReceipt(cid);
    }

    function releaseFloorReceipt(bytes32 key)
        external
        view
        override
        returns (StreamConservationFloorTypes.ReleaseFloorReceipt memory)
    {
        return _releaseReceipt(key);
    }

    function settlementReceipt(bytes32 key)
        external
        view
        override
        returns (StreamConservationFloorTypes.SettlementReceipt memory)
    {
        return _settlementReceipt(key);
    }

    function directPrimarySaleFloorReceipt(bytes32 key)
        external
        view
        override
        returns (StreamDirectPrimaryConservationTypes.Receipt memory)
    {
        return _directReceipt(key);
    }

    function primarySalePrepared(bytes32 key) external view override returns (bool) {
        return _salePreparations[key].exists;
    }

    function preparePrimarySale(
        address recorder,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate calldata candidate,
        StreamPrimarySettlementTypes.PrimarySettlementResult calldata expectedResult
    ) external override guarded returns (bytes32 key) {
        StreamConservationFloorReads.Context memory x = _context();
        StreamConservationFloorReads.requireRecorder(x, recorder);
        // This deliberately does not require payment, consumed state, or an allocated future
        // prepared-mint token. Preparation is evidence storage, never a successful sale.
        StreamConservationFloorReads.requireProjection(
            x, recorder, candidate, expectedResult, false
        );
        (CollectionPreparation memory collection_, ReleasePreparation memory release_) =
            _universalEvidence(candidate, _tier(candidate.sale.collectionId), false);
        bytes32 collectionKey = keccak256(abi.encode(collection_));
        bytes32 releaseKey = release_.exists ? keccak256(abi.encode(release_)) : bytes32(0);
        SalePreparation memory p =
            _salePreparation(recorder, candidate, expectedResult, collectionKey, releaseKey);
        return _persistPreparation(p, collection_, release_);
    }

    function recordPrimarySale(
        StreamPrimarySettlementTypes.ERC20SettlementCandidate calldata candidate,
        StreamPrimarySettlementTypes.PrimarySettlementResult calldata result
    ) external override guarded returns (bytes32 receiptHash) {
        StreamConservationFloorReads.Context memory x = _context();
        StreamConservationFloorReads.requireRecorder(x, msg.sender);
        StreamConservationFloorReads.requireCandidate(x, msg.sender, candidate, result);
        if (_saleLinks[result.settlementKey].preparation != 0) {
            revert ConservationFloorAlreadyRecorded(result.settlementKey);
        }
        if (block.timestamp == 0 || block.timestamp > type(uint64).max) {
            revert ConservationFloorInvalidEvidence();
        }
        (CollectionPreparation memory collection_, ReleasePreparation memory release_) =
            _universalEvidence(candidate, _tier(candidate.sale.collectionId), true);
        SalePreparation memory p = _salePreparation(
            msg.sender,
            candidate,
            result,
            keccak256(abi.encode(collection_)),
            release_.exists ? keccak256(abi.encode(release_)) : bytes32(0)
        );
        // Preparation is an optimization. The original one-transaction purchase persists the
        // same genuine immutable evidence inline when absent, after all paid authentication.
        // Current source head and complete first/new-release facts determine the exact key;
        // an older preparation neither authorizes a sale nor substitutes its old evidence.
        bytes32 key = _persistPreparation(p, collection_, release_);
        _linkSale(result.settlementKey, key, UNIVERSAL, candidate.sale.collectionId, release_);
        StreamConservationFloorTypes.SettlementReceipt memory s =
            _settlementReceipt(result.settlementKey);
        emit ConservationSettlementRecorded(s.settlementKey, s.receiptHash, s, 1);
        return s.receiptHash;
    }

    function recordDirectPrimarySale(bytes32 authorizationId)
        external
        override
        guarded
        returns (bytes32 receiptHash)
    {
        (
            StreamDirectPrimarySaleTypes.Bindings memory bindings,
            StreamDirectPrimarySaleTypes.Receipt memory sale,
            bytes32 directKey,
            bytes32 originalHash
        ) = StreamConservationDirectReads.requireReceipt(_context(), msg.sender, authorizationId);
        if (_saleLinks[directKey].preparation != 0) {
            revert ConservationFloorAlreadyRecorded(directKey);
        }
        if (block.timestamp == 0 || block.timestamp > type(uint64).max) {
            revert ConservationFloorInvalidEvidence();
        }
        bytes32 tier = _tier(sale.collectionId);
        (CollectionPreparation memory collection_, ReleasePreparation memory release_) = _evidence(
            StreamConservationFloorTypes.SaleContext(
                sale.collectionId,
                sale.tokenId,
                msg.sender,
                authorizationId,
                sale.operationRoot,
                sale.operationId,
                sale.boundMintPolicyHash
            ),
            tier
        );
        StreamConservationDirectHistory.Preparation memory p;
        p.exists = true;
        p.collectionEvidence = keccak256(abi.encode(collection_));
        p.releaseEvidence = release_.exists ? keccak256(abi.encode(release_)) : bytes32(0);
        p.seed.adapter = msg.sender;
        p.seed.adapterCodeHash = msg.sender.codehash;
        p.seed.directKey = directKey;
        p.seed.authorizationId = authorizationId;
        p.seed.originalReceiptHash = originalHash;
        p.seed.bindings = bindings;
        p.seed.sale = sale;
        p.seed.effectiveTier = tier;
        _persistEvidence(p.collectionEvidence, p.releaseEvidence, collection_, release_);
        bytes32 preparation = StreamConservationDirectHistory.persist(
            _directPreparations, p, deploymentChainId, core
        );
        _linkSale(directKey, preparation, DIRECT, sale.collectionId, release_);
        StreamDirectPrimaryConservationTypes.Receipt memory r = _directReceipt(directKey);
        emit ConservationDirectPrimarySaleRecorded(directKey, r.receiptHash, r, 1);
        return r.receiptHash;
    }

    function _linkSale(
        bytes32 saleKey,
        bytes32 preparation,
        uint8 family,
        uint256 cid,
        ReleasePreparation memory release_
    ) private {
        _saleLinks[saleKey] = SaleLink(preparation, uint64(block.timestamp), family);
        if (_first[cid] == 0) {
            _first[cid] = saleKey;
            StreamConservationFloorTypes.FirstSaleReceipt memory f = _firstReceipt(cid);
            emit ConservationFirstSaleRecorded(cid, f.receiptHash, f, 1);
        }
        if (release_.exists && _release[release_.releaseKey] == 0) {
            _release[release_.releaseKey] = saleKey;
            StreamConservationFloorTypes.ReleaseFloorReceipt memory releaseReceipt =
                _releaseReceipt(release_.releaseKey);
            emit ConservationReleaseFloorRecorded(
                release_.releaseKey, releaseReceipt.receiptHash, releaseReceipt, 1
            );
        }
    }

    function requireSupplemental(
        StreamNativeSupplementalTypes.NativeSupplementalCandidate calldata candidate,
        StreamNativeSupplementalTypes.NativeSupplementalResult calldata result
    ) external view override returns (bytes32 originalReceiptHash) {
        StreamConservationFloorReads.Context memory x = _context();
        StreamConservationFloorReads.requireRecorder(x, msg.sender);
        StreamConservationFloorTypes.SettlementReceipt memory original =
            _settlementReceipt(candidate.purchase.floorSettlementKey);
        if (original.receiptHash == 0) {
            revert ConservationFloorOriginalReceiptMissing(candidate.purchase.floorSettlementKey);
        }
        if (
            _firstReceipt(original.collectionId).receiptHash != original.firstSaleReceiptHash
                || (original.effectiveTier != WAIVED && original.releaseReceiptHash == 0)
        ) revert ConservationFloorInvalidEvidence();
        StreamConservationFloorSupplemental.requireOriginal(x, original, candidate, result);
        return original.receiptHash;
    }

    function _salePreparation(
        address recorder,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate calldata c,
        StreamPrimarySettlementTypes.PrimarySettlementResult calldata r,
        bytes32 collectionKey,
        bytes32 releaseKey
    ) private view returns (SalePreparation memory p) {
        p.exists = true;
        p.collectionEvidence = collectionKey;
        p.releaseEvidence = releaseKey;
        p.seed.recorder = recorder;
        p.seed.recorderCodeHash = recorder.codehash;
        p.seed.settlementKey = r.settlementKey;
        p.seed.candidatePayloadHash = keccak256(abi.encode(c));
        p.seed.candidateCommitment = r.candidateCommitment;
        p.seed.resultHash = keccak256(abi.encode(r));
        p.seed.collectionId = c.sale.collectionId;
        p.seed.tokenId = c.sale.tokenId;
        p.seed.effectiveTier = _tier(c.sale.collectionId);
    }

    function _preparationHash(SalePreparation memory p) private view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_CONSERVATION_PREPARED_SALE_V1"),
                deploymentChainId,
                core,
                address(this),
                p
            )
        );
    }

    function _persistPreparation(
        SalePreparation memory p,
        CollectionPreparation memory collection_,
        ReleasePreparation memory release_
    ) private returns (bytes32 key) {
        key = _preparationHash(p);
        if (_salePreparations[key].exists) return key;
        _persistEvidence(p.collectionEvidence, p.releaseEvidence, collection_, release_);
        _salePreparations[key] = p;
        emit ConservationPrimarySalePrepared(
            key, p.seed.recorder, p.seed.settlementKey, p.collectionEvidence, p.releaseEvidence, 1
        );
    }

    function _persistEvidence(
        bytes32 collectionKey,
        bytes32 releaseKey,
        CollectionPreparation memory collection_,
        ReleasePreparation memory release_
    ) private {
        if (!_collectionPreparations[collectionKey].exists) {
            _collectionPreparations[collectionKey] = collection_;
        }
        if (release_.exists && !_releasePreparations[releaseKey].exists) {
            _releasePreparations[releaseKey] = release_;
        }
    }

    function _universalEvidence(
        StreamPrimarySettlementTypes.ERC20SettlementCandidate calldata c,
        bytes32 tier,
        bool paid
    )
        private
        view
        returns (CollectionPreparation memory collection_, ReleasePreparation memory release_)
    {
        StreamConservationFloorTypes.SaleContext memory
            sale = StreamConservationFloorTypes.SaleContext(
            c.sale.collectionId,
            c.sale.tokenId,
            c.saleAdapter,
            c.sale.settlementId,
            c.operationIdentityCommitment,
            c.operationId,
            c.boundPolicyHash
        );
        if (
            tier != WAIVED && !paid && c.orchestrationOrder == 2 && c.sale.tokenId != 0
                && StreamConservationFloorReads.word(
                        core,
                        abi.encodeCall(IStreamCoreIdentity.tokenLifecycle, (c.sale.tokenId)),
                        _gasParameterValue(READ_GAS)
                    ) == 0
        ) {
            // Only optional prospective preparation uses collection scope before allocation.
            // The exact original candidate remains seed-bound and paid entry uses its real token.
            sale.tokenId = 0;
        }
        return _evidence(sale, tier);
    }

    function _evidence(StreamConservationFloorTypes.SaleContext memory sale, bytes32 tier)
        private
        view
        returns (CollectionPreparation memory collection_, ReleasePreparation memory release_)
    {
        uint256 cid = sale.collectionId;
        bytes32 firstKey = _first[cid];
        if (firstKey != 0) {
            collection_ = _collectionPreparations[_collectionEvidenceFor(firstKey)];
            if (collection_.tier != tier) revert ConservationFloorInvalidEvidence();
        } else {
            collection_.exists = true;
            collection_.collectionId = cid;
            collection_.tier = tier;
            // Includes the actual paid source head, even when tier is WAIVED. A source append
            // selects fresh immutable evidence and never rewrites the prior preparation.
            collection_.sourceSetHash = _heads[sourceCount()];
        }
        if (tier == WAIVED) return (collection_, release_);
        (uint64 sourceId, StreamConservationFloorTypes.Source memory source) = _currentSource();
        if (firstKey == 0) {
            collection_.sourceId = sourceId;
            collection_.facts = _collection(source, cid, tier);
        }
        release_ = _releaseEvidence(sourceId, source, sale, tier);
    }

    function _releaseEvidence(
        uint64 sourceId,
        StreamConservationFloorTypes.Source memory source,
        StreamConservationFloorTypes.SaleContext memory sale,
        bytes32 tier
    ) private view returns (ReleasePreparation memory p) {
        bytes memory raw = _producer(
            source, abi.encodeCall(IStreamConservationFloorProvider.saleRelease, (sale)), 192
        );
        StreamConservationFloorTypes.ReleaseContext memory release =
            abi.decode(raw, (StreamConservationFloorTypes.ReleaseContext));
        if (
            keccak256(raw) != keccak256(abi.encode(release)) || release.scopeSubject == 0
                || release.membershipHash == 0 || release.mediaInventoryHash == 0
                || release.sourceContextHash == 0
                || release.scriptWork != (release.scriptSourceHash != 0)
        ) revert ConservationFloorInvalidEvidence();
        bytes32 key = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONSERVATION_RELEASE_V1"),
                deploymentChainId,
                core,
                sale.collectionId,
                release.scopeSubject,
                release.membershipHash,
                release.mediaInventoryHash,
                release.scriptSourceHash,
                release.scriptWork
            )
        );
        bytes32 previous = _release[key];
        if (previous != 0) {
            // Current sale-to-release mapping was just re-proved. Historical successful
            // evidence for identical semantic content remains the immutable denominator.
            p = _releasePreparations[_releaseEvidenceFor(previous)];
            if (p.tier != tier || p.collectionId != sale.collectionId) {
                revert ConservationFloorInvalidEvidence();
            }
            return p;
        }
        raw = _producer(
            source,
            abi.encodeCall(
                IStreamConservationFloorProvider.requireReleaseFloor, (sale, release, tier)
            ),
            96
        );
        p.facts = abi.decode(raw, (StreamConservationFloorTypes.ReleaseFacts));
        if (
            keccak256(raw) != keccak256(abi.encode(p.facts))
                || p.facts.sourceContextHash != release.sourceContextHash
                || p.facts.mediaEvidenceHash == 0
                || (tier == FULL && release.scriptWork && p.facts.referenceEvidenceHash == 0)
                || (!release.scriptWork && p.facts.referenceEvidenceHash != 0)
        ) revert ConservationFloorInvalidEvidence();
        p.exists = true;
        p.collectionId = sale.collectionId;
        p.tier = tier;
        p.sourceId = sourceId;
        p.sourceSetHash = _heads[sourceId];
        p.releaseKey = key;
        p.context = release;
    }

    function _firstReceipt(uint256 cid)
        private
        view
        returns (StreamConservationFloorTypes.FirstSaleReceipt memory f)
    {
        bytes32 key = _first[cid];
        if (key == 0) return f;
        SaleLink memory link = _saleLinks[key];
        CollectionPreparation storage p = _collectionPreparations[_collectionEvidenceFor(key)];
        f.collectionId = p.collectionId;
        f.effectiveTier = p.tier;
        f.recorder = _originFor(key);
        f.settlementKey = key;
        f.recordedAt = link.recordedAt;
        f.sourceId = p.sourceId;
        f.sourceSetHash = p.sourceSetHash;
        f.facts = p.facts;
        f.receiptHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONSERVATION_FIRST_SALE_V1"),
                deploymentChainId,
                core,
                address(this),
                f
            )
        );
    }

    function _releaseReceipt(bytes32 semanticKey)
        private
        view
        returns (StreamConservationFloorTypes.ReleaseFloorReceipt memory r)
    {
        bytes32 key = _release[semanticKey];
        if (key == 0) return r;
        SaleLink memory link = _saleLinks[key];
        ReleasePreparation storage p = _releasePreparations[_releaseEvidenceFor(key)];
        r.releaseKey = p.releaseKey;
        r.collectionId = p.collectionId;
        r.effectiveTier = p.tier;
        r.recorder = _originFor(key);
        r.settlementKey = key;
        r.recordedAt = link.recordedAt;
        r.sourceId = p.sourceId;
        r.sourceSetHash = p.sourceSetHash;
        r.context = p.context;
        r.facts = p.facts;
        r.receiptHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONSERVATION_RELEASE_RECEIPT_V1"),
                deploymentChainId,
                core,
                address(this),
                r
            )
        );
    }

    function _settlementReceipt(bytes32 key)
        private
        view
        returns (StreamConservationFloorTypes.SettlementReceipt memory s)
    {
        SaleLink memory link = _saleLinks[key];
        if (link.preparation == 0 || link.family != UNIVERSAL) return s;
        SalePreparation storage p = _salePreparations[link.preparation];
        s = p.seed;
        s.recordedAt = link.recordedAt;
        s.firstSaleReceiptHash = _firstReceipt(s.collectionId).receiptHash;
        if (p.releaseEvidence != 0) {
            s.releaseReceiptHash =
            _releaseReceipt(_releasePreparations[p.releaseEvidence].releaseKey).receiptHash;
        }
        s.receiptHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONSERVATION_SETTLEMENT_RECEIPT_V1"),
                deploymentChainId,
                core,
                address(this),
                s
            )
        );
    }

    function _directReceipt(bytes32 key)
        private
        view
        returns (StreamDirectPrimaryConservationTypes.Receipt memory r)
    {
        SaleLink memory link = _saleLinks[key];
        if (link.preparation == 0 || link.family != DIRECT) return r;
        StreamConservationDirectHistory.Preparation storage p =
            _directPreparations[link.preparation];
        bytes32 releaseReceiptHash;
        if (p.releaseEvidence != 0) {
            releaseReceiptHash =
            _releaseReceipt(_releasePreparations[p.releaseEvidence].releaseKey).receiptHash;
        }
        return StreamConservationDirectHistory.receipt(
            p,
            link.recordedAt,
            _firstReceipt(p.seed.sale.collectionId).receiptHash,
            releaseReceiptHash,
            deploymentChainId,
            core
        );
    }

    function _collectionEvidenceFor(bytes32 key) private view returns (bytes32) {
        SaleLink memory link = _saleLinks[key];
        if (link.family == UNIVERSAL) {
            return _salePreparations[link.preparation].collectionEvidence;
        }
        if (link.family == DIRECT) return _directPreparations[link.preparation].collectionEvidence;
        revert ConservationFloorInvalidEvidence();
    }

    function _releaseEvidenceFor(bytes32 key) private view returns (bytes32) {
        SaleLink memory link = _saleLinks[key];
        if (link.family == UNIVERSAL) return _salePreparations[link.preparation].releaseEvidence;
        if (link.family == DIRECT) return _directPreparations[link.preparation].releaseEvidence;
        revert ConservationFloorInvalidEvidence();
    }

    function _originFor(bytes32 key) private view returns (address) {
        SaleLink memory link = _saleLinks[key];
        if (link.family == UNIVERSAL) return _salePreparations[link.preparation].seed.recorder;
        if (link.family == DIRECT) return _directPreparations[link.preparation].seed.adapter;
        revert ConservationFloorInvalidEvidence();
    }

    function _collection(
        StreamConservationFloorTypes.Source memory source,
        uint256 cid,
        bytes32 tier
    ) private view returns (StreamConservationFloorTypes.CollectionFacts memory f) {
        bytes memory raw = _producer(
            source,
            abi.encodeCall(IStreamConservationFloorProvider.requireCollectionFloor, (cid, tier)),
            256
        );
        f = abi.decode(raw, (StreamConservationFloorTypes.CollectionFacts));
        if (keccak256(raw) != keccak256(abi.encode(f)) || f.rightsRecordHash == 0) {
            revert ConservationFloorInvalidEvidence();
        }
        if (f.platformWorks) {
            if (
                f.artistId != 0 || f.identityRecordHash != 0 || f.intentRecordHash != 0
                    || f.intentWaiverRecordHash != 0 || f.interviewEvidenceHash != 0
                    || f.personhoodEvidenceHash != 0
            ) revert ConservationFloorInvalidEvidence();
        } else if (
            f.artistId == 0 || f.identityRecordHash == 0
                || (f.intentRecordHash == 0) == (f.intentWaiverRecordHash == 0)
                || f.interviewEvidenceHash == 0 || f.personhoodEvidenceHash == 0
        ) {
            revert ConservationFloorInvalidEvidence();
        }
    }

    function _tier(uint256 cid) private view returns (bytes32 declared) {
        declared = bytes32(
            StreamConservationFloorReads.word(
                core,
                abi.encodeCall(IStreamCoreConservationTier.declaredConservationTier, (cid)),
                _gasParameterValue(READ_GAS)
            )
        );
        // Sale payment may precede completed minting. Absence prospectively bears the lite floor.
        if (declared == 0) return keccak256("MUSEUM_GRADE_LITE");
        StreamConservationTiers.requireKnown(declared);
    }

    function _currentSource()
        private
        view
        returns (uint64 id, StreamConservationFloorTypes.Source memory s)
    {
        id = sourceCount();
        if (id == 0) revert ConservationFloorSourceUnavailable();
        s = _sources[id - 1];
        _providerIdentity(s);
    }

    function _validateSource(address metadata_, address provider, uint64 predecessor)
        private
        view
        returns (StreamConservationFloorTypes.Source memory s)
    {
        _context();
        if (
            predecessor != _sources.length || _sources.length == type(uint64).max
                || block.timestamp == 0 || block.timestamp > type(uint64).max
                || !StreamSettlementAdmission.isContract(metadata_)
                || !StreamSettlementAdmission.isContract(provider)
        ) revert ConservationFloorSourceUnavailable();
        s.metadata = metadata_;
        s.metadataCodeHash = metadata_.codehash;
        s.provider = provider;
        s.providerCodeHash = provider.codehash;
        s.predecessor = predecessor;
        s.configurationHash = bytes32(
            StreamConservationFloorReads.word(
                provider,
                abi.encodeCall(IStreamConservationFloorProvider.configurationHash, ()),
                _gasParameterValue(READ_GAS)
            )
        );
        _providerIdentity(s);
        if (_sources.length != 0) {
            StreamConservationFloorTypes.Source memory previous = _sources[_sources.length - 1];
            if (previous.metadata == metadata_ && previous.provider == provider) {
                revert ConservationFloorSourceUnavailable();
            }
        }
    }

    function _providerIdentity(StreamConservationFloorTypes.Source memory s) private view {
        uint256 cap = _gasParameterValue(READ_GAS);
        (address metadata_, bytes32 metadataHash) = StreamConservationFloorReads.selected(
            _readContext(), keccak256("COLLECTION_METADATA")
        );
        if (
            s.metadata != metadata_ || s.metadataCodeHash != metadataHash
                || s.provider.code.length == 0 || s.provider.codehash != s.providerCodeHash
                || s.configurationHash == 0
                || StreamConservationFloorReads.word(
                        s.provider, abi.encodeCall(IStreamConservationFloorProvider.core, ()), cap
                    ) != uint160(core)
                || bytes32(
                        StreamConservationFloorReads.word(
                            s.provider,
                            abi.encodeCall(IStreamConservationFloorProvider.coreCodeHash, ()),
                            cap
                        )
                    ) != coreCodeHash
                || StreamConservationFloorReads.word(
                        s.provider,
                        abi.encodeCall(IStreamConservationFloorProvider.metadata, ()),
                        cap
                    ) != uint160(s.metadata)
                || bytes32(
                        StreamConservationFloorReads.word(
                            s.provider,
                            abi.encodeCall(IStreamConservationFloorProvider.metadataCodeHash, ()),
                            cap
                        )
                    ) != s.metadataCodeHash
                || bytes32(
                        StreamConservationFloorReads.word(
                            s.provider,
                            abi.encodeCall(IStreamConservationFloorProvider.configurationHash, ()),
                            cap
                        )
                    ) != s.configurationHash
                || StreamConservationFloorReads.word(
                        s.provider,
                        abi.encodeCall(IStreamConservationFloorProvider.deploymentChainId, ()),
                        cap
                    ) != deploymentChainId
                || StreamConservationFloorReads.word(
                        s.provider,
                        abi.encodeCall(
                            IERC165.supportsInterface,
                            (type(IStreamConservationFloorProvider).interfaceId)
                        ),
                        cap
                    ) != 1
                || StreamConservationFloorReads.word(
                        s.provider,
                        abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff))),
                        cap
                    ) != 0
        ) revert ConservationFloorSourceUnavailable();
    }

    function _producer(
        StreamConservationFloorTypes.Source memory s,
        bytes memory input,
        uint256 size
    ) private view returns (bytes memory) {
        return StreamConservationFloorReads.read(
            s.provider, input, size, _gasParameterValue(PRODUCER_GAS)
        );
    }

    function _sourceState(uint64 count, bytes32 head) private view returns (bytes32) {
        return
            keccak256(
                abi.encode(SOURCE_DOMAIN, deploymentChainId, core, address(this), count, head)
            );
    }

    function _nextSource(bytes32 head, uint64 id, StreamConservationFloorTypes.Source memory s)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                SOURCE_DOMAIN,
                head,
                id,
                s.metadata,
                s.metadataCodeHash,
                s.provider,
                s.providerCodeHash,
                s.configurationHash,
                s.predecessor
            )
        );
    }

    function _readContext() private view returns (StreamConservationFloorReads.Context memory) {
        return StreamConservationFloorReads.Context(
            core, coreCodeHash, deploymentChainId, _gasParameterValue(READ_GAS)
        );
    }

    function _context() private view returns (StreamConservationFloorReads.Context memory x) {
        x = _readContext();
        StreamConservationFloorReads.requireBound(x);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/IStreamConservationFloor.sol";
import "../../interfaces/stream/metadata/IStreamConservationFloorProvider.sol";
import "../../interfaces/stream/core/IStreamCorePointers.sol";
import "../../interfaces/stream/core/IStreamCoreCollectionView.sol";
import "../../interfaces/stream/core/IStreamCoreIdentity.sol";
import "../../interfaces/stream/revenue/IStreamPrimarySaleSettlement.sol";
import "../../interfaces/stream/revenue/IStreamPreparedNativePrimarySaleSettlement.sol";
import "../../interfaces/stream/revenue/IStreamNativeSaleBinding.sol";
import "../revenue/StreamPrimarySettlementHash.sol";
import "../revenue/StreamSettlementAdmission.sol";

/// @notice Bounded exact reads and native recorder admission for the permanent floor ledger.
library StreamConservationFloorReads {
    struct Context {
        address core;
        bytes32 coreCodeHash;
        uint256 chainId;
        uint256 readGas;
    }

    function requireBound(Context memory x) public view {
        if (
            block.chainid != x.chainId || x.core.code.length == 0
                || x.core.codehash != x.coreCodeHash
        ) revert IStreamConservationFloor.ConservationFloorDependency(x.core);
        bytes memory raw =
            read(x.core, abi.encodeWithSignature("conservationFloor()"), 64, x.readGas);
        (address host, bytes32 codeHash) = abi.decode(raw, (address, bytes32));
        if (
            keccak256(raw) != keccak256(abi.encode(host, codeHash)) || host != address(this)
                || codeHash != address(this).codehash
        ) revert IStreamConservationFloor.ConservationFloorNotBound();
    }

    function selected(Context memory x, bytes32 kind)
        public
        view
        returns (address target, bytes32 codeHash)
    {
        bytes memory raw = read(
            x.core, abi.encodeCall(IStreamCorePointers.getSatellitePointer, (kind)), 320, x.readGas
        );
        uint256[10] memory w = abi.decode(raw, (uint256[10]));
        if (
            w[0] > type(uint160).max || w[2] > 1 || bytes32(w[3]) != kind
                || (w[4] & type(uint224).max) != 0 || w[5] > type(uint160).max || w[6] != 1
                || w[7] == 0 || w[8] == 0 || w[9] == 0 || w[9] > type(uint64).max
        ) revert IStreamConservationFloor.ConservationFloorDependency(x.core);
        target = address(uint160(w[0]));
        codeHash = bytes32(w[1]);
        if (!StreamSettlementAdmission.isContract(target) || target.codehash != codeHash) {
            revert IStreamConservationFloor.ConservationFloorDependency(target);
        }
    }

    function requireRecorder(Context memory x, address recorder) public view {
        (address registry, bytes32 registryHash) = selected(x, keccak256("MODULE_REGISTRY"));
        if (
            !StreamSettlementAdmission.isContract(recorder)
                || word(recorder, abi.encodeWithSignature("core()"), x.readGas) != uint160(x.core)
                || bytes32(word(recorder, abi.encodeWithSignature("coreCodeHash()"), x.readGas))
                    != x.coreCodeHash
                || word(recorder, abi.encodeWithSignature("moduleRegistry()"), x.readGas)
                    != uint160(registry)
                || bytes32(
                        word(
                            recorder, abi.encodeWithSignature("moduleRegistryCodeHash()"), x.readGas
                        )
                    ) != registryHash
        ) revert IStreamConservationFloor.ConservationFloorAuthority(recorder);
        _recorderRecord(registry, recorder, x.readGas);
    }

    function _recorderRecord(address registry, address recorder, uint256 cap) private view {
        uint256[14] memory w = _moduleRecord(registry, recorder, cap);
        if (bytes32(w[2]) != keccak256("PRIMARY_SALE_SETTLEMENT")) {
            revert IStreamConservationFloor.ConservationFloorAuthority(recorder);
        }
        bytes4 id;
        if (bytes32(w[3]) == keccak256("6529STREAM_UNIVERSAL_SETTLEMENT_V1")) {
            id = type(IStreamPrimarySaleSettlement).interfaceId;
        } else if (bytes32(w[3]) == keccak256("6529STREAM_PREPARED_NATIVE_SETTLEMENT_V1")) {
            id = type(IStreamPreparedNativePrimarySaleSettlement).interfaceId;
        } else {
            revert IStreamConservationFloor.ConservationFloorAuthority(recorder);
        }
        _moduleInterface(recorder, w[4], id, cap);
        // DEPRECATED recorders keep their own exact operation-lifecycle admission. The floor
        // does not grant new sale creation rights or replace those original checks.
    }

    function requireNativeSale(
        Context memory x,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) public view {
        (address registry,) = selected(x, keccak256("MODULE_REGISTRY"));
        uint256[14] memory w = _moduleRecord(registry, c.saleAdapter, x.readGas);
        if (
            bytes32(w[2]) != keccak256("NATIVE_PRIMARY_SALE_ADAPTER")
                || bytes32(w[3]) != keccak256("6529STREAM_UNIVERSAL_SETTLEMENT_V1")
        ) {
            revert IStreamConservationFloor.ConservationFloorAuthority(c.saleAdapter);
        }
        _moduleInterface(c.saleAdapter, w[4], type(IStreamNativeSaleBinding).interfaceId, x.readGas);
        bytes memory raw = read(
            c.saleAdapter,
            abi.encodeCall(
                IStreamNativeSaleBinding.nativeSaleLifecycleBinding, (c.sale.settlementId)
            ),
            64,
            x.readGas
        );
        if (
            keccak256(raw) != keccak256(abi.encode(c.lifecycleBinding))
                || c.lifecycleBinding.saleCreatedAt == 0
                || c.lifecycleBinding.saleCreatedAt > block.timestamp
                || c.lifecycleBinding.saleCreatedAt < w[10]
                || c.lifecycleBinding.saleAdapterRegistryRevision == 0
                || c.lifecycleBinding.saleAdapterRegistryRevision > w[12]
                || (w[1] == 2
                    && (c.lifecycleBinding.saleCreatedAt >= w[11]
                        || c.lifecycleBinding.saleAdapterRegistryRevision >= w[12]))
        ) {
            revert IStreamConservationFloor.ConservationFloorAuthority(c.saleAdapter);
        }
    }

    function _moduleRecord(address registry, address module, uint256 cap)
        private
        view
        returns (uint256[14] memory w)
    {
        if (!StreamSettlementAdmission.isContract(module)) {
            revert IStreamConservationFloor.ConservationFloorAuthority(module);
        }
        bytes memory input = abi.encodeCall(IStreamModuleRegistry.moduleRecord, (module));
        bool ok;
        uint256 size;
        _gas(registry, bytes4(input), cap);
        assembly ("memory-safe") {
            ok := staticcall(cap, registry, add(input, 32), mload(input), w, 448)
            size := returndatasize()
        }
        // A single dynamic tuple with twelve fixed fields and its bounded URI tail.
        if (
            !ok || size < 448 || size > 4096 || w[0] != 32 || w[9] != 384 || w[13] > size - 448
                || size - 448 != ((w[13] + 31) / 32) * 32 || (w[1] != 1 && w[1] != 2)
                || w[5] > type(uint32).max || bytes32(w[6]) != module.codehash || w[7] == 0
                || w[8] == 0 || w[10] == 0 || w[10] > block.timestamp || w[10] > type(uint64).max
                || w[11] > type(uint64).max || w[11] < w[10] || w[11] > block.timestamp
                || w[12] == 0 || w[12] > type(uint64).max
        ) revert IStreamConservationFloor.ConservationFloorAuthority(module);
    }

    function _moduleInterface(address module, uint256 encodedId, bytes4 id, uint256 cap)
        private
        view
    {
        if (
            encodedId != uint256(uint32(id)) << 224
                || word(module, abi.encodeCall(IERC165.supportsInterface, (id)), cap) != 1
                || word(
                        module, abi.encodeCall(IERC165.supportsInterface, (bytes4(0x01ffc9a7))), cap
                    ) != 1
                || word(
                        module, abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff))), cap
                    ) != 0
        ) revert IStreamConservationFloor.ConservationFloorAuthority(module);
    }

    function requireCandidate(
        Context memory x,
        address recorder,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory r
    ) public view {
        requireProjection(x, recorder, c, r, true);
        requireStoredResult(x, recorder, r);
    }

    /// @dev Preparation may name a future prepared-mint identity. Only the paid entry proves it
    /// allocated; custody always requires an already completed original token.
    function requireProjection(
        Context memory x,
        address recorder,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory r,
        bool paid
    ) public view {
        if (
            c.sale.collectionId == 0 || c.sale.revenueClass != keccak256("PRIMARY_SALE")
                || c.sale.settlementId == 0 || c.sale.saleNonce == 0 || c.sale.payer == address(0)
                || c.sale.beneficiary == address(0) || c.sale.amount == 0
                || c.sale.expectedPrimaryPolicyHash == 0 || c.saleAdapter == address(0)
                || c.executor == address(0) || c.executionBinding.executionId == 0
                || c.saleExecutionHash == 0 || r.candidateCommitment == 0
                || r.settlementKey
                    != StreamPrimarySettlementHash.settlementKey(
                        recorder, c.saleAdapter, c.executionBinding.executionId
                    ) || r.amount != c.sale.amount || r.asset != c.asset || r.executor != c.executor
                || r.executionId != c.executionBinding.executionId || r.profileId == 0
                || r.wallet == address(0) || r.profileId != c.rights.profileId
                || r.wallet != c.rights.wallet
                || r.operationIdentityCommitment != c.operationIdentityCommitment
                || r.currentPolicyHash != c.currentPolicyHash
                || r.boundPolicyHash != c.boundPolicyHash
                || word(
                        x.core,
                        abi.encodeCall(
                            IStreamCoreCollectionView.collectionExists, (c.sale.collectionId)
                        ),
                        x.readGas
                    ) != 1
        ) revert IStreamConservationFloor.ConservationFloorSettlementMismatch(r.settlementKey);
        if (c.orchestrationOrder == 1 || c.orchestrationOrder == 2) {
            if (
                c.operationIdentityCommitment == 0 || c.operationId == 0 || c.currentPolicyHash == 0
                    || c.boundPolicyHash == 0
                    || !StreamSettlementAdmission.isContract(c.mintManager)
                    || word(c.mintManager, abi.encodeWithSignature("core()"), x.readGas)
                        != uint160(x.core) || (c.orchestrationOrder == 1 && c.sale.tokenId != 0)
            ) revert IStreamConservationFloor.ConservationFloorSettlementMismatch(r.settlementKey);
        } else if (c.orchestrationOrder == 3) {
            if (
                c.sale.tokenId == 0 || c.mintManager != address(0)
                    || c.operationIdentityCommitment != 0 || c.operationId != 0
                    || c.currentPolicyHash != 0 || c.boundPolicyHash != 0
            ) revert IStreamConservationFloor.ConservationFloorSettlementMismatch(r.settlementKey);
        } else {
            revert IStreamConservationFloor.ConservationFloorSettlementMismatch(r.settlementKey);
        }
        if (c.sale.tokenId != 0 && (paid || c.orchestrationOrder == 3)) {
            requireToken(x, c.sale.collectionId, c.sale.tokenId, c.orchestrationOrder == 3);
        }
    }

    function requireToken(Context memory x, uint256 cid, uint256 token, bool completed)
        public
        view
    {
        bytes memory raw = read(
            x.core,
            abi.encodeCall(IStreamCoreIdentity.tokenCollectionIdentity, (token)),
            128,
            x.readGas
        );
        (bool exists, uint256 collection, uint256 serial, bool burned) =
            abi.decode(raw, (bool, uint256, uint256, bool));
        uint256 lifecycle =
            word(x.core, abi.encodeCall(IStreamCoreIdentity.tokenLifecycle, (token)), x.readGas);
        if (
            keccak256(raw) != keccak256(abi.encode(exists, collection, serial, burned)) || !exists
                || collection != cid || serial == 0 || lifecycle == 0 || lifecycle > 3
                || (completed && lifecycle < 2) || burned != (lifecycle == 3)
        ) revert IStreamConservationFloor.ConservationFloorInvalidEvidence();
    }

    function requireStoredResult(
        Context memory x,
        address recorder,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory r
    ) public view {
        if (
            word(
                        recorder,
                        abi.encodeCall(
                            IStreamPrimarySaleSettlement.settlementConsumed, (r.settlementKey)
                        ),
                        x.readGas
                    ) != 1
                || keccak256(
                        read(
                            recorder,
                            abi.encodeCall(
                                IStreamPrimarySaleSettlement.settlementResult, (r.settlementKey)
                            ),
                            384,
                            x.readGas
                        )
                    ) != keccak256(abi.encode(r))
        ) {
            revert IStreamConservationFloor.ConservationFloorSettlementMismatch(r.settlementKey);
        }
    }

    function word(address target, bytes memory input, uint256 cap) internal view returns (uint256) {
        return abi.decode(read(target, input, 32, cap), (uint256));
    }

    function read(address target, bytes memory input, uint256 size, uint256 cap)
        public
        view
        returns (bytes memory output)
    {
        _gas(target, bytes4(input), cap);
        output = new bytes(size);
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(output, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) {
            revert IStreamConservationFloor.ConservationFloorRead(target, bytes4(input));
        }
    }

    function _gas(address target, bytes4 selector, uint256 cap) private view {
        if (cap == 0 || cap > type(uint64).max || gasleft() <= cap + cap / 63 + 10000) {
            revert IStreamConservationFloor.ConservationFloorRead(target, selector);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamConservationFloorReads.sol";
import "../revenue/StreamNativeSettlementHash.sol";
import "../revenue/StreamNativeSupplementalHash.sol";
import "../../interfaces/stream/revenue/IStreamNativeClearingSaleBinding.sol";
import "../../interfaces/stream/revenue/IStreamNativeSupplementalSettlement.sol";

/// @notice Exact native purchase joins for supplemental payments against an immutable floor receipt.
/// @dev Runs in the permanent ledger, after the admitted recorder has stored both consumed results.
library StreamConservationFloorSupplemental {
    function requireOriginal(
        StreamConservationFloorReads.Context memory x,
        StreamConservationFloorTypes.SettlementReceipt memory original,
        StreamNativeSupplementalTypes.NativeSupplementalCandidate memory c,
        StreamNativeSupplementalTypes.NativeSupplementalResult memory r
    ) public view {
        _original(x, original, c);
        _result(x, c, r);
        _purchase(x, c, r);
    }

    function _original(
        StreamConservationFloorReads.Context memory x,
        StreamConservationFloorTypes.SettlementReceipt memory original,
        StreamNativeSupplementalTypes.NativeSupplementalCandidate memory c
    ) private view {
        StreamNativeSettlementTypes.NativeSettlementCandidate memory n = c.originalFloor;
        bytes32 commitment = StreamNativeSettlementHash.candidateCommitment(msg.sender, n);
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            msg.sender, n.saleAdapter, n.executionBinding.executionId
        );
        if (
            original.recorder != msg.sender || original.recorderCodeHash != msg.sender.codehash
                || original.collectionId != n.sale.collectionId || original.tokenId != 0
                || original.settlementKey != key || key != c.purchase.floorSettlementKey
                || original.candidateCommitment != commitment
                || commitment != c.purchase.floorCandidateCommitment
                || original.candidatePayloadHash
                    != keccak256(abi.encode(StreamNativeSettlementHash.accountingContext(n)))
                || n.sale.revenueClass != keccak256("PRIMARY_SALE") || n.sale.policyMode != 0
                || n.sale.tokenId != 0 || n.sale.collectionId == 0 || n.orchestrationOrder != 1
                || n.executionBinding.executionId != StreamNativeSettlementHash.executionId(n)
        ) revert IStreamConservationFloor.ConservationFloorSettlementMismatch(key);
        bytes memory raw = StreamConservationFloorReads.read(
            msg.sender,
            abi.encodeCall(IStreamPrimarySaleSettlement.settlementResult, (key)),
            384,
            x.readGas
        );
        StreamPrimarySettlementTypes.PrimarySettlementResult memory previous =
            abi.decode(raw, (StreamPrimarySettlementTypes.PrimarySettlementResult));
        if (
            keccak256(raw) != original.resultHash
                || keccak256(raw) != keccak256(abi.encode(previous))
        ) {
            revert IStreamConservationFloor.ConservationFloorSettlementMismatch(key);
        }
        // Reuses exact field/result checks, including native asset zero and the same collection.
        StreamConservationFloorReads.requireCandidate(
            x, msg.sender, StreamNativeSettlementHash.accountingContext(n), previous
        );
    }

    function _result(
        StreamConservationFloorReads.Context memory x,
        StreamNativeSupplementalTypes.NativeSupplementalCandidate memory c,
        StreamNativeSupplementalTypes.NativeSupplementalResult memory r
    ) private view {
        bytes32 executionId = StreamNativeSupplementalHash.executionId(msg.sender, c);
        if (
            r.candidateCommitment != StreamNativeSupplementalHash.candidateCommitment(msg.sender, c)
                || r.settlementKey
                    != StreamPrimarySettlementHash.settlementKey(
                        msg.sender, c.originalFloor.saleAdapter, executionId
                    ) || r.executionId != executionId || r.purchaseId != c.purchaseId
                || r.originalFloorSettlementKey != c.purchase.floorSettlementKey
                || r.tokenId != c.purchase.tokenId || r.profileId == 0 || r.wallet == address(0)
                || r.profileId != c.currentRights.profileId || r.wallet != c.currentRights.wallet
                || r.executor != c.executor || c.executor == address(0)
                || r.originalOperationRoot != c.originalFloor.operationIdentityCommitment
                || r.originalOperationId != c.originalFloor.operationId
                || r.originalExpectedPrimaryPolicyHash
                    != c.originalFloor.sale.expectedPrimaryPolicyHash
                || r.currentPrimaryPolicyHash != c.currentPrimaryPolicyHash
                || c.currentPrimaryPolicyHash == 0
                || r.policyDrift
                    != (r.originalExpectedPrimaryPolicyHash != r.currentPrimaryPolicyHash)
                || keccak256(
                        StreamConservationFloorReads.read(
                            msg.sender,
                            abi.encodeCall(
                                IStreamNativeSupplementalSettlement.nativeSupplementalResult,
                                (r.settlementKey)
                            ),
                            512,
                            x.readGas
                        )
                    ) != keccak256(abi.encode(r))
        ) revert IStreamConservationFloor.ConservationFloorSettlementMismatch(r.settlementKey);
        StreamPrimarySettlementTypes.PrimarySettlementResult memory common =
            StreamPrimarySettlementTypes.PrimarySettlementResult(
                r.candidateCommitment,
                r.settlementKey,
                r.profileId,
                r.wallet,
                address(0),
                r.amount,
                r.executor,
                r.executionId,
                r.escrowed,
                r.originalOperationRoot,
                c.originalFloor.currentPolicyHash,
                c.originalFloor.boundPolicyHash
            );
        StreamConservationFloorReads.requireStoredResult(x, msg.sender, common);
    }

    function _purchase(
        StreamConservationFloorReads.Context memory x,
        StreamNativeSupplementalTypes.NativeSupplementalCandidate memory c,
        StreamNativeSupplementalTypes.NativeSupplementalResult memory r
    ) private view {
        StreamNativeSupplementalTypes.ClearingPurchaseFacts memory p = c.purchase;
        if (
            c.purchaseId == 0 || c.purchaseId != StreamNativeSupplementalHash.purchaseId(c)
                || p.purchaseNonce == 0 || p.tokenId == 0
                || p.status != StreamNativeSupplementalTypes.SUPPLEMENTAL_OWED
                || p.effectiveFinalizeBy == 0 || block.timestamp > p.effectiveFinalizeBy
                || p.floorPrice == 0 || p.floorPrice != c.originalFloor.sale.amount
                || p.paidPrice < p.floorPrice || p.globalClearingPrice < p.floorPrice
                || p.originalOperationId != c.originalFloor.operationId
                || p.originalAuthorizationDigest
                    != c.originalFloor.executionBinding.saleAuthorizationDigest
        ) revert IStreamConservationFloor.ConservationFloorSettlementMismatch(r.settlementKey);
        uint256 uniform = p.globalClearingPrice;
        if (p.hasPriceOverride) {
            if (p.priceOverride < p.floorPrice) {
                revert IStreamConservationFloor.ConservationFloorInvalidEvidence();
            }
            if (p.priceOverride < uniform) uniform = p.priceOverride;
        } else if (p.priceOverride != 0) {
            revert IStreamConservationFloor.ConservationFloorInvalidEvidence();
        }
        if (
            uniform != p.buyerUniformPrice || uniform > p.paidPrice || uniform <= p.floorPrice
                || r.amount != uniform - p.floorPrice
        ) revert IStreamConservationFloor.ConservationFloorInvalidEvidence();
        _consumer(x, c, r.candidateCommitment);
        StreamConservationFloorReads.requireToken(
            x, c.originalFloor.sale.collectionId, p.tokenId, true
        );
    }

    function _consumer(
        StreamConservationFloorReads.Context memory x,
        StreamNativeSupplementalTypes.NativeSupplementalCandidate memory c,
        bytes32 commitment
    ) private view {
        StreamNativeSettlementTypes.NativeSettlementCandidate memory n = c.originalFloor;
        StreamConservationFloorReads.requireNativeSale(x, n);
        address adapter = n.saleAdapter;
        if (
            StreamConservationFloorReads.word(adapter, abi.encodeWithSignature("core()"), x.readGas)
                    != uint160(x.core)
                || StreamConservationFloorReads.word(
                        adapter, abi.encodeWithSignature("primarySaleSettlement()"), x.readGas
                    ) != uint160(msg.sender)
                || StreamConservationFloorReads.word(
                        adapter, abi.encodeWithSignature("mintManager()"), x.readGas
                    ) != uint160(n.mintManager)
                || bytes32(
                        StreamConservationFloorReads.word(
                            adapter, abi.encodeWithSignature("mintManagerCodeHash()"), x.readGas
                        )
                    ) != n.mintManager.codehash
                || StreamConservationFloorReads.word(
                        adapter,
                        abi.encodeCall(
                            IERC165.supportsInterface,
                            (type(IStreamNativeClearingSaleBinding).interfaceId)
                        ),
                        x.readGas
                    ) != 1
                || bytes32(
                        StreamConservationFloorReads.word(
                            adapter,
                            abi.encodeCall(
                                IStreamNativeClearingSaleBinding.activeNativeSupplementalSettlement,
                                (c.purchaseId)
                            ),
                            x.readGas
                        )
                    ) != commitment
                || keccak256(
                        StreamConservationFloorReads.read(
                            adapter,
                            abi.encodeCall(
                                IStreamNativeClearingSaleBinding.clearingPurchaseFacts,
                                (c.purchaseId)
                            ),
                            448,
                            x.readGas
                        )
                    ) != keccak256(abi.encode(c.purchase))
                || StreamConservationFloorReads.word(
                        n.mintManager,
                        abi.encodeWithSignature(
                            "isOperationRootUsed(bytes32)", n.operationIdentityCommitment
                        ),
                        x.readGas
                    ) != 1
        ) revert IStreamConservationFloor.ConservationFloorAuthority(adapter);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/core/IStreamCoreConservationTier.sol";

/// @notice Closed CMC-MUSEUM-GRADE vocabulary. The effective default uses completed mints only.
library StreamConservationTiers {
    bytes32 internal constant MUSEUM_GRADE = keccak256("MUSEUM_GRADE");
    bytes32 internal constant MUSEUM_GRADE_LITE = keccak256("MUSEUM_GRADE_LITE");
    bytes32 internal constant CONSERVATION_WAIVED = keccak256("CONSERVATION_WAIVED");

    function requireKnown(bytes32 tier) internal pure {
        if (tier != MUSEUM_GRADE && tier != MUSEUM_GRADE_LITE && tier != CONSERVATION_WAIVED) {
            revert IStreamCoreConservationTier.InvalidConservationTier(tier);
        }
    }

    function effective(bytes32 declared, uint256 completedMints) internal pure returns (bytes32) {
        if (declared != 0) {
            requireKnown(declared);
            return declared;
        }
        return completedMints == 0 ? bytes32(0) : MUSEUM_GRADE_LITE;
    }
}

