// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    IStreamEntropyCollectionPolicy as Policy
} from "../../interfaces/stream/entropy/IStreamEntropyCollectionPolicy.sol";
import { IStreamEntropyView } from "../../interfaces/stream/entropy/IStreamEntropyView.sol";
import { IStreamCoreIdentity } from "../../interfaces/stream/core/IStreamCoreIdentity.sol";
import {
    IStreamImmediateSaleReveal as Reveal
} from "../../interfaces/stream/mint/IStreamImmediateSaleReveal.sol";

/// @notice Fixed read boundary for explicit entropy policy in mint completion paths.
/// @dev A missing legacy capability is not an entropy exemption. No token is represented as finalized.
library StreamImmediateSaleEntropyPolicy {
    function terminalStatus(address coordinator, uint256 collectionId)
        public
        view
        returns (uint8 status)
    {
        Policy.PolicyRecord memory p = _policy(coordinator, collectionId);
        if (!p.explicitPolicy) return 0;
        if (p.mode == Policy.Mode.DISABLED) return 1;
        if (p.renderRequirement == Policy.RenderRequirement.NOT_REQUIRED) return 2;
    }

    /// @notice Whether this explicit mode has no asynchronous reveal promise or fee.
    function noRevealPolicy(address coordinator, uint256 collectionId) public view returns (bool) {
        Policy.PolicyRecord memory p = _policy(coordinator, collectionId);
        return p.explicitPolicy && p.mode != Policy.Mode.ASYNC;
    }

    /// @notice Validate a terminal token or a newly registered INSTANT token before skipping AT_MINT.
    /// @dev Required INSTANT entropy is requested in a later block; it is not terminal or finalized.
    function requireNoMintRequestToken(
        address core,
        address coordinator,
        uint256 collectionId,
        uint256 tokenId
    ) public view returns (bool) {
        Policy.PolicyRecord memory p = _policy(coordinator, collectionId);
        if (
            !p.explicitPolicy
                || (p.mode == Policy.Mode.ASYNC
                    && p.renderRequirement == Policy.RenderRequirement.REQUIRED)
        ) return false;
        _requireToken(core, coordinator, collectionId, tokenId, p);
        return true;
    }

    /// @notice Validate a completed terminal token using permanent identity, including after burn.
    /// @dev Core itself prevents burning during its mint receiver callback.
    function requireTerminalToken(
        address core,
        address coordinator,
        uint256 collectionId,
        uint256 tokenId
    ) public view returns (bool terminal) {
        Policy.PolicyRecord memory p = _policy(coordinator, collectionId);
        if (!p.explicitPolicy || p.renderRequirement != Policy.RenderRequirement.NOT_REQUIRED) {
            return false;
        }
        _requireToken(core, coordinator, collectionId, tokenId, p);
        return true;
    }

    function _requireToken(
        address core,
        address coordinator,
        uint256 collectionId,
        uint256 tokenId,
        Policy.PolicyRecord memory p
    ) private view {
        uint8 expected = p.mode == Policy.Mode.DISABLED
            ? 1
            : p.renderRequirement == Policy.RenderRequirement.NOT_REQUIRED ? 2 : 3;
        if (!p.frozen) revert Reveal.SaleRevealDependencyInvalid(coordinator);
        uint256[4] memory identity = abi.decode(
            _read(
                core, abi.encodeCall(IStreamCoreIdentity.tokenCollectionIdentity, (tokenId)), 128
            ),
            (uint256[4])
        );
        uint256 lifecycle = abi.decode(
            _read(core, abi.encodeCall(IStreamCoreIdentity.tokenLifecycle, (tokenId)), 32),
            (uint256)
        );
        uint256 original = abi.decode(
            _read(core, abi.encodeCall(IStreamCoreIdentity.coordinatorAtMint, (tokenId)), 32),
            (uint256)
        );
        if (
            identity[0] != 1 || identity[1] != collectionId || identity[2] == 0
                || (lifecycle != 2 && lifecycle != 3) || identity[3] != (lifecycle == 3 ? 1 : 0)
                || original != uint256(uint160(coordinator))
        ) revert Reveal.SaleRevealDependencyInvalid(core);
        uint256[8] memory e = abi.decode(
            _read(coordinator, abi.encodeCall(IStreamEntropyView.tokenEntropy, (tokenId)), 256),
            (uint256[8])
        );
        uint256[2] memory seed = abi.decode(
            _read(coordinator, abi.encodeCall(IStreamEntropyView.tokenSeed, (tokenId)), 64),
            (uint256[2])
        );
        uint256 observed = abi.decode(
            _read(
                coordinator, abi.encodeCall(IStreamEntropyView.tokenEntropyStatus, (tokenId)), 32
            ),
            (uint256)
        );
        if (
            e[0] != expected || observed != expected || e[1] != 0 || e[5] != 0 || e[6] != 0
                || e[7] != 0 || seed[0] != 0 || seed[1] != 0 || e[2] > type(uint160).max
                || e[3] > type(uint32).max || e[3] != p.providerEpoch
                || (expected == 1 ? e[2] != 0 || e[4] != 0 : e[2] == 0 || e[4] == 0)
        ) {
            revert Reveal.SaleRevealDependencyInvalid(coordinator);
        }
    }

    function _policy(address target, uint256 collectionId)
        private
        view
        returns (Policy.PolicyRecord memory p)
    {
        bytes memory query =
            abi.encodeWithSignature("supportsInterface(bytes4)", type(Policy).interfaceId);
        bool ok;
        uint256 size;
        uint256 word;
        assembly ("memory-safe") {
            ok := staticcall(30000, target, add(query, 32), mload(query), 0, 32)
            size := returndatasize()
            word := mload(0)
        }
        // Original coordinators need not expose the additive interface.
        if (!ok || size == 0) return p;
        if (size != 32 || word > 1) revert Reveal.SaleRevealDependencyInvalid(target);
        if (word == 0) return p;
        p = abi.decode(
            _read(target, abi.encodeCall(Policy.collectionEntropyPolicy, (collectionId)), 384),
            (Policy.PolicyRecord)
        );
        if (!p.explicitPolicy) {
            if (
                p.mode != Policy.Mode.ASYNC
                    || p.renderRequirement != Policy.RenderRequirement.REQUIRED
                    || p.securityClass != Policy.SecurityClass.HIGH_ASSURANCE || p.revision != 0
            ) {
                revert Reveal.SaleRevealDependencyInvalid(target);
            }
            return p;
        }
        if (
            !p.configured || p.revision == 0 || p.policyHash == 0 || p.contentStateHash == 0
                || p.lastActionId == 0 || p.artistConsentRecord == 0
                || (p.mode == Policy.Mode.DISABLED
                    && p.renderRequirement != Policy.RenderRequirement.NOT_REQUIRED)
                || (p.mode == Policy.Mode.INSTANT
                    && p.securityClass != Policy.SecurityClass.LOW_SECURITY)
        ) {
            revert Reveal.SaleRevealDependencyInvalid(target);
        }
        bytes32 expected = keccak256(
            abi.encode(keccak256("6529STREAM_ENTROPY_CONFIGURATION_V1"), p.policyHash, p.frozen)
        );
        if (p.contentStateHash != expected) revert Reveal.SaleRevealDependencyInvalid(target);
    }

    function _read(address target, bytes memory data, uint256 length)
        private
        view
        returns (bytes memory raw)
    {
        raw = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), add(raw, 32), length)
            size := returndatasize()
        }
        if (!ok || size != length) revert Reveal.SaleRevealDependencyInvalid(target);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamImmediateSaleReveal.sol";
import "../../interfaces/stream/core/IStreamCorePointers.sol";
import "../../interfaces/stream/entropy/IStreamEntropyCoordinator.sol";
import {
    StreamImmediateSaleEntropyPolicy as EntropyPolicy
} from "./StreamImmediateSaleEntropyPolicy.sol";

/// @notice Linked current-coordinator fee funding and failure-isolated AT_MINT requests.
/// @dev The caller owns credits and replay. Fixed-size reads and bounded return copies keep
///      an external provider's returndata out of the parent's allocation budget.
library StreamImmediateSaleReveal {
    event ImmediateRevealAttempt(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        uint256 indexed tokenId,
        bool succeeded,
        bytes32 requestKey,
        uint256 providerRequestId,
        uint256 returnDataSize,
        bytes failurePrefix
    );
    bytes32 private constant _ENTROPY = keccak256("ENTROPY_COORDINATOR");

    function quote(address core, uint256 collectionId)
        public
        view
        returns (IStreamImmediateSaleReveal.RevealQuote memory q)
    {
        uint256[10] memory pointer = abi.decode(
            _read(core, abi.encodeCall(IStreamCorePointers.getSatellitePointer, (_ENTROPY)), 320),
            (uint256[10])
        );
        if (pointer[0] > type(uint160).max) {
            revert IStreamImmediateSaleReveal.SaleRevealDependencyInvalid(core);
        }
        q.coordinator = address(uint160(pointer[0]));
        q.coordinatorCodeHash = bytes32(pointer[1]);
        _requireSelected(core, q);
        uint256[5] memory words = abi.decode(
            _read(
                q.coordinator,
                abi.encodeCall(IStreamRevealFeeEscrow.collectionRevealPolicy, (collectionId)),
                160
            ),
            (uint256[5])
        );
        if (EntropyPolicy.noRevealPolicy(q.coordinator, collectionId)) {
            // DISABLED and INSTANT have no asynchronous reveal promise or fee.
            if (words[0] != 0 || words[1] != 0 || words[2] != 0 || words[3] != 0 || words[4] != 0) {
                revert IStreamImmediateSaleReveal.SaleRevealDependencyInvalid(q.coordinator);
            }
            return q;
        }
        if (words[0] != 1 || words[1] > 1 || words[3] > type(uint64).max) {
            revert IStreamImmediateSaleReveal.SaleRevealDependencyInvalid(q.coordinator);
        }
        q.policy = IStreamRevealFeeEscrow.CollectionRevealPolicy(
            true, uint8(words[1]), bytes32(words[2]), uint64(words[3]), words[4]
        );
    }

    function preflight(
        IStreamImmediateSaleReveal.RevealQuote memory q,
        uint256 allowance,
        uint256 cap
    ) public view returns (uint256 excess) {
        uint256 fee = q.policy.revealFeePerTokenWei;
        if (allowance < fee) {
            revert IStreamImmediateSaleReveal.SaleRevealFeeBelowRequired(allowance, fee);
        }
        if (q.policy.declared && q.policy.requestMode == 0) _requireGas(cap);
        return allowance - fee;
    }

    /// @dev The pre-mint policy is the transaction's captured fee quote, even if an external
    ///      receiver changes an Operational fee later. Funding is separate from requesting.
    function fundAndAttempt(
        address core,
        uint256 collectionId,
        uint256 tokenId,
        IStreamImmediateSaleReveal.RevealQuote memory q,
        uint256 cap
    ) public {
        _requireSelected(core, q);
        address target = q.coordinator;
        bool skipRequest =
            EntropyPolicy.requireNoMintRequestToken(core, target, collectionId, tokenId);
        if (
            !q.policy.declared
                && (!skipRequest || !EntropyPolicy.noRevealPolicy(target, collectionId))
        ) {
            revert IStreamImmediateSaleReveal.SaleRevealDependencyInvalid(target);
        }
        uint256 fee = q.policy.revealFeePerTokenWei;
        if (fee != 0) {
            bytes memory readData =
                abi.encodeCall(IStreamRevealFeeEscrow.revealFeeEscrow, (collectionId));
            uint256 beforeEscrow = abi.decode(_read(target, readData, 32), (uint256));
            bytes memory data =
                abi.encodeCall(IStreamRevealFeeEscrow.fundRevealFeeEscrow, (collectionId));
            bool ok;
            uint256 size;
            assembly ("memory-safe") {
                ok := call(gas(), target, fee, add(data, 32), mload(data), 0, 0)
                size := returndatasize()
            }
            if (!ok || size != 0) {
                revert IStreamImmediateSaleReveal.SaleRevealDependencyInvalid(target);
            }
            uint256 afterEscrow = abi.decode(_read(target, readData, 32), (uint256));
            if (afterEscrow != beforeEscrow + fee) {
                revert IStreamImmediateSaleReveal.SaleRevealAccountingMismatch();
            }
        }
        if (!skipRequest && q.policy.requestMode == 0) {
            _requireGas(cap);
            bytes memory data = abi.encodeCall(IStreamEntropyCoordinator.requestEntropy, (tokenId));
            uint256[2] memory result;
            bool ok;
            uint256 size;
            assembly ("memory-safe") {
                ok := call(cap, target, 0, add(data, 32), mload(data), result, 64)
                size := returndatasize()
            }
            if (ok && size == 64 && result[0] != 0) {
                emit ImmediateRevealAttempt(
                    1, collectionId, tokenId, true, bytes32(result[0]), result[1], size, ""
                );
            } else {
                bytes memory prefix = new bytes(size > 256 ? 256 : size);
                assembly ("memory-safe") { returndatacopy(add(prefix, 32), 0, mload(prefix)) }
                emit ImmediateRevealAttempt(1, collectionId, tokenId, false, 0, 0, size, prefix);
            }
        }
        _requireSelected(core, q);
    }

    function _requireSelected(address core, IStreamImmediateSaleReveal.RevealQuote memory q)
        private
        view
    {
        address target = q.coordinator;
        if (target.code.length == 0 || target.codehash != q.coordinatorCodeHash) {
            revert IStreamImmediateSaleReveal.SaleRevealDependencyInvalid(target);
        }
        uint256[10] memory pointer = abi.decode(
            _read(core, abi.encodeCall(IStreamCorePointers.getSatellitePointer, (_ENTROPY)), 320),
            (uint256[10])
        );
        if (
            pointer[0] != uint256(uint160(target)) || bytes32(pointer[1]) != q.coordinatorCodeHash
                || abi.decode(
                        _read(target, abi.encodeCall(IStreamRevealFeeEscrow.core, ()), 32),
                        (uint256)
                    ) != uint256(uint160(core))
        ) {
            revert IStreamImmediateSaleReveal.SaleRevealDependencyInvalid(target);
        }
    }

    function _read(address target, bytes memory data, uint256 length)
        private
        view
        returns (bytes memory raw)
    {
        raw = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), add(raw, 32), length)
            size := returndatasize()
        }
        if (!ok || size != length) {
            revert IStreamImmediateSaleReveal.SaleRevealDependencyInvalid(target);
        }
    }

    function _requireGas(uint256 cap) private view {
        uint256 available = gasleft();
        if (cap > available || available - cap < cap / 63 + (cap % 63 == 0 ? 0 : 1) + 30_000) {
            revert IStreamImmediateSaleReveal.SaleRevealCallGasInsufficient(cap, available);
        }
    }
}

