pragma solidity ^0.8.19;
import "./StreamMintTranscriptTypes.sol";
import "./StreamMintPhaseState.sol";
import "./StreamMintManagerAccounting.sol";
import "./StreamMintArtistConsent.sol";
import "./StreamPreparedNativeOfferHash.sol";
import "../../interfaces/stream/mint/IStreamPreparedNativeOfferMint.sol";

/// @notice Offer-only transcript after Manager has independently admitted both original signatures.
/// @dev The ordinary zero-gate validator remains unchanged. Unselected offers retain their verified
/// buyer signer in the original counter subjects and operation hash domains without fabricating a gate.
library StreamMintManagerOfferTranscript {
    struct Context {
        address core;
        StreamMintOperationIdentity.PolicyContext policy;
        bytes32 registeredPolicyHash;
        uint256 firstOperationNonce;
        uint256 artistGas;
    }

    function build(
        IStreamMintManager.MintBatch calldata batch,
        bytes calldata gateData,
        bytes32 executionPath,
        StreamMintPhaseState.PhaseState storage phaseState,
        IStreamMintManager.MintGateConfig storage gate,
        bytes32[] storage counterIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage counters,
        address[] storage executors,
        Context memory x
    ) public view returns (StreamMintTranscriptTypes.OperationTranscript memory transcript) {
        transcript.quantity = validateMintBatch(batch, phaseState.config);
        transcript.currentPolicyHash = StreamMintPhaseState.computeStoredPolicyHash(
            phaseState, gate, counterIds, counters, executors, x.policy
        );
        if (transcript.currentPolicyHash != x.registeredPolicyHash) {
            revert IStreamMintManager.MintPolicyHashMismatch(
                x.registeredPolicyHash, transcript.currentPolicyHash
            );
        }
        transcript.boundPolicyHash = requireBoundPolicyHash(
            batch, transcript.currentPolicyHash, IStreamMintLedger(x.policy.ledger)
        );
        StreamMintArtistConsent.mint(
            x.core, batch.collectionId, batch.phaseId, transcript.currentPolicyHash, x.artistGas
        );
        if (gate.gate == address(0)) {
            // Manager's guarded offer entry has already authenticated this exact batch and payload.
            if (IStreamPreparedNativeOfferMint(address(this)).preparedNativeOfferAdmission() == 0) {
                revert StreamPreparedNativeOfferHash.InvalidPreparedNativeOffer();
            }
            StreamPreparedNativeOfferTypes.GateData memory d =
                abi.decode(gateData, (StreamPreparedNativeOfferTypes.GateData));
            if (
                transcript.quantity != 1 || d.authorizationId != batch.authorizationId
                    || d.buyerSignature.authorizer != batch.authorizer
                    || batch.authorizer == address(0)
                    || (d.buyerSignature.kind != 1 && d.buyerSignature.kind != 2)
            ) revert StreamPreparedNativeOfferHash.InvalidPreparedNativeOffer();
            transcript.authorization = StreamMintOperationIdentity.MintAuthorization({
                authorizationId: batch.authorizationId,
                nullifiers: new bytes32[](0),
                authorizer: batch.authorizer,
                authorizerKind: IStreamMintManager.AuthorizerKind(d.buyerSignature.kind),
                maxQuantity: 1,
                gateHash: bytes32(0)
            });
        } else {
            transcript.authorization = StreamMintGateValidator.validateAuthorization(
                batch,
                gateData,
                transcript.quantity,
                transcript.boundPolicyHash,
                gate,
                IERC165(x.policy.moduleRegistry),
                msg.sender
            );
        }
        transcript.consumptions = StreamMintManagerAccounting.counterConsumptions(
            batch,
            transcript.quantity,
            transcript.authorization.authorizer,
            x.policy.ledger,
            counterIds,
            counters
        );
        transcript.firstOperationNonce = x.firstOperationNonce;
        if (type(uint256).max - transcript.firstOperationNonce < transcript.quantity) {
            revert IStreamMintManager.MintOperationNonceOverflow(
                transcript.firstOperationNonce, transcript.quantity
            );
        }
        StreamMintOperationIdentity.TranscriptContext memory context =
            StreamMintOperationIdentity.TranscriptContext({
                chainId: block.chainid,
                manager: address(this),
                coreAddress: x.core,
                ledgerAddress: x.policy.ledger,
                gate: gate.gate,
                executor: msg.sender,
                executionPath: executionPath,
                currentPolicyHash: transcript.currentPolicyHash,
                boundPolicyHash: transcript.boundPolicyHash,
                firstOperationNonce: transcript.firstOperationNonce,
                quantity: transcript.quantity
            });
        (transcript.operationRoot, transcript.operationIds) = StreamMintOperationIdentity.derive(
            batch, transcript.authorization, transcript.consumptions, context
        );
    }

    function validateMintBatch(
        IStreamMintManager.MintBatch calldata request,
        IStreamMintManager.MintPhaseConfig memory config
    ) private pure returns (uint256 quantity) {
        quantity = request.initialRecipients.length;
        if (
            quantity == 0 || quantity != request.beneficiaries.length
                || quantity != request.tokenData.length
                || quantity != request.mintCommitments.length
        ) revert IStreamMintManager.MintArrayLengthMismatch();
        if (quantity > config.maxBatchQuantity) {
            revert IStreamMintManager.MintBatchQuantityLimitExceeded(
                quantity, config.maxBatchQuantity
            );
        }
        for (uint256 i = 0; i < quantity; i++) {
            if (
                request.initialRecipients[i] == address(0) || request.beneficiaries[i] == address(0)
            ) {
                revert IStreamMintManager.InvalidMintRecipient(
                    i, request.initialRecipients[i], request.beneficiaries[i]
                );
            }
        }
    }

    function requireBoundPolicyHash(
        IStreamMintManager.MintBatch calldata batch,
        bytes32 currentPolicyHash,
        IStreamMintLedger ledger
    ) private view returns (bytes32 boundPolicyHash) {
        boundPolicyHash = batch.expectedPolicyHash;
        if (boundPolicyHash == bytes32(0)) {
            revert IStreamMintManager.MintPolicyHashRequired(batch.collectionId, batch.phaseId);
        }
        if (boundPolicyHash == currentPolicyHash) return boundPolicyHash;
        (bytes32 previousPolicyHash,, uint64 graceUntil) =
            ledger.policyGrace(address(this), batch.collectionId, batch.phaseId);
        if (boundPolicyHash != previousPolicyHash || block.timestamp > graceUntil) {
            revert IStreamMintManager.MintPolicyHashMismatch(boundPolicyHash, currentPolicyHash);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamMintPhaseState.sol";
import "./StreamMintManagerAccounting.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";

/// @notice Original consent-gated policy refresh through a fixed linked boundary.
/// @dev Manager retains owner/reentrancy and configured-phase admission.
/// Delegatecall keeps its storage, identity and event emitter; the artist cap is
/// read from the actual Manager at the original post-hash consent phase.
library StreamMintManagerPolicy {
    struct Context {
        StreamMintOperationIdentity.PolicyContext policy;
        address core;
    }

    struct ExecutorUpdate {
        Context context;
        address executor;
        bool allowed;
        uint64 graceUntil;
        uint16 maxExecutors;
    }

    uint16 private constant SCHEMA_VERSION = 1;
    bytes32 private constant GGP_ARTIST_AUTHORITY_GAS_LIMIT =
        keccak256("6529STREAM_GGP_ARTIST_AUTHORITY_GAS_LIMIT");

    event MintPhaseConsentRecorded(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed policyHash,
        uint8 consentMode,
        bytes32 consentEvidenceHash
    );

    event MintPhaseExecutorUpdated(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address indexed executor,
        bool allowed,
        bytes32 policyHash,
        address admin
    );

    event MintPhasePausedEvent(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bool paused,
        bytes32 policyHash,
        address admin
    );

    /// @notice Original executable-phase admission in the actual Manager caller context.
    /// @dev The facade supplies its exact phase storage and caller's authorization bit.
    function requireExecutable(
        StreamMintPhaseState.PhaseState storage phase,
        uint256 collectionId,
        bytes32 phaseId,
        bool authorized
    ) external view {
        if (collectionId == 0 || phaseId == bytes32(0)) {
            revert IStreamMintManager.InvalidMintPhase(collectionId, phaseId);
        }
        if (!phase.exists) revert IStreamMintManager.MintPhaseDoesNotExist(collectionId, phaseId);
        if (phase.config.paused) revert IStreamMintManager.MintPhasePaused(collectionId, phaseId);
        if (phase.config.startTime != 0 && block.timestamp < phase.config.startTime) {
            revert IStreamMintManager.MintPhaseNotStarted(collectionId, phaseId, block.timestamp);
        }
        if (phase.config.endTime != 0 && block.timestamp > phase.config.endTime) {
            revert IStreamMintManager.MintPhaseEnded(collectionId, phaseId, block.timestamp);
        }
        if (!authorized) {
            revert IStreamMintManager.UnauthorizedMintExecutor(collectionId, phaseId, msg.sender);
        }
    }

    /// @dev The guarded facade admits an existing phase; no policy hash or grace changes here.
    function pause(
        StreamMintPhaseState.PhaseState storage phase,
        uint256 collectionId,
        bytes32 phaseId,
        bool paused,
        bytes32 policyHash
    ) external {
        if (phase.config.paused == paused) return;
        phase.config.paused = paused;
        emit MintPhasePausedEvent(collectionId, phaseId, paused, policyHash, msg.sender);
    }

    /// @notice Applies one original executor mutation and consented policy refresh atomically.
    /// @dev All storage references and the maximum originate at the guarded Manager entrypoint.
    function updateExecutor(
        StreamMintPhaseState.PhaseState storage phaseState,
        IStreamMintManager.MintGateConfig storage gate,
        bytes32[] storage counterIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage counters,
        mapping(address => bool) storage authorized,
        address[] storage executors,
        mapping(address => uint256) storage indexPlusOne,
        mapping(bytes32 => bytes32) storage policyHashes,
        ExecutorUpdate memory update
    ) external {
        if (update.executor == address(0)) {
            revert IStreamMintManager.InvalidMintExecutor(update.executor);
        }
        if (
            update.allowed && !authorized[update.executor]
                && StreamMintPhaseFreezeControl.frozen(
                    update.context.policy.ledger,
                    address(this),
                    update.context.policy.collectionId,
                    update.context.policy.phaseId
                )
        ) {
            revert IStreamMintPhaseFreeze.MintPhaseFrozenExecutor(
                update.context.policy.collectionId, update.context.policy.phaseId, update.executor
            );
        }
        if (!StreamMintPhaseState.setExecutor(
                authorized,
                executors,
                indexPlusOne,
                update.executor,
                update.allowed,
                update.maxExecutors
            )) {
            if (update.graceUntil != 0) {
                revert IStreamMintLedger.InvalidPolicyGrace(update.graceUntil);
            }
            return;
        }
        bytes32 policyHash = _refresh(
            phaseState,
            gate,
            counterIds,
            counters,
            executors,
            policyHashes,
            update.context,
            update.graceUntil
        );
        emit MintPhaseExecutorUpdated(
            update.context.policy.collectionId,
            update.context.policy.phaseId,
            update.executor,
            update.allowed,
            policyHash,
            msg.sender
        );
    }

    function _refresh(
        StreamMintPhaseState.PhaseState storage phaseState,
        IStreamMintManager.MintGateConfig storage gate,
        bytes32[] storage counterIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage counters,
        address[] storage executors,
        mapping(bytes32 => bytes32) storage policyHashes,
        Context memory x,
        uint64 graceUntil
    ) private returns (bytes32 policyHash) {
        uint256 collectionId = x.policy.collectionId;
        bytes32 phaseId = x.policy.phaseId;
        (bytes32[] memory ids, IStreamMintLedger.LedgerCounterPolicy[] memory ledgerPolicies) =
            StreamMintManagerAccounting.ledgerPolicies(counterIds, counters);
        policyHash = _computePolicyHash(phaseState, gate, counterIds, counters, executors, x);
        _recordArtistConsent(collectionId, phaseId, policyHash, x);
        policyHashes[phaseId] = policyHash;
        IStreamMintLedger(x.policy.ledger)
            .registerPhasePolicy(
                address(this), collectionId, phaseId, policyHash, ids, ledgerPolicies, graceUntil
            );
    }

    function _recordArtistConsent(
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 policyHash,
        Context memory x
    ) private {
        (uint8 mode, bytes32 evidence) = StreamMintArtistConsent.registration(
            x.core,
            collectionId,
            phaseId,
            policyHash,
            IStreamGasParameterHost(address(this)).gasParameter(GGP_ARTIST_AUTHORITY_GAS_LIMIT)
        );
        emit MintPhaseConsentRecorded(
            SCHEMA_VERSION, collectionId, phaseId, policyHash, mode, evidence
        );
    }

    function _computePolicyHash(
        StreamMintPhaseState.PhaseState storage phaseState,
        IStreamMintManager.MintGateConfig storage gate,
        bytes32[] storage counterIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage counters,
        address[] storage executors,
        Context memory x
    ) private view returns (bytes32) {
        return StreamMintPhaseState.computeStoredPolicyHash(
            phaseState, gate, counterIds, counters, executors, x.policy
        );
    }
}

