// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/mint/IStreamMintAuthorizationRevocation.sol";
import "../../interfaces/stream/mint/IStreamMintLedger.sol";
import "../../interfaces/stream/mint/IStreamMintLedgerRevocation.sol";
import "../../interfaces/stream/mint/IStreamImmediateSaleAuthorizationBinding.sol";
import "./StreamMintTicketHash.sol";
import "./StreamPrivateSaleHash.sol";

/// @notice Full-payload signer validation and exact manager-scoped Ledger voids.
/// @dev The guarded Manager invokes mutable functions through compiler links; direct CALL rejects.
///      Original gate/adapter addresses are domain inputs, not current authorization callbacks.
library StreamMintRevocation {
    struct Context {
        address core;
        address ledger;
        uint256 signatureGas;
    }

    event MintAuthorizationVoided(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed authorizationId,
        address authorizer,
        address verifyingContract,
        uint8 family
    );

    function ticketId(StreamMintTicketTypes.MintTicket memory ticket, address gate)
        public
        view
        returns (bytes32)
    {
        return StreamMintTicketHash.authorizationId(
            StreamMintTicketHash.digest(block.chainid, gate, ticket)
        );
    }

    function offerId(StreamPrivateSaleTypes.SaleOffer memory offer) public view returns (bytes32) {
        return StreamMintTicketHash.authorizationId(
            StreamPrivateSaleHash.digest(
                block.chainid, offer.saleAdapter, StreamPrivateSaleHash.offerBody(offer)
            )
        );
    }

    function voidTicket(
        Context memory c,
        StreamMintTicketTypes.MintTicket calldata ticket,
        address gate,
        bytes calldata signature
    ) public returns (bytes32 id) {
        if (
            ticket.chainId != block.chainid || ticket.manager != address(this)
                || ticket.ledger != c.ledger || gate == address(0)
                || ticket.authorizer == address(0)
        ) {
            revert IStreamMintAuthorizationRevocation.MintRevocationInvalidBinding();
        }
        id = ticketId(ticket, gate);
        _authorizer(
            c,
            ticket.authorizer,
            ticket.authorizerKind,
            id,
            StreamMintTicketHash.domain(block.chainid, gate),
            signature
        );
        _void(c.ledger, id);
        emit MintAuthorizationVoided(
            1, ticket.collectionId, ticket.phaseId, id, ticket.authorizer, gate, 0
        );
    }

    function saleAuthorizationId(StreamPrivateSaleTypes.SaleAuthorization memory authorization)
        public view returns (bytes32)
    {
        return StreamMintTicketHash.authorizationId(StreamPrivateSaleHash.digest(
            block.chainid, authorization.saleAdapter, StreamPrivateSaleHash.authorizationBody(authorization)
        ));
    }

    function voidSaleAuthorization(
        Context memory c,
        StreamPrivateSaleTypes.SaleAuthorization calldata authorization,
        bytes calldata signature
    ) public returns (bytes32 id) {
        if (authorization.chainId != block.chainid || authorization.mintManager != address(this)
            || authorization.saleAdapter == address(0) || authorization.saleId == 0
            || authorization.saleKind != 5 || authorization.revenueClass != keccak256("PRIMARY_SALE")) {
            revert IStreamMintAuthorizationRevocation.MintRevocationInvalidBinding();
        }
        // Exact immutable historical membership only. Expiry, current phase, module admission,
        // Artist authority and payment availability never condition a revocation.
        bytes memory data = abi.encodeWithSignature("curatedSaleAuthorizationBinding(bytes32)", authorization.saleId);
        bytes memory raw = new bytes(160);
        address adapter = authorization.saleAdapter;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), adapter, add(data, 32), mload(data), add(raw, 32), 160)
            size := returndatasize()
        }
        if (!ok || size != 160) revert IStreamMintAuthorizationRevocation.MintRevocationInvalidBinding();
        (uint256 collection, bytes32 phase, address signer, uint8 kind, bytes32 configHash) =
            abi.decode(raw, (uint256, bytes32, address, uint8, bytes32));
        if (keccak256(raw) != keccak256(abi.encode(collection, phase, signer, kind, configHash))
            || collection == 0 || collection != authorization.collectionId || phase == 0
            || phase != authorization.phaseId || signer == address(0) || configHash == 0) {
            revert IStreamMintAuthorizationRevocation.MintRevocationInvalidBinding();
        }
        id = saleAuthorizationId(authorization);
        _authorizer(c, signer, kind, id, StreamPrivateSaleHash.domain(block.chainid, adapter), signature);
        _void(c.ledger, id);
        emit MintAuthorizationVoided(1, collection, phase, id, signer, adapter, 2);
    }

    function voidImmediateSaleAuthorization(
        Context memory c,
        StreamPrivateSaleTypes.SaleAuthorization calldata authorization,
        address claimedAuthorizer,
        uint8 kind,
        bytes calldata signature
    ) public returns (bytes32 id) {
        if (
            authorization.chainId != block.chainid || authorization.mintManager != address(this)
                || authorization.saleAdapter == address(0) || authorization.saleId == 0
                || authorization.collectionId == 0 || authorization.phaseId == 0
                || (authorization.saleKind != 0 && authorization.saleKind != 1
                    && authorization.saleKind != 3 && authorization.saleKind != 12
                    && authorization.saleKind != 13)
                || authorization.revenueClass != keccak256("PRIMARY_SALE")
                || claimedAuthorizer == address(0)
        ) revert IStreamMintAuthorizationRevocation.MintRevocationInvalidBinding();
        if (kind != 1 && kind != 2) {
            revert IStreamMintAuthorizationRevocation.MintRevocationUnsupportedKind(kind);
        }

        // Copy only the fixed historical record. Decode words before narrowing so malformed
        // addresses and uint8 values fail with the same explicit binding error.
        address adapter = authorization.saleAdapter;
        bytes memory data = abi.encodeCall(
            IStreamImmediateSaleAuthorizationBinding.immediateSaleAuthorizationBinding,
            (authorization.saleId)
        );
        bytes memory raw = new bytes(224);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), adapter, add(data, 32), mload(data), add(raw, 32), 224)
            size := returndatasize()
        }
        if (!ok || size != 224) {
            revert IStreamMintAuthorizationRevocation.MintRevocationInvalidBinding();
        }
        uint256[7] memory binding = abi.decode(raw, (uint256[7]));
        if (
            binding[0] != authorization.collectionId || bytes32(binding[1]) != authorization.phaseId
                || binding[2] != authorization.saleKind || binding[3] != 1 || binding[4] == 0
                || binding[5] != uint256(uint160(claimedAuthorizer)) || binding[6] != kind
        ) revert IStreamMintAuthorizationRevocation.MintRevocationInvalidBinding();

        id = saleAuthorizationId(authorization);
        _authorizer(
            c,
            claimedAuthorizer,
            kind,
            id,
            StreamPrivateSaleHash.domain(block.chainid, adapter),
            signature
        );
        _void(c.ledger, id);
        emit MintAuthorizationVoided(
            1, authorization.collectionId, authorization.phaseId, id, claimedAuthorizer, adapter, 2
        );
    }

    function voidOffer(
        Context memory c,
        StreamPrivateSaleTypes.SaleOffer calldata offer,
        uint8 kind,
        bytes calldata signature
    ) public returns (bytes32 id) {
        if (
            offer.chainId != block.chainid || offer.core != c.core || offer.tokenId != 0
                || offer.buyer == address(0) || offer.saleAdapter == address(0)
        ) {
            revert IStreamMintAuthorizationRevocation.MintRevocationInvalidBinding();
        }
        id = offerId(offer);
        _authorizer(
            c,
            offer.buyer,
            kind,
            id,
            StreamPrivateSaleHash.domain(block.chainid, offer.saleAdapter),
            signature
        );
        _void(c.ledger, id);
        emit MintAuthorizationVoided(
            1, offer.collectionId, 0, id, offer.buyer, offer.saleAdapter, 1
        );
    }

    function _authorizer(
        Context memory c,
        address signer,
        uint8 kind,
        bytes32 id,
        bytes32 originalDomain,
        bytes calldata signature
    ) private view {
        if (kind != 1 && kind != 2) {
            revert IStreamMintAuthorizationRevocation.MintRevocationUnsupportedKind(kind);
        }
        if (msg.sender == signer) return;
        bytes32 digest = keccak256(
            abi.encodePacked(
                hex"1901",
                originalDomain,
                StreamMintTicketHash.revocationBody(block.chainid, address(this), c.ledger, id)
            )
        );
        if (!_validSignature(signer, kind, digest, signature, c.signatureGas)) {
            revert IStreamMintAuthorizationRevocation.MintRevocationInvalidSignature(signer);
        }
    }

    function _validSignature(
        address signer,
        uint8 kind,
        bytes32 digest,
        bytes calldata signature,
        uint256 cap
    ) private view returns (bool) {
        if (kind == 1) {
            bytes32 r;
            bytes32 s;
            uint8 v;
            if (signature.length == 65) {
                assembly ("memory-safe") {
                    r := calldataload(signature.offset)
                    s := calldataload(add(signature.offset, 32))
                    v := byte(0, calldataload(add(signature.offset, 64)))
                }
            } else if (signature.length == 64) {
                bytes32 vs;
                assembly ("memory-safe") {
                    r := calldataload(signature.offset)
                    vs := calldataload(add(signature.offset, 32))
                }
                s = bytes32(uint256(vs) & ((uint256(1) << 255) - 1));
                v = uint8((uint256(vs) >> 255) + 27);
            } else {
                return false;
            }
            if (
                uint256(s) > 0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0
                    || (v != 27 && v != 28)
            ) return false;
            address recovered = ecrecover(digest, v, r, s);
            return recovered != address(0) && recovered == signer;
        }
        return _contractSignature(signer, digest, signature, cap);
    }

    function _contractSignature(
        address signer,
        bytes32 digest,
        bytes calldata signature,
        uint256 cap
    ) private view returns (bool) {
        bytes memory data = abi.encodeWithSelector(bytes4(0x1626ba7e), digest, signature);
        uint256 available = gasleft();
        uint256 required = cap + (cap + 62) / 63 + 40_000;
        if (available < required) {
            revert IStreamMintAuthorizationRevocation.MintRevocationInsufficientGas(
                required, available
            );
        }
        bool ok;
        uint256 size;
        uint256 word;
        assembly ("memory-safe") {
            ok := staticcall(cap, signer, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            word := mload(0)
        }
        return ok && size == 32 && word == uint256(uint32(0x1626ba7e)) << 224;
    }

    function _void(address ledger, bytes32 id) private {
        if (
            _word(
                    ledger,
                    abi.encodeWithSelector(
                        IERC165.supportsInterface.selector,
                        type(IStreamMintLedgerRevocation).interfaceId
                    )
                ) != 1
        ) {
            revert IStreamMintAuthorizationRevocation.MintLedgerRevocationUnavailable(ledger);
        }
        bytes memory usedCall =
            abi.encodeCall(IStreamMintLedger.isManagerAuthorizationUsed, (address(this), id));
        uint256 used = _word(ledger, usedCall);
        if (used > 1) {
            revert IStreamMintAuthorizationRevocation.MintLedgerRevocationUnavailable(ledger);
        }
        if (used == 1) revert IStreamMintLedger.AuthorizationAlreadyConsumed(id);
        bytes memory data =
            abi.encodeCall(IStreamMintLedgerRevocation.voidAuthorization, (address(this), id));
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := call(gas(), ledger, 0, add(data, 32), mload(data), 0, 0)
            size := returndatasize()
        }
        if (!ok || size != 0 || _word(ledger, usedCall) != 1) {
            revert IStreamMintAuthorizationRevocation.MintLedgerRevocationUnavailable(ledger);
        }
    }

    function _word(address ledger, bytes memory data) private view returns (uint256 word) {
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), ledger, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            word := mload(0)
        }
        if (!ok || size != 32) {
            revert IStreamMintAuthorizationRevocation.MintLedgerRevocationUnavailable(ledger);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { IStreamCorePointers } from "../../interfaces/stream/core/IStreamCorePointers.sol";
import {
    IStreamModuleRegistry,
    StreamModuleRecord
} from "../../interfaces/stream/modules/IStreamModuleRegistry.sol";
import { IStreamRoyaltyResolver } from "../../interfaces/stream/revenue/IStreamRoyaltyResolver.sol";
import { IStreamRoyaltySnapshot } from "../../interfaces/stream/revenue/IStreamRoyaltySnapshot.sol";
import {
    IStreamArtistSnapshotRoyaltyFacts
} from "../../interfaces/stream/artist/IStreamArtistSnapshotRoyaltyFacts.sol";
import {
    IStreamMintRoyaltyPolicy
} from "../../interfaces/stream/mint/IStreamMintRoyaltyPolicy.sol";
import { IStreamMintManager } from "../../interfaces/stream/mint/IStreamMintManager.sol";
import { IERC165 } from "../../vendor/openzeppelin/IERC165.sol";
import { StreamRoyaltyPreparedProof } from "../revenue/StreamRoyaltyPreparedProof.sol";

/// @notice One fixed policy implementation shared by transcript admission and every prepared site.
library StreamMintRoyaltyPolicy {
    struct Context {
        address core;
        address registry;
    }
    event MintPhaseRoyaltyPolicyRegistered(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed configHash,
        IStreamMintRoyaltyPolicy.Policy policy
    );

    function context(address core) public view returns (Context memory) {
        return Context(
            core,
            abi.decode(
                _read(address(this), abi.encodeWithSignature("moduleRegistry()"), 32), (address)
            )
        );
    }

    function configHash(
        uint256 collectionId,
        bytes32 phaseId,
        IStreamMintRoyaltyPolicy.Policy memory p
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_MINT_PHASE_ROYALTY_CONFIG_V1"),
                block.chainid,
                address(this),
                collectionId,
                phaseId,
                p.applicationConfigHash,
                p.resolver,
                p.resolverRuntimeHash,
                uint8(2),
                p.electionHash,
                p.expectedModeAssignmentHash,
                p.expectedSourceRoyaltyPolicyHash
            )
        );
    }

    function register(
        IStreamMintRoyaltyPolicy.Policy storage stored,
        Context memory x,
        uint256 collectionId,
        bytes32 phaseId,
        IStreamMintRoyaltyPolicy.Policy memory p
    ) public returns (bytes32 hash) {
        if (stored.configured) {
            revert IStreamMintRoyaltyPolicy.MintRoyaltyPolicyAlreadyConfigured(
                collectionId, phaseId
            );
        }
        if (
            !p.configured || p.applicationConfigHash == 0 || p.resolver == address(0)
                || p.resolverRuntimeHash == 0 || p.electionHash == 0
                || p.expectedModeAssignmentHash == 0 || p.expectedSourceRoyaltyPolicyHash == 0
        ) revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        hash = configHash(collectionId, phaseId, p);
        requireCurrent(p, x, collectionId, phaseId, hash, false);
        stored.configured = p.configured;
        stored.applicationConfigHash = p.applicationConfigHash;
        stored.resolver = p.resolver;
        stored.resolverRuntimeHash = p.resolverRuntimeHash;
        stored.electionHash = p.electionHash;
        stored.expectedModeAssignmentHash = p.expectedModeAssignmentHash;
        stored.expectedSourceRoyaltyPolicyHash = p.expectedSourceRoyaltyPolicyHash;
        emit MintPhaseRoyaltyPolicyRegistered(1, collectionId, phaseId, hash, p);
    }

    function requireCurrent(
        IStreamMintRoyaltyPolicy.Policy memory p,
        Context memory x,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 actualConfigHash,
        bool singleStep
    ) public view returns (bool snapshotRequired) {
        StreamRoyaltyPreparedProof.Pointer memory pointer = abi.decode(
            _read(
                x.core,
                abi.encodeCall(
                    IStreamCorePointers.getSatellitePointer, (keccak256("ROYALTY_RESOLVER"))
                ),
                320
            ),
            (StreamRoyaltyPreparedProof.Pointer)
        );
        if (pointer.target == address(0)) {
            if (p.configured) revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
            return false;
        }
        if (pointer.target.code.length == 0 || pointer.target.codehash != pointer.runtimeHash) {
            revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        }
        bool capable = abi.decode(
            _read(
                pointer.target,
                abi.encodeCall(
                    IERC165.supportsInterface, (type(IStreamArtistSnapshotRoyaltyFacts).interfaceId)
                ),
                32
            ),
            (bool)
        );
        if (!capable) {
            if (p.configured) revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
            return false;
        }
        (uint8 mode, bytes32 election) = abi.decode(
            _read(
                pointer.target,
                abi.encodeCall(
                    IStreamArtistSnapshotRoyaltyFacts.collectionRoyaltyMode, (collectionId)
                ),
                64
            ),
            (uint8, bytes32)
        );
        if (mode == 1) {
            if (p.configured) revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
            return false;
        }
        if (mode != 2 || election == 0) revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        if (singleStep) {
            revert IStreamMintRoyaltyPolicy.PreparedRoyaltySnapshotRequired(collectionId);
        }
        if (
            !p.configured || p.resolver != pointer.target
                || p.resolverRuntimeHash != pointer.runtimeHash || p.electionHash != election
                || actualConfigHash != configHash(collectionId, phaseId, p)
        ) {
            revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        }
        _activeResolver(x, pointer);
        IStreamRoyaltySnapshot.Source memory source = abi.decode(
            _read(
                pointer.target,
                abi.encodeCall(IStreamRoyaltySnapshot.currentRoyaltySnapshotSource, (collectionId)),
                352
            ),
            (IStreamRoyaltySnapshot.Source)
        );
        if (
            source.collectionId != collectionId || source.electionHash != election
                || source.modeAssignmentHash != p.expectedModeAssignmentHash
                || source.sourceRoyaltyPolicyHash != p.expectedSourceRoyaltyPolicyHash
        ) {
            revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        }
        return true;
    }

    /// @dev Called only by fixed execution libraries in Manager context, immediately after prepare.
    function snapshot(
        Context memory x,
        uint256 collectionId,
        bytes32 phaseId,
        uint256 tokenId,
        bytes32 root,
        bytes32 operationId
    ) public {
        (IStreamMintRoyaltyPolicy.Policy memory p, bool required) =
            _current(x, collectionId, phaseId);
        if (!required) return;
        bytes32 returned = IStreamRoyaltySnapshot(p.resolver)
            .snapshotTokenRoyaltyAtMint(
                tokenId,
                collectionId,
                root,
                operationId,
                keccak256("ROYALTY_ERC2981"),
                p.expectedSourceRoyaltyPolicyHash
            );
        if (returned == 0) revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        _snapshot(p, collectionId, tokenId, root, operationId, returned);
        _current(x, collectionId, phaseId);
    }

    /// @dev Rechecks current phase/source and retained result after callbacks; never snapshots twice.
    function completed(
        Context memory x,
        uint256 collectionId,
        bytes32 phaseId,
        uint256 tokenId,
        bytes32 root,
        bytes32 operationId
    ) public view {
        (IStreamMintRoyaltyPolicy.Policy memory p, bool required) =
            _current(x, collectionId, phaseId);
        if (required) _snapshot(p, collectionId, tokenId, root, operationId, bytes32(0));
    }

    function _current(Context memory x, uint256 collectionId, bytes32 phaseId)
        private
        view
        returns (IStreamMintRoyaltyPolicy.Policy memory p, bool required)
    {
        // Fixed self-reads preserve the single original Manager-owned policy, with no callback facts.
        p = IStreamMintRoyaltyPolicy(address(this)).phaseRoyaltyPolicy(collectionId, phaseId);
        (bool exists, IStreamMintManager.MintPhaseConfig memory phase) =
            IStreamMintManager(address(this)).phase(collectionId, phaseId);
        if (!exists) revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        required = requireCurrent(p, x, collectionId, phaseId, phase.configHash, false);
    }

    function _snapshot(
        IStreamMintRoyaltyPolicy.Policy memory p,
        uint256 collectionId,
        uint256 tokenId,
        bytes32 root,
        bytes32 operationId,
        bytes32 returned
    ) private view {
        IStreamRoyaltySnapshot.Snapshot memory s = abi.decode(
            _read(
                p.resolver, abi.encodeCall(IStreamRoyaltySnapshot.royaltySnapshot, (tokenId)), 448
            ),
            (IStreamRoyaltySnapshot.Snapshot)
        );
        if (
            !s.exists || s.collectionId != collectionId || s.tokenId != tokenId
                || s.manager != address(this) || s.operationRoot != root
                || s.operationId != operationId || s.preparedProofHash == 0
                || s.electionHash != p.electionHash
                || s.modeAssignmentHash != p.expectedModeAssignmentHash
                || s.sourceRoyaltyPolicyHash != p.expectedSourceRoyaltyPolicyHash
                || s.sourceAssignmentHash == 0 || s.tokenAssignmentHash == 0
                || s.tokenRoyaltyPolicyHash == 0 || s.tokenConfigHash == 0
                || (returned != 0 && s.tokenRoyaltyPolicyHash != returned)
        ) {
            revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        }
    }

    function _activeResolver(Context memory x, StreamRoyaltyPreparedProof.Pointer memory p)
        private
        view
    {
        if (
            p.registry != x.registry || p.status != 1
                || p.moduleType != keccak256("REVENUE_RESOLVER")
                || p.interfaceId != type(IStreamRoyaltyResolver).interfaceId
                || p.moduleManifest == 0 || p.deploymentManifest == 0 || p.revision == 0
                || !IStreamModuleRegistry(x.registry)
                    .isModuleEligible(p.target, p.moduleType, p.interfaceId)
                || !abi.decode(
                    _read(
                        p.target,
                        abi.encodeCall(
                            IERC165.supportsInterface, (type(IStreamRoyaltySnapshot).interfaceId)
                        ),
                        32
                    ),
                    (bool)
                )
        ) {
            revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        }
        StreamModuleRecord memory record = IStreamModuleRegistry(x.registry).moduleRecord(p.target);
        if (
            uint8(record.status) != 1 || record.runtimeCodeHash != p.runtimeHash
                || record.moduleManifestHash != p.moduleManifest
                || record.deploymentManifestHash != p.deploymentManifest
                || record.moduleType != p.moduleType || record.interfaceId != p.interfaceId
        ) {
            revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
        }
    }

    function _read(address target, bytes memory data, uint256 width)
        private
        view
        returns (bytes memory raw)
    {
        raw = new bytes(width);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), add(raw, 32), width)
            size := returndatasize()
        }
        if (!ok || size != width) revert IStreamMintRoyaltyPolicy.InvalidMintRoyaltyPolicy();
    }
}

