pragma solidity ^0.8.19;

import {
    StreamNativeCuratedSaleTypes as Curated
} from "../../interfaces/stream/mint/StreamNativeCuratedSaleTypes.sol";
import {
    StreamPreparedNativeContentTypes as Content
} from "../../interfaces/stream/mint/StreamPreparedNativeContentTypes.sol";
import {
    IStreamPreparedNativeContentPurchaseGate
} from "../../interfaces/stream/mint/IStreamPreparedNativeContentPurchaseGate.sol";
import { IStreamMintManager } from "../../interfaces/stream/mint/IStreamMintManager.sol";
import { IStreamMintLedger } from "../../interfaces/stream/mint/IStreamMintLedger.sol";
import {
    IStreamArtistAttribution
} from "../../interfaces/stream/artist/IStreamArtistAttribution.sol";
import {
    IStreamArtistPlatformWorks
} from "../../interfaces/stream/artist/IStreamArtistPlatformWorks.sol";
import { IStreamRevenueResolver } from "../../interfaces/stream/revenue/IStreamRevenueResolver.sol";
import { IERC165 } from "../../vendor/openzeppelin/IERC165.sol";
import { MerkleProof } from "../../vendor/openzeppelin/MerkleProof.sol";
import { StreamMintGateValidator } from "./StreamMintGateValidator.sol";
import { StreamPreparedNativeContentHash } from "./StreamPreparedNativeContentHash.sol";
import { StreamRefundWindowSupport } from "./StreamRefundWindowSupport.sol";
import {
    StreamPreparedNativeSettlementAdmission
} from "../revenue/StreamPreparedNativeSettlementAdmission.sol";

/// @notice Fixed reads for immutable selected-work records and the actual configured mint phase.
library StreamNativeCuratedSaleSupport {
    struct Context {
        address core;
        address registry;
        IStreamMintManager manager;
        IStreamRevenueResolver resolver;
        IStreamArtistAttribution artists;
        bytes32 artistsHash;
        uint256 artistGas;
    }

    error CuratedSaleInvalid();
    error CuratedSelectionInvalid();
    error CuratedAttributionReadFailed();
    error SaleAttributionContested(uint256 collectionId);

    function artistContext(Context memory x)
        private
        pure
        returns (StreamRefundWindowSupport.Context memory c)
    {
        c.core = x.core;
        c.manager = x.manager;
        c.resolver = x.resolver;
        c.artists = x.artists;
        c.artistHash = x.artistsHash;
        c.artistGas = x.artistGas;
    }

    function association(Context memory x, uint256 collection)
        public
        view
        returns (StreamRefundWindowSupport.ArtistAssociation memory a)
    {
        a = StreamRefundWindowSupport.artistAssociation(artistContext(x), collection);
        if (
            a.state != 2 || a.authorityStatus != 1 || a.artistId == 0 || a.generation == 0
                || a.bindingHash == 0
        ) {
            revert CuratedSaleInvalid();
        }
    }

    function retained(Context memory x, bytes32 id, Curated.SaleRecord memory sale) public view {
        if (sale.status != 1 || sale.configHash == 0) revert CuratedSaleInvalid();
        StreamPreparedNativeSettlementAdmission.requireAdmission(x.registry, address(this), id);
        StreamRefundWindowSupport.requireSaleConsent(
            artistContext(x), sale.config.collectionId, id, sale.configHash
        );
        StreamRefundWindowSupport.requireArtistAssociation(
            artistContext(x),
            sale.config.collectionId,
            sale.artistId,
            sale.bindingGeneration,
            sale.bindingHash
        );
        IStreamMintManager.MintGateConfig memory gate =
            x.manager.phaseGate(sale.config.collectionId, sale.config.phaseId);
        if (
            gate.gate != sale.gate || gate.gateCodehash != sale.gateCodeHash
                || gate.gate.codehash != sale.gateCodeHash
                || gate.gateConfigHash != sale.gateConfigHash
        ) revert CuratedSaleInvalid();
        _phase(x, sale.config);
        IStreamMintManager.MintCounterConfig memory counter = x.manager
            .counterConfig(sale.config.collectionId, sale.config.phaseId, sale.contentCounterId);
        if (
            !_contentCounter(counter) || counter.counterConfigHash != sale.contentCounterConfigHash
                || !_containsCounter(x.manager, sale.config, sale.contentCounterId)
        ) revert CuratedSaleInvalid();
    }

    /// @dev Sale clock tolling never bypasses the Manager's independent phase admission.
    /// Recheck after callbacks so a successful mint cannot retain a changed executor or policy.
    function _phase(Context memory x, Curated.Configuration memory config) private view {
        (bool exists, IStreamMintManager.MintPhaseConfig memory phase) =
            x.manager.phase(config.collectionId, config.phaseId);
        if (
            !exists || phase.paused || phase.maxBatchQuantity != 1
                || block.timestamp < phase.startTime
                || (phase.endTime != 0 && block.timestamp > phase.endTime)
                || !x.manager.phaseExecutor(config.collectionId, config.phaseId, address(this))
        ) revert CuratedSaleInvalid();
        bytes32 current = x.manager.phasePolicyHash(config.collectionId, config.phaseId);
        if (current == config.mintPolicyHash) return;
        (bytes32 previous, uint64 graceUntil) =
            x.manager.phasePolicyGrace(config.collectionId, config.phaseId);
        if (previous != config.mintPolicyHash || block.timestamp > graceUntil) {
            revert CuratedSaleInvalid();
        }
    }

    function publication(Context memory x, bytes32 id, Curated.Configuration memory config)
        public
        view
        returns (IStreamMintManager.MintGateConfig memory g, Content.Publication memory p)
    {
        if (
            config.collectionId == 0 || config.phaseId == 0 || config.price == 0
                || config.poster == address(0) || config.poster == address(this)
                || config.startsAt <= block.timestamp || config.endsAt <= config.startsAt
                || config.mintPolicyHash == 0 || config.expectedPrimaryPolicyHash == 0
                || config.primaryPolicyMode > 1 || config.contentManifestRoot == 0
                || x.manager.phasePolicyHash(config.collectionId, config.phaseId)
                    != config.mintPolicyHash
        ) revert CuratedSaleInvalid();
        g = x.manager.phaseGate(config.collectionId, config.phaseId);
        IStreamMintManager.MintGateConfig memory actual =
            StreamMintGateValidator.validateConfiguration(g, IERC165(x.registry));
        if (keccak256(abi.encode(actual)) != keccak256(abi.encode(g))) revert CuratedSaleInvalid();
        IStreamPreparedNativeContentPurchaseGate gate =
            IStreamPreparedNativeContentPurchaseGate(g.gate);
        p = gate.publication();
        if (
            !gate.supportsInterface(type(IStreamPreparedNativeContentPurchaseGate).interfaceId)
                || gate.contentPurchaseVersion()
                    != keccak256("6529STREAM_NATIVE_CONTENT_PURCHASE_GATE_V1")
                || gate.gateConfigHash() != g.gateConfigHash || p.chainId != block.chainid
                || p.manager != address(x.manager) || p.house != address(this) || p.saleId != id
                || p.collectionId != config.collectionId || p.phaseId != config.phaseId
                || p.manifestRoot != config.contentManifestRoot || p.manifestHash == 0
                || p.counterId == 0
                || g.gateConfigHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_NATIVE_CONTENT_PURCHASE_GATE_V1"),
                            p,
                            address(x.manager).codehash,
                            address(this).codehash
                        )
                    )
        ) revert CuratedSaleInvalid();
        _manifest(gate, p);
        (bool exists, IStreamMintManager.MintPhaseConfig memory phase) =
            x.manager.phase(config.collectionId, config.phaseId);
        IStreamMintManager.MintCounterConfig memory counter =
            x.manager.counterConfig(config.collectionId, config.phaseId, p.counterId);
        if (
            !exists || phase.paused || phase.maxBatchQuantity != 1
                || phase.startTime > config.startsAt
                || (phase.endTime != 0 && phase.endTime < config.endsAt)
                || !x.manager.phaseExecutor(config.collectionId, config.phaseId, address(this))
                || !_containsCounter(x.manager, config, p.counterId) || !_contentCounter(counter)
        ) revert CuratedSaleInvalid();
    }

    function _contentCounter(IStreamMintManager.MintCounterConfig memory counter)
        private
        pure
        returns (bool)
    {
        return counter.enabled && counter.keyMode == IStreamMintManager.CounterKeyMode.CONTEXT
            && counter.capMode == IStreamMintLedger.CounterCapMode.STATIC
            && counter.deltaMode == IStreamMintLedger.CounterDeltaMode.STATIC
            && counter.staticCap == 1 && counter.staticIncrement == 1
            && counter.counterConfigHash != 0;
    }

    function _containsCounter(
        IStreamMintManager manager,
        Curated.Configuration memory config,
        bytes32 counterId
    ) private view returns (bool) {
        bytes32[] memory ids = manager.phaseCounterIds(config.collectionId, config.phaseId);
        if (ids.length > 16) revert CuratedSaleInvalid();
        for (uint256 n; n < ids.length; ++n) {
            if (ids[n] == counterId) return true;
        }
        return false;
    }

    function selection(bytes32 id, Curated.SaleRecord memory sale, Curated.Selection memory chosen)
        public
        view
        returns (bytes32 leaf, bytes32 contextHash)
    {
        if (
            chosen.recipient == address(0) || chosen.recipient == address(this)
                || chosen.purchaseNonce == 0 || chosen.mintCommitment == 0
                || chosen.tokenData.length > 8192
                || chosen.content.tokenDataHash != keccak256(chosen.tokenData)
        ) revert CuratedSelectionInvalid();
        leaf = StreamPreparedNativeContentHash.leaf(
            block.chainid, address(this), id, chosen.content.contentId, chosen.content.tokenDataHash
        );
        if (!MerkleProof.verify(chosen.content.proof, sale.config.contentManifestRoot, leaf)) {
            revert CuratedSelectionInvalid();
        }
        contextHash = StreamPreparedNativeContentHash.context(
            block.chainid, address(this), id, chosen.content.contentId
        );
    }

    /// @notice Sync reads are bounded and fail closed; ordinary purchases use only the local stop.
    function contestState(Context memory x, uint256 collection) public view returns (uint8 state) {
        if (
            address(x.artists).codehash != x.artistsHash || x.artistGas == 0
                || x.artistGas > type(uint64).max
        ) {
            revert CuratedAttributionReadFailed();
        }
        uint256 cap = x.artistGas;
        if (gasleft() < cap + (cap + 62) / 63 + 30000) revert CuratedAttributionReadFailed();
        bytes memory data =
            abi.encodeCall(IStreamArtistPlatformWorks.platformWorksContest, (collection));
        address target = address(x.artists);
        uint256[2] memory result;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(data, 32), mload(data), result, 64)
            size := returndatasize()
        }
        if (!ok || size != 64 || result[0] > 3) revert CuratedAttributionReadFailed();
        state = uint8(result[0]);
    }

    function _manifest(IStreamPreparedNativeContentPurchaseGate gate, Content.Publication memory p)
        private
        view
    {
        bytes memory raw = gate.manifestBytes();
        Content.Row[] memory rows = abi.decode(raw, (Content.Row[]));
        if (
            rows.length == 0 || rows.length != gate.itemCount() || keccak256(raw) != p.manifestHash
                || keccak256(abi.encode(rows)) != p.manifestHash
        ) revert CuratedSaleInvalid();
        bytes32[] memory level = new bytes32[](rows.length);
        for (uint256 n; n < rows.length; ++n) {
            if (
                (n != 0 && rows[n - 1].contentId >= rows[n].contentId) || rows[n].tokenDataHash == 0
                    || bytes(rows[n].previewURI).length == 0
            ) revert CuratedSaleInvalid();
            level[n] = StreamPreparedNativeContentHash.leaf(
                p.chainId, p.house, p.saleId, rows[n].contentId, rows[n].tokenDataHash
            );
        }
        uint256 width = level.length;
        while (width > 1) {
            uint256 next;
            for (uint256 n; n < width; n += 2) {
                bytes32 a = level[n];
                if (n + 1 == width) {
                    level[next] = a;
                } else {
                    bytes32 b = level[n + 1];
                    level[next] = a < b
                        ? keccak256(abi.encodePacked(a, b))
                        : keccak256(abi.encodePacked(b, a));
                }
                ++next;
            }
            width = next;
        }
        if (level[0] != p.manifestRoot) revert CuratedSaleInvalid();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamNativeImmediateSalesRuntime.sol";
import "./StreamNativeImmediateSalesRefunds.sol";
import "./StreamNativeImmediateSalesAdministration.sol";
import "./StreamImmediateSaleReveal.sol";
import "./StreamNativeSaleMint.sol";
import "../revenue/StreamSettlementContext.sol";
import "../parameters/StreamGasParameterHost.sol";
import "../../interfaces/stream/mint/IStreamImmediateSaleAuthorizationBinding.sol";
import "../../interfaces/stream/revenue/IStreamNativePublicSaleBinding.sol";
import "../../vendor/openzeppelin/Ownable.sol";
import "../../vendor/openzeppelin/ReentrancyGuard.sol";
import "../../vendor/openzeppelin/ERC165.sol";

/// @notice Canonical signed and unsigned public fixed/open native sales, one ERC721 per purchase.
/// @dev Existing DIRECT, native and Universal signature families are separate deployments.
contract StreamNativeImmediateSales is
    IStreamNativeImmediateSales,
    IStreamImmediateSaleAuthorizationBinding,
    IStreamNativePublicSaleBinding,
    StreamSettlementContext,
    StreamGasParameterHost,
    Ownable,
    ReentrancyGuard,
    ERC165
{
    struct DeploymentConfig {
        IStreamMintManager manager;
        IStreamPrimarySaleSettlement recorder;
        IStreamArtistAttribution artists;
        IStreamRoleRegistry roles;
        address authority;
        GasParameterConfig[3] parameters;
    }

    bytes32 private constant _SALE_SIGNATURE = keccak256("6529STREAM_GGP_SALE_ERC1271_GAS_LIMIT");
    bytes32 private constant _ARTIST = keccak256("6529STREAM_GGP_SALE_ARTIST_AUTHORITY_GAS_LIMIT");
    bytes32 private constant _REVEAL = keccak256("6529STREAM_GGP_REVEAL_ATTEMPT_GAS_LIMIT");
    IStreamMintManager public immutable mintManager;
    bytes32 public immutable mintManagerCodeHash;
    address public immutable primarySaleSettlement;
    bytes32 public immutable settlementCodeHash;
    IStreamArtistAttribution public immutable artistRegistry;
    bytes32 public immutable artistRegistryCodeHash;
    IStreamRoleRegistry public immutable roleRegistry;
    bytes32 public immutable roleRegistryCodeHash;
    StreamNativeImmediateSalesState.State private _state;

    constructor(DeploymentConfig memory d)
        StreamSettlementContext(d.recorder.revenueResolver(), d.recorder.moduleRegistry())
        StreamGasParameterHost(d.authority)
    {
        if (
            d.authority == address(0) || d.authority != splitFactory.governanceAuthority()
                || !StreamSettlementAdmission.isContract(address(d.manager))
                || !StreamSettlementAdmission.isContract(address(d.recorder))
                || !d.recorder.isStreamPrimarySaleSettlement() || d.recorder.core() != core
                || !IStreamMintReads(address(d.manager)).isStreamMintManager()
                || address(IStreamMintReads(address(d.manager)).core()) != core
                || address(IStreamMintReads(address(d.manager)).moduleRegistry()) != moduleRegistry
                || !StreamSaleArtist.supportsAttribution(d.artists) || d.artists.core() != core
                || revenueResolver.artistRegistry() != address(d.artists)
                || address(d.roles).code.length == 0
                || _read(address(d.roles), abi.encodeWithSignature("owner()"), gasleft())
                    != uint256(uint160(d.authority))
                || !IERC165(address(d.recorder))
                    .supportsInterface(type(IStreamNativePrimarySaleSettlement).interfaceId)
                || !IERC165(address(d.recorder))
                    .supportsInterface(type(IStreamNativePublicPrimarySaleSettlement).interfaceId)
        ) revert InvalidImmediateSale();
        bytes32[3] memory names = [
            keccak256("SALE_ERC1271_GAS_LIMIT"),
            keccak256("SALE_ARTIST_AUTHORITY_GAS_LIMIT"),
            keccak256("REVEAL_ATTEMPT_GAS_LIMIT")
        ];
        for (uint256 i; i < 3; ++i) {
            if (
                keccak256(bytes(d.parameters[i].name)) != names[i]
                    || d.parameters[i].failureClass != 2
            ) revert InvalidImmediateSale();
            _registerGasParameter(d.parameters[i]);
        }
        mintManager = d.manager;
        mintManagerCodeHash = address(d.manager).codehash;
        primarySaleSettlement = address(d.recorder);
        settlementCodeHash = address(d.recorder).codehash;
        artistRegistry = d.artists;
        artistRegistryCodeHash = address(d.artists).codehash;
        roleRegistry = d.roles;
        roleRegistryCodeHash = address(d.roles).codehash;
        _state.nextSaleNonce = 1;
    }

    function supportsInterface(bytes4 id) public view override returns (bool) {
        return id == type(IStreamNativeImmediateSales).interfaceId
            || id == type(IStreamNativeSaleBinding).interfaceId
            || id == type(IStreamNativePublicSaleBinding).interfaceId
            || id == type(IStreamImmediateSaleAuthorizationBinding).interfaceId
            || id == type(IStreamArtistSaleFacts).interfaceId
            || id == type(IStreamImmediateSaleReveal).interfaceId
            || id == type(IStreamGasParameterHost).interfaceId || id == type(IERC5267).interfaceId
            || super.supportsInterface(id);
    }

    function streamModuleType() external pure returns (bytes32) {
        return keccak256("NATIVE_PRIMARY_SALE_ADAPTER");
    }

    function streamModuleInterfaceId() external pure returns (bytes4) {
        return type(IStreamNativeSaleBinding).interfaceId;
    }

    function eip712Domain()
        external
        view
        override
        returns (bytes1, string memory, string memory, uint256, address, bytes32, uint256[] memory)
    {
        return (
            0x0f,
            "6529Stream Sales",
            "1",
            block.chainid,
            address(this),
            bytes32(0),
            new uint256[](0)
        );
    }

    function authorizationDigest(StreamPrivateSaleTypes.SaleAuthorization calldata a)
        external
        view
        override
        returns (bytes32)
    {
        return StreamPrivateSaleHash.digest(
            block.chainid, address(this), StreamPrivateSaleHash.authorizationBody(a)
        );
    }

    function saleIdFor(uint256 collection, bytes32 phase, uint256 nonce)
        external
        view
        override
        returns (bytes32)
    {
        return StreamNativeImmediateSalesRuntime.saleId(collection, phase, nonce);
    }

    function saleConfigurationHash(Configuration calldata config)
        external
        view
        override
        returns (bytes32)
    {
        return StreamNativeImmediateSalesRuntime.configurationHash(config);
    }

    function saleRecord(bytes32 id) external view override returns (Record memory) {
        return _state.sales[id];
    }

    function nextSaleNonce() external view returns (uint256) {
        return _state.nextSaleNonce;
    }

    function nextExecutionNonce(bytes32 id, address payer) public view override returns (uint256) {
        return _state.executionNonces[id][payer] + 1;
    }

    function executionReceipt(bytes32 id) external view override returns (Receipt memory) {
        return _state.receipts[id];
    }

    function executionStatus(bytes32 id) external view override returns (uint8) {
        return _state.executionStatus[id];
    }

    function saleConsentFacts(bytes32 id) external view override returns (uint256, bytes32) {
        Record storage r = _record(id);
        return (r.config.collectionId, r.configHash);
    }

    function nativeSaleLifecycleBinding(bytes32 id)
        external
        view
        returns (StreamNativeSettlementTypes.SaleLifecycleBinding memory)
    {
        return _record(id).lifecycle;
    }

    function publicNativeSaleBinding(bytes32 id)
        external
        view
        override
        returns (uint256, bytes32, bytes32, uint8)
    {
        Record storage r = _record(id);
        return (r.config.collectionId, r.config.phaseId, r.configHash, r.config.authorityMode);
    }

    function activePublicNativeCandidate(bytes32 id) external view override returns (bytes32) {
        return id != 0 && id == _state.activePublicId ? _state.activePublicCommitment : bytes32(0);
    }

    function immediateSaleAuthorizationBinding(bytes32 id)
        external
        view
        override
        returns (uint256, bytes32, uint8, uint8, bytes32, address, uint8)
    {
        Record storage r = _record(id);
        return (
            r.config.collectionId,
            r.config.phaseId,
            r.config.saleKind,
            r.config.authorityMode,
            r.configHash,
            r.config.signer.authorizer,
            r.config.signer.kind
        );
    }

    function configureCollectionSigner(
        uint256 collection,
        address signer,
        uint8 kind,
        bytes32 evidence,
        bool enabled
    ) external override onlyOwner nonReentrant {
        _requireContext();
        StreamNativeImmediateSalesAdministration.configureSigner(
            _state, collection, signer, kind, evidence, enabled
        );
    }

    function collectionSigner(uint256 collection, address signer, uint8 kind)
        external
        view
        override
        returns (SignerBinding memory, bool)
    {
        StreamNativeImmediateSalesState.Signer storage s = _state.signers[collection][signer][kind];
        return (s.binding, s.enabled);
    }

    function registerSale(Configuration calldata config)
        external
        override
        onlyOwner
        nonReentrant
        returns (bytes32)
    {
        _requireContext();
        return StreamNativeImmediateSalesRuntime.register(_state, _context(), config);
    }

    function closeSale(bytes32 id) external override onlyOwner nonReentrant {
        StreamNativeImmediateSalesAdministration.close(_state, id);
    }

    function setGlobalPause(bool value, bytes32 reason) external override nonReentrant {
        _pauseRole(value, reason);
        StreamNativeCuratedClock.setGlobal(_state.clocks, value);
        emit ImmediateSalePause(0, value, msg.sender, reason);
    }

    function setSalePause(bytes32 id, bool value, bytes32 reason) external override nonReentrant {
        _pauseRole(value, reason);
        StreamNativeCuratedClock.setSale(_state.clocks, id, _record(id).config.collectionId, value);
        emit ImmediateSalePause(id, value, msg.sender, reason);
    }

    function syncCollectionContest(uint256 collection) external override nonReentrant {
        _requireContext();
        StreamNativeImmediateSalesAdministration.syncContest(_state, _context().artist, collection);
    }

    function _pauseRole(bool value, bytes32 reason) private view {
        if (reason == 0) revert InvalidImmediateSale();
        StreamRefundWindowSupport.requireRole(
            address(roleRegistry),
            roleRegistryCodeHash,
            governanceAuthority,
            value ? keccak256("ROLE_PAUSE_GUARDIAN") : keccak256("ROLE_UNPAUSE")
        );
    }

    function previewSignedPurchase(
        Purchase calldata p,
        StreamPrivateSaleTypes.SaleAuthorization calldata a,
        IStreamPrivateSaleAdapter.Signature calldata proof
    )
        external
        view
        override
        returns (StreamNativeSettlementTypes.NativeSettlementCandidate memory c)
    {
        _requireContext();
        (c,) = StreamNativeImmediateSalesRuntime.prepare(_state, _context(), p, a, proof, 1);
    }

    function previewPublicPurchase(Purchase calldata p)
        external
        view
        override
        returns (StreamNativeSettlementTypes.NativeSettlementCandidate memory c, bytes32 id)
    {
        _requireContext();
        StreamPrivateSaleTypes.SaleAuthorization memory a;
        IStreamPrivateSaleAdapter.Signature memory proof;
        IStreamMintManager.MintBatch memory b;
        (c, b) = StreamNativeImmediateSalesRuntime.prepare(_state, _context(), p, a, proof, 2);
        return (c, b.authorizationId);
    }

    function purchaseSigned(
        Purchase calldata p,
        StreamPrivateSaleTypes.SaleAuthorization calldata a,
        IStreamPrivateSaleAdapter.Signature calldata proof
    ) external payable override nonReentrant returns (Receipt memory) {
        return _purchase(p, a, proof, 1);
    }

    function purchasePublic(Purchase calldata p)
        external
        payable
        override
        nonReentrant
        returns (Receipt memory)
    {
        StreamPrivateSaleTypes.SaleAuthorization memory a;
        IStreamPrivateSaleAdapter.Signature memory proof;
        return _purchase(p, a, proof, 2);
    }

    function _purchase(
        Purchase memory p,
        StreamPrivateSaleTypes.SaleAuthorization memory a,
        IStreamPrivateSaleAdapter.Signature memory proof,
        uint8 mode
    ) private returns (Receipt memory r) {
        if (msg.sender != p.payer || msg.sender != p.executor) {
            revert InvalidImmediateSale();
        }
        _requireContext();
        StreamNativeImmediateSalesRuntime.Context memory x = _context();
        (
            StreamNativeSettlementTypes.NativeSettlementCandidate memory c,
            IStreamMintManager.MintBatch memory b
        ) = StreamNativeImmediateSalesRuntime.prepare(_state, x, p, a, proof, mode);
        RevealQuote memory quote = StreamImmediateSaleReveal.quote(core, c.sale.collectionId);
        if (msg.value < c.sale.amount || (!quote.policy.declared && msg.value != c.sale.amount)) {
            revert ImmediateSaleValueInvalid(msg.value, c.sale.amount);
        }
        uint256 revealCap = gasParameter(_REVEAL);
        uint256 excess =
            StreamImmediateSaleReveal.preflight(quote, msg.value - c.sale.amount, revealCap);
        uint256 original = address(this).balance - msg.value;
        bytes32 id = c.executionBinding.executionId;
        if (_state.executionStatus[id] != 0 || _state.activePublicId != 0) {
            revert ImmediateSaleResultMismatch();
        }
        _state.executionNonces[p.saleId][p.payer] = p.executionNonce;
        ++_state.sales[p.saleId].soldQuantity;
        r = Receipt(
            p.saleId,
            id,
            b.authorizationId,
            c.executionBinding.saleAuthorizationDigest,
            c.operationIdentityCommitment,
            c.operationId,
            0,
            0,
            c.sale.amount,
            quote.policy.revealFeePerTokenWei,
            excess
        );
        _state.receipts[id] = r;
        _state.executionStatus[id] = 1;
        if (mode == 2) {
            _state.activePublicId = id;
            _state.activePublicCommitment =
                StreamNativeSettlementHash.candidateCommitment(primarySaleSettlement, c);
        }
        emit ImmediateSaleExecution(p.saleId, id, r.operationRoot, 1, r);
        StreamPrimarySettlementTypes.PrimarySettlementResult memory result =
            StreamNativeImmediateSalesRuntime.settle(x, c);
        _retained(x, c);
        r.tokenId = StreamNativeSaleMint.execute(
            mintManager, b, c.operationIdentityCommitment, c.operationId
        );
        StreamImmediateSaleReveal.fundAndAttempt(
            core, c.sale.collectionId, r.tokenId, quote, revealCap
        );
        _retained(x, c);
        if (address(this).balance != original + excess) revert SaleRevealAccountingMismatch();
        r.settlementKey = result.settlementKey;
        StreamNativeImmediateSalesRefunds.credit(_state, p.saleId, p.payer, excess);
        _state.receipts[id] = r;
        _state.executionStatus[id] = 2;
        delete _state.activePublicId;
        delete _state.activePublicCommitment;
        Record storage sale = _state.sales[p.saleId];
        if (sale.config.saleSupplyLimit != 0 && sale.soldQuantity == sale.config.saleSupplyLimit) {
            sale.closed = true;
            emit ImmediateSaleClosed(p.saleId, sale.soldQuantity);
        }
        emit ImmediateSaleExecution(p.saleId, id, r.operationRoot, 2, r);
    }

    function _retained(
        StreamNativeImmediateSalesRuntime.Context memory x,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) private view {
        _requireContext();
        StreamNativeImmediateSalesRuntime.retained(_state, x, c);
    }

    function saleRevealQuote(bytes32 id) external view override returns (RevealQuote memory) {
        return StreamImmediateSaleReveal.quote(core, _record(id).config.collectionId);
    }

    function refundLiability() external view override returns (uint256) {
        return _state.refundLiability;
    }

    function refundableBalance(bytes32 id, address payer) external view override returns (uint256) {
        return _state.refunds[id][payer];
    }

    function refundAccountCount() external view override returns (uint256) {
        return _state.refundPayers.length;
    }

    function refundAccountAt(uint256 i) external view override returns (bytes32, address) {
        return (_state.refundSales[i], _state.refundPayers[i]);
    }

    function claimRefund(bytes32 id, address recipient) external override nonReentrant {
        StreamNativeImmediateSalesRefunds.claim(_state, id, recipient);
    }

    function _record(bytes32 id) private view returns (Record storage r) {
        r = _state.sales[id];
        if (r.saleNonce == 0) revert ImmediateSaleUnavailable(id);
    }

    function _context() private view returns (StreamNativeImmediateSalesRuntime.Context memory x) {
        x.artist = StreamNativeCuratedSaleSupport.Context(
            core,
            moduleRegistry,
            mintManager,
            revenueResolver,
            artistRegistry,
            artistRegistryCodeHash,
            gasParameter(_ARTIST)
        );
        x.recorder = primarySaleSettlement;
        x.recorderHash = settlementCodeHash;
        x.managerHash = mintManagerCodeHash;
        x.signatureGas = gasParameter(_SALE_SIGNATURE);
    }

    function transferOwnership(address next) public override onlyOwner nonReentrant {
        super.transferOwnership(next);
    }

    function renounceOwnership() public override onlyOwner nonReentrant {
        super.renounceOwnership();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamNativeImmediateSalesState.sol";
import "./StreamNativeCuratedSaleSupport.sol";

/// @notice Fixed configuration and stop operations behind the adapter's owner and reentrancy guards.
library StreamNativeImmediateSalesAdministration {
    event ImmediateSaleSignerConfigured(
        uint256 indexed collectionId,
        address indexed authorizer,
        uint8 kind,
        IStreamNativeImmediateSales.SignerBinding binding,
        bool enabled
    );
    event ImmediateSaleClosed(bytes32 indexed saleId, uint64 soldQuantity);
    event ImmediateSaleContestSynced(
        uint256 indexed collectionId, uint8 contestState, bool stopped
    );

    function configureSigner(
        StreamNativeImmediateSalesState.State storage state,
        uint256 collection,
        address signer,
        uint8 kind,
        bytes32 evidence,
        bool enabled
    ) public {
        if (collection == 0 || signer == address(0) || (kind != 1 && kind != 2) || evidence == 0) {
            revert IStreamNativeImmediateSales.InvalidImmediateSale();
        }
        StreamNativeImmediateSalesState.Signer storage s = state.signers[collection][signer][kind];
        s.binding = IStreamNativeImmediateSales.SignerBinding(
            signer, kind, evidence, s.binding.revision + 1, msg.sender
        );
        s.enabled = enabled;
        emit ImmediateSaleSignerConfigured(collection, signer, kind, s.binding, enabled);
    }

    function close(StreamNativeImmediateSalesState.State storage state, bytes32 id) public {
        IStreamNativeImmediateSales.Record storage r = state.sales[id];
        if (r.saleNonce == 0 || r.closed) {
            revert IStreamNativeImmediateSales.ImmediateSaleUnavailable(id);
        }
        r.closed = true;
        emit ImmediateSaleClosed(id, r.soldQuantity);
    }

    function syncContest(
        StreamNativeImmediateSalesState.State storage state,
        StreamNativeCuratedSaleSupport.Context memory context,
        uint256 collection
    ) public {
        uint8 contest = StreamNativeCuratedSaleSupport.contestState(context, collection);
        bool stopped = contest == 1 || contest == 3;
        StreamNativeCuratedClock.Point[] storage history = state.clocks.collections[collection];
        bool prior = history.length != 0 && history[history.length - 1].stopped;
        if (prior != stopped) {
            StreamNativeCuratedClock.setCollection(state.clocks, collection, stopped);
        }
        emit ImmediateSaleContestSynced(collection, contest, stopped);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamNativeImmediateSalesState.sol";

/// @notice Payer-owned reveal credits in the guarded immediate adapter's storage context.
/// @dev Fixed compiler link preserves caller, balance, events and atomic refund effects.
library StreamNativeImmediateSalesRefunds {
    event SalePaymentExcessCredited(
        uint16 schemaVersion, bytes32 indexed saleId, address indexed payer, uint256 amount
    );
    event SaleRefundClaimed(
        uint16 schemaVersion,
        bytes32 indexed saleId,
        address indexed payer,
        address indexed recipient,
        uint256 amount
    );

    function claim(
        StreamNativeImmediateSalesState.State storage state,
        bytes32 id,
        address recipient
    ) public {
        uint256 amount = state.refunds[id][msg.sender];
        if (amount == 0) revert IStreamImmediateSaleReveal.SaleRefundEmpty(id, msg.sender);
        if (recipient == address(0) || recipient == address(this)) {
            revert IStreamImmediateSaleReveal.SaleRefundTransferFailed(recipient);
        }
        uint256 before_ = address(this).balance;
        if (before_ < state.refundLiability) {
            revert IStreamImmediateSaleReveal.SaleRevealAccountingMismatch();
        }
        delete state.refunds[id][msg.sender];
        state.refundLiability -= amount;
        bool ok;
        assembly ("memory-safe") { ok := call(gas(), recipient, amount, 0, 0, 0, 0) }
        if (!ok) revert IStreamImmediateSaleReveal.SaleRefundTransferFailed(recipient);
        if (address(this).balance != before_ - amount) {
            revert IStreamImmediateSaleReveal.SaleRevealAccountingMismatch();
        }
        emit SaleRefundClaimed(1, id, msg.sender, recipient, amount);
    }

    function credit(
        StreamNativeImmediateSalesState.State storage state,
        bytes32 id,
        address payer,
        uint256 amount
    ) public {
        if (amount == 0) return;
        if (!state.refundSeen[id][payer]) {
            state.refundSeen[id][payer] = true;
            state.refundSales.push(id);
            state.refundPayers.push(payer);
        }
        state.refunds[id][payer] += amount;
        state.refundLiability += amount;
        emit SalePaymentExcessCredited(1, id, payer, amount);
    }
}

