    ) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PREPARED_NATIVE_CONTENT_ADMISSION_V1"),
                block.chainid,
                house,
                intent,
                content
            )
        );
    }
}

