// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/auctions/IStreamCustodyRightsAuction.sol";
import "../../interfaces/stream/revenue/StreamNativeCustodySettlementTypes.sol";
import "../../interfaces/stream/revenue/StreamPrimarySettlementTypes.sol";
import "../../vendor/openzeppelin/IERC165.sol";

/// @notice New domains retain the full append-only activation; old custody preimages are unchanged.
library StreamCustodyRightsHash {
    function digest(address house, StreamCustodyRightsTypes.Authorization memory a)
        public
        view
        returns (bytes32)
    {
        bytes32 domain = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256("6529StreamCustodyRightsAllowCurrent"),
                keccak256("1"),
                block.chainid,
                house
            )
        );
        return keccak256(
            abi.encodePacked(
                hex"1901",
                domain,
                keccak256(
                    abi.encode(
                        keccak256(
                            "CustodyRightsActivation(bytes32 auctionId,bytes32 baseConfigHash,bytes32 originHash,uint256 tokenId,uint8 rightsMode,bytes32 assignmentHash,bytes32 primaryPolicyHash,uint8 primaryPolicyMode,address artist,bytes32 nonce,uint64 deadline)"
                        ),
                        a
                    )
                )
            )
        );
    }

    function configuration(address house, StreamCustodyRightsTypes.Activation memory a)
        public
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_CUSTODY_RIGHTS_ALLOW_CURRENT_CONFIG_V1"),
                block.chainid,
                house,
                a.authorization,
                a.authorizationDigest
            )
        );
    }

    function readOptional(address house, bytes32 id)
        public
        view
        returns (StreamCustodyRightsTypes.Activation memory a)
    {
        if (IERC165(house).supportsInterface(type(IStreamCustodyRightsAuction).interfaceId)) {
            return IStreamCustodyRightsAuction(house).custodyRightsActivation(id);
        }
    }

    function requireLegacy(address house, bytes32 id) public view {
        if (readOptional(house, id).authorizationDigest != 0) {
            revert IStreamCustodyRightsAuction.CustodyRightsEntryRequired(id);
        }
    }

    function execution(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamCustodyRightsTypes.Activation memory a
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_CUSTODY_RIGHTS_EXECUTION_V1"),
                block.chainid,
                recorder,
                house,
                f,
                a
            )
        );
    }

    function facts(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamCustodyRightsTypes.Activation memory a
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_CUSTODY_RIGHTS_FACTS_V1"),
                block.chainid,
                recorder,
                house,
                f,
                a
            )
        );
    }

    function candidate(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamCustodyRightsTypes.Activation memory a,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        bytes32 beneficiaryHash
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_CUSTODY_RIGHTS_CANDIDATE_V1"),
                block.chainid,
                recorder,
                house,
                f,
                a,
                c,
                beneficiaryHash
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamCustodyRightsValidation.sol";
import "../../interfaces/stream/revenue/IStreamCustodyRightsSettlement.sol";
import "./StreamNativePrimaryExecution.sol";
import "./StreamScopedNativePrimaryExecution.sol";
import "./StreamPrimarySettlementEmission.sol";
import "./StreamPrimarySettlementHash.sol";

/// @notice Official payment before custody delivery, with no mint or ledger operation.
library StreamCustodyRightsRecording {
    struct Context {
        StreamNativeCustodyPrimaryAdmission.Context admission;
        bytes32 resolverHash;
        StreamNativePrimaryExecution.Context funding;
    }
    event CustodyRightsRevenueRecorded(
        uint16 schemaVersion,
        bytes32 indexed settlementKey,
        bytes32 indexed saleKey,
        bytes32 indexed factsHash,
        StreamNativeCustodySettlementTypes.Facts facts,
        StreamCustodyRightsTypes.Activation activation,
        bytes32 beneficiaryHash,
        StreamPrimarySettlementTypes.PrimarySettlementResult result
    );

    function execute(
        Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        mapping(bytes32 => bool) storage saleConsumed,
        mapping(bytes32 => bool) storage consumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage results,
        mapping(bytes32 => bytes32) storage factsHashes,
        mapping(bytes32 => uint256) storage official,
        mapping(address => uint256) storage total,
        bytes32 id
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory r) {
        requireContext(x);
        (
            StreamNativeCustodySettlementTypes.Facts memory f,
            StreamCustodyRightsTypes.Activation memory activation
        ) = StreamCustodyRightsValidation.read(x.admission, pin, id);
        if (
            msg.value != f.auction.winner.amount
                || f.auction.winner.payer == address(x.funding.escrow)
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected,
            bytes32 beneficiaryHash
        ) = StreamCustodyRightsValidation.derive(
            x.funding.rights, f, activation, msg.sender, address(this)
        );
        if (c.sale.payer == selected.wallet) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 saleKey = StreamPreparedNativeSettlementHash.saleKey(
            address(this), msg.sender, f.auction.saleId, f.auction.saleNonce
        );
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            address(this), msg.sender, c.executionBinding.executionId
        );
        if (saleConsumed[saleKey] || consumed[key]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(key);
        }
        saleConsumed[saleKey] = true;
        consumed[key] = true;
        bool escrowed = StreamScopedNativePrimaryExecution.fund(
            x.funding,
            c.sale.collectionId,
            c.sale.tokenId,
            activation.authorization.rightsMode,
            c.sale.poster,
            c.sale.amount,
            selected,
            beneficiaryHash
        );
        requireContext(x);
        (
            StreamNativeCustodySettlementTypes.Facts memory after_,
            StreamCustodyRightsTypes.Activation memory afterActivation
        ) = StreamCustodyRightsValidation.read(x.admission, pin, id);
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory afterCandidate,,
            bytes32 afterBeneficiaries
        ) = StreamCustodyRightsValidation.derive(
            x.funding.rights, after_, afterActivation, msg.sender, address(this)
        );
        if (
            keccak256(abi.encode(f)) != keccak256(abi.encode(after_))
                || keccak256(abi.encode(activation)) != keccak256(abi.encode(afterActivation))
                || keccak256(abi.encode(c)) != keccak256(abi.encode(afterCandidate))
                || beneficiaryHash != afterBeneficiaries
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 factsHash = StreamCustodyRightsHash.facts(address(this), msg.sender, f, activation);
        r = StreamPrimarySettlementTypes.PrimarySettlementResult(
            StreamCustodyRightsHash.candidate(
                address(this), msg.sender, f, activation, c, beneficiaryHash
            ),
            key,
            selected.profileId,
            selected.wallet,
            address(0),
            c.sale.amount,
            c.executor,
            c.executionBinding.executionId,
            escrowed,
            0,
            0,
            0
        );
        results[key] = r;
        factsHashes[key] = factsHash;
        official[
            keccak256(
                abi.encode(
                    keccak256("6529STREAM_OFFICIAL_PRIMARY_SETTLED_V1"),
                    keccak256("PRIMARY_SALE"),
                    selected.profileId,
                    selected.wallet,
                    address(0)
                )
            )
        ] += r.amount;
        total[address(0)] += r.amount;
        StreamPrimarySettlementEmission.emitSettlement(
            c, r, address(0), activation.authorization.primaryPolicyHash
        );
        emit CustodyRightsRevenueRecorded(
            1, key, saleKey, factsHash, f, activation, beneficiaryHash, r
        );
    }

    function requireContext(Context memory x) private view {
        StreamSettlementAdmission.requireRegistry(
            x.admission.core, x.admission.coreHash, x.admission.registry, x.admission.registryHash
        );
        if (
            address(x.funding.rights.resolver).codehash != x.resolverHash
                || address(x.funding.rights.factory).codehash != x.funding.factoryHash
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamNativeCustodyPrimaryValidation.sol";
import "./StreamCustodyRightsHash.sol";
import "./StreamDefaultPrimaryProfile.sol";
import { StreamScopedSaleTemplate } from "../mint/StreamScopedSaleTemplate.sol";
import { StreamDefaultSaleTemplate } from "../mint/StreamDefaultSaleTemplate.sol";

library StreamCustodyRightsValidation {
    function activation(address house, StreamNativeCustodySettlementTypes.Facts memory f)
        public
        view
        returns (StreamCustodyRightsTypes.Activation memory a)
    {
        a = StreamCustodyRightsHash.readOptional(house, f.auctionId);
        StreamCustodyRightsTypes.Authorization memory q = a.authorization;
        if (
            a.authorizationDigest == 0 || q.auctionId != f.auctionId
                || q.baseConfigHash != f.auction.configHash
                || q.originHash != keccak256(abi.encode(f.origin)) || q.tokenId != f.auction.tokenId
                || q.primaryPolicyMode != 1 || q.rightsMode < 1 || q.rightsMode > 7
                || q.assignmentHash == 0 || q.primaryPolicyHash == 0 || q.artist == address(0)
                || q.nonce == 0 || a.authorizationDigest != StreamCustodyRightsHash.digest(house, q)
                || a.effectiveConfigHash != StreamCustodyRightsHash.configuration(house, a)
        ) {
            revert IStreamCustodyRightsAuction.InvalidCustodyRights();
        }
    }

    function read(
        StreamNativeCustodyPrimaryAdmission.Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        bytes32 id
    )
        public
        view
        returns (
            StreamNativeCustodySettlementTypes.Facts memory f,
            StreamCustodyRightsTypes.Activation memory a
        )
    {
        f = StreamNativeCustodyPrimaryValidation.read(x, pin, id);
        a = activation(msg.sender, f);
    }

    function selection(
        StreamPrimarySettlementRights.Context memory x,
        uint256 collection,
        uint256 token,
        uint8 mode,
        address poster
    )
        public
        view
        returns (StreamSaleTemplate.Selection memory selected, bytes32 policy, bytes32 witness)
    {
        if (token == 0) {
            revert IStreamCustodyRightsAuction.InvalidCustodyRights();
        }
        if (mode == 1) {
            selected = StreamDefaultPrimaryProfile.resolve(x.resolver, collection, token);
        } else if (mode >= 5 && mode <= 7) {
            (selected, witness) =
                StreamDefaultSaleTemplate.resolve(x.resolver, collection, token, mode, poster);
        } else {
            IStreamRevenueResolver.ResolvedPrimaryAssignment memory actual =
                x.resolver.resolvePrimaryAssignment(collection, token, keccak256("PRIMARY_SALE"));
            (selected, witness) = StreamScopedSaleTemplate.preview(
                x.resolver, collection, token, mode, poster, actual
            );
        }
        policy = keccak256(
            abi.encode(
                keccak256("6529STREAM_PRIMARY_POLICY_V1"),
                block.chainid,
                address(x.resolver),
                keccak256("PRIMARY_SALE"),
                collection,
                token,
                selected.templateId,
                selected.profileId,
                selected.wallet,
                selected.assignmentHash
            )
        );
    }

    function derive(
        StreamPrimarySettlementRights.Context memory x,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamCustodyRightsTypes.Activation memory a,
        address house,
        address recorder
    )
        public
        view
        returns (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected,
            bytes32 beneficiaryHash
        )
    {
        bytes32 policy;
        (selected, policy, beneficiaryHash) = selection(
            x,
            f.auction.config.collectionId,
            f.auction.tokenId,
            a.authorization.rightsMode,
            f.auction.config.poster
        );
        IStreamNativeEnglishAuction.Auction memory sale = f.auction;
        c.saleAdapter = house;
        c.executor = sale.winner.executor;
        c.sale = StreamPrimarySettlementTypes.PrimarySale(
            sale.saleId,
            keccak256("PRIMARY_SALE"),
            1,
            sale.config.collectionId,
            sale.tokenId,
            sale.saleNonce,
            sale.winner.payer,
            sale.config.poster,
            sale.winner.deliverTo,
            sale.winner.amount,
            policy
        );
        c.lifecycleBinding.saleCreatedAt = sale.lifecycle.saleCreatedAt;
        c.lifecycleBinding.saleAdapterRegistryRevision = sale.lifecycle.saleAdapterRegistryRevision;
        c.executionBinding = StreamPrimarySettlementTypes.SaleExecutionBinding(
            StreamCustodyRightsHash.execution(recorder, house, f, a),
            sale.winner.bidIndex,
            sale.winner.signed ? 1 : 2,
            sale.winner.authorizationDigest
        );
        c.orchestrationOrder = 3;
        c.rights = StreamPrimarySettlementTypes.PrimaryRights(
            selected.profileId,
            selected.wallet,
            selected.templateId,
            selected.assignmentHash,
            selected.entriesHash
        );
        c.saleExecutionHash = StreamCustodyRightsHash.facts(recorder, house, f, a);
    }
}

