pragma solidity ^0.8.19;

import "./StreamSettlementAdmission.sol";
import "../../interfaces/stream/revenue/IStreamDeferredNativeSaleBinding.sol";

/// @notice Linked deferred-native policy over the canonical registry, separate from immediate admission.
/// @dev Record/lifecycle predicates preserve the accepted85557c99 bounded reader semantics.
library StreamDeferredNativeSettlementAdmission {
    bytes32 private constant VERSION = keccak256("6529STREAM_UNIVERSAL_SETTLEMENT_V1");
    bytes32 private constant ROLE = keccak256("NATIVE_REFUND_WINDOW_SALE_ADAPTER");

    struct ModuleFacts {
        uint8 status;
        uint64 registeredAt;
        uint64 statusUpdatedAt;
        uint64 revision;
    }
    error SettlementModuleReadFailed(address module);
    error SettlementModuleReadMalformed(address module, uint256 length);
    error SettlementModuleNotAdmitted(address module);
    error SaleLifecycleReadFailed(address module);
    error SaleLifecycleReadMalformed(address module, uint256 length);
    error SaleLifecycleMismatch(address module, bytes32 saleId);

    function capture(address registry, address sale)
        public
        view
        returns (StreamNativeSettlementTypes.SaleLifecycleBinding memory)
    {
        ModuleFacts memory facts =
            _record(registry, sale, ROLE, type(IStreamDeferredNativeSaleBinding).interfaceId);
        if (facts.status != 1) revert SettlementModuleNotAdmitted(sale);
        if (block.timestamp == 0 || block.timestamp > type(uint64).max) {
            revert SaleLifecycleMismatch(sale, 0);
        }
        return
            StreamNativeSettlementTypes.SaleLifecycleBinding(
                uint64(block.timestamp), facts.revision
            );
    }

    function requireAdmission(
        address registry,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) public view {
        ModuleFacts memory facts =
            _record(
                registry, c.saleAdapter, ROLE, type(IStreamDeferredNativeSaleBinding).interfaceId
            );
        bytes memory data = abi.encodeCall(
            IStreamNativeSaleBinding.nativeSaleLifecycleBinding, (c.sale.settlementId)
        );
        uint256[2] memory words;
        bool ok;
        uint256 size;
        address sale = c.saleAdapter;
        assembly ("memory-safe") {
            ok := staticcall(gas(), sale, add(data, 32), mload(data), words, 64)
            size := returndatasize()
        }
        if (!ok) revert SaleLifecycleReadFailed(sale);
        if (size != 64 || words[0] > type(uint64).max || words[1] > type(uint64).max) {
            revert SaleLifecycleReadMalformed(sale, size);
        }
        if (
            words[0] == 0 || words[0] > block.timestamp
                || words[0] != c.lifecycleBinding.saleCreatedAt
                || words[1] != c.lifecycleBinding.saleAdapterRegistryRevision
        ) revert SaleLifecycleMismatch(sale, c.sale.settlementId);
        _requireLifecycle(facts, sale, uint64(words[0]), uint64(words[1]));
    }

    function isContract(address target) private view returns (bool) {
        return StreamSettlementAdmission.isContract(target);
    }

    function _requireLifecycle(
        ModuleFacts memory facts,
        address module,
        uint64 created,
        uint64 revision
    ) private pure {
        if (
            revision == 0 || revision > facts.revision || created < facts.registeredAt
                || (facts.status == 2
                    && (created >= facts.statusUpdatedAt || revision >= facts.revision))
        ) revert SettlementModuleNotAdmitted(module);
    }

    function _record(address registry, address module, bytes32 role, bytes4 interfaceId)
        private
        view
        returns (ModuleFacts memory facts)
    {
        if (!isContract(module)) revert SettlementModuleNotAdmitted(module);
        bytes memory data = abi.encodeCall(IStreamModuleRegistry.moduleRecord, (module));
        // Dynamic struct return: outer offset; twelve-word head; URI byte length.
        uint256[14] memory words;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), registry, add(data, 32), mload(data), words, 448)
            size := returndatasize()
        }
        if (!ok) revert SettlementModuleReadFailed(module);
        if (
            size < 448 || words[0] != 32 || words[1] > 3 || words[5] > type(uint32).max
                || words[9] != 384 || words[10] > type(uint64).max || words[11] > type(uint64).max
                || words[12] > type(uint64).max || words[13] > size - 448
                || size - 448 != ((words[13] + 31) / 32) * 32
        ) revert SettlementModuleReadMalformed(module, size);
        if (
            (words[1] != 1 && words[1] != 2) || bytes32(words[2]) != role
                || bytes32(words[3]) != VERSION || words[4] != uint256(uint32(interfaceId)) << 224
                || bytes32(words[6]) != module.codehash || words[7] == 0 || words[8] == 0
                || words[10] == 0 || words[10] > block.timestamp || words[11] < words[10]
                || words[11] > block.timestamp || words[12] == 0
        ) revert SettlementModuleNotAdmitted(module);
        // Match canonical registry live eligibility's exact-code ERC165 policy, including
        // its available-gas probes; DEPRECATED cannot use isModuleEligible's ACTIVE-only path.
        if (
            !_interface(module, 0x01ffc9a7, true) || !_interface(module, 0xffffffff, false)
                || !_interface(module, interfaceId, true)
        ) {
            revert SettlementModuleNotAdmitted(module);
        }
        facts =
            ModuleFacts(uint8(words[1]), uint64(words[10]), uint64(words[11]), uint64(words[12]));
    }

    function _interface(address target, bytes4 id, bool expected) private view returns (bool) {
        bytes memory data = abi.encodeWithSelector(bytes4(0x01ffc9a7), id);
        bool ok;
        uint256 size;
        uint256 word;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            word := mload(0)
        }
        return ok && size == 32 && word == (expected ? 1 : 0);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/StreamDeferredNativeSettlementTypes.sol";

/// @notice Distinct deferred identity domains; the existing official settlement key is unchanged.
library StreamDeferredNativeSettlementHash {
    function candidateCommitment(
        address recorder,
        StreamDeferredNativeSettlementTypes.DeferredNativeCandidate memory c
    ) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_DEFERRED_NATIVE_SETTLEMENT_CANDIDATE_V1"),
                block.chainid,
                recorder,
                c
            )
        );
    }

    /// @dev Immutable purchase record commits payer, price, original authorization and envelope.
    ///      The recorder must also consume purchaseKey: recomputing an execution identity with
    ///      another finalizer or current policy never permits paying one purchase twice.
    function executionId(StreamDeferredNativeSettlementTypes.DeferredNativeCandidate memory c)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_DEFERRED_NATIVE_SALE_EXECUTION_V1"),
                block.chainid,
                c.execution.saleAdapter,
                c.purchaseId,
                c.purchaseRecordHash,
                c.execution.executor,
                c.execution.executionBinding.saleAuthorizationDigest,
                c.execution.currentPolicyHash,
                c.execution.boundPolicyHash,
                c.execution.operationIdentityCommitment
            )
        );
    }

    function purchaseKey(address recorder, address saleAdapter, bytes32 purchaseId)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_DEFERRED_PURCHASE_SETTLEMENT_V1"),
                block.chainid,
                recorder,
                saleAdapter,
                purchaseId
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamDeferredNativeSettlementAdmission.sol";
import "./StreamDeferredNativeSettlementHash.sol";
import "../../interfaces/stream/revenue/IStreamPrimarySaleSettlement.sol";

/// @notice Exact deferred-native admission, separate from either immediate funding entry.
library StreamDeferredNativeSettlementValidation {
    struct Bindings {
        address core;
        address registry;
        address resolver;
        address escrow;
    }

    function validate(
        Bindings memory x,
        StreamDeferredNativeSettlementTypes.DeferredNativeCandidate memory d
    ) public view {
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c = d.execution;
        if (
            msg.sender != c.saleAdapter || c.saleAdapter == address(0) || c.executor == address(0)
                || c.sale.settlementId == 0 || c.sale.revenueClass != keccak256("PRIMARY_SALE")
                || c.sale.policyMode != 1 || c.sale.collectionId == 0 || c.sale.tokenId != 0
                || c.sale.saleNonce == 0 || c.sale.payer == address(0)
                || c.sale.payer == address(this) || c.sale.payer == c.saleAdapter
                || c.sale.payer == c.rights.wallet || c.sale.payer == x.escrow
                || c.sale.beneficiary == address(0) || c.sale.amount == 0
                || msg.value != c.sale.amount || c.sale.expectedPrimaryPolicyHash == 0
                || c.orchestrationOrder != 1 || c.executionBinding.authorityMode != 1
                || c.executionBinding.executionNonce == 0
                || c.executionBinding.saleAuthorizationDigest == 0
                || c.operationIdentityCommitment == 0 || c.operationId == 0
                || c.currentPolicyHash == 0 || c.boundPolicyHash == 0
                || c.saleExecutionHash != d.purchaseRecordHash || d.purchaseRecordHash == 0
                || d.purchaseId == 0 || d.originalPrimaryPolicyHash == 0
                || c.executionBinding.executionId
                    != StreamDeferredNativeSettlementHash.executionId(d)
        ) revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        uint256 refund = uint256(d.nominalRefundDeadline) + d.pauseToll;
        uint256 finalDeadline = uint256(d.nominalFinalizeBy) + d.pauseToll;
        if (refund > d.absoluteEscapeDeadline) refund = d.absoluteEscapeDeadline;
        if (finalDeadline > d.absoluteEscapeDeadline) finalDeadline = d.absoluteEscapeDeadline;
        if (
            d.nominalRefundDeadline == 0 || d.nominalFinalizeBy <= d.nominalRefundDeadline
                || d.nominalFinalizeBy > d.maximumNominalFinalizeBy
                || d.nominalFinalizeBy > d.absoluteEscapeDeadline
                || d.effectiveRefundDeadline != refund || d.effectiveFinalizeBy != finalDeadline
                || block.timestamp < refund || block.timestamp > finalDeadline
        ) {
            revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        }
        StreamDeferredNativeSettlementAdmission.requireAdmission(x.registry, c);
        requireBindings(x, c);
        if (
            _word(
                    c.saleAdapter,
                    abi.encodeCall(
                        IStreamDeferredNativeSaleBinding.activeDeferredNativeSettlement,
                        (d.purchaseId)
                    )
                )
                != uint256(StreamDeferredNativeSettlementHash.candidateCommitment(address(this), d))
        ) {
            revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        }
    }

    function requireBindings(
        Bindings memory x,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) public view {
        if (
            _word(c.saleAdapter, abi.encodeWithSignature("primarySaleSettlement()"))
                    != uint256(uint160(address(this)))
                || _word(c.saleAdapter, abi.encodeWithSignature("core()"))
                    != uint256(uint160(x.core))
                || _word(c.saleAdapter, abi.encodeWithSignature("moduleRegistry()"))
                    != uint256(uint160(x.registry))
                || _word(c.saleAdapter, abi.encodeWithSignature("revenueResolver()"))
                    != uint256(uint160(x.resolver))
                || _word(c.saleAdapter, abi.encodeWithSignature("mintManager()"))
                    != uint256(uint160(c.mintManager))
                || !StreamSettlementAdmission.isContract(c.mintManager)
                || _word(c.mintManager, abi.encodeWithSignature("core()"))
                    != uint256(uint160(x.core))
                || _word(c.mintManager, abi.encodeWithSignature("moduleRegistry()"))
                    != uint256(uint160(x.registry))
        ) {
            revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        }
    }

    function _word(address target, bytes memory data) private view returns (uint256 value) {
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            value := mload(0)
        }
        if (!ok || size != 32) revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
    }
}

