// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamEscrowRecoveryState as S } from "./StreamEscrowRecoveryState.sol";
import {
    StreamEscrowRecoveryTypes as R
} from "../../interfaces/stream/revenue/StreamEscrowRecoveryTypes.sol";
import {
    IStreamGasParameterHost as G
} from "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";

/// @notice Original escrow EIP-712 consent and cap-independent direct recording.
/// @dev Accounts may pre-consent to a fully specified recovery ID before its delayed
///      scheduling. That confers no sweep authority and never replaces affected-set proof.
library StreamEscrowRecoveryConsent {
    bytes32 private constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    bytes32 private constant ERC1271_GAS = keccak256("6529STREAM_GGP_ERC_1271_GAS_LIMIT");
    uint256 private constant HALF_ORDER =
        0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0;
    bytes4 private constant MAGIC = 0x1626ba7e;

    event EscrowRecoveryConsentRecorded(
        uint16 schemaVersion, bytes32 indexed recoveryId, address indexed account, bytes32 nonce
    );
    event EscrowRecoveryConsentRevoked(
        uint16 schemaVersion, bytes32 indexed recoveryId, address indexed account
    );

    function domainSeparator() public view returns (bytes32) {
        return keccak256(
            abi.encode(
                DOMAIN_TYPEHASH,
                keccak256("6529StreamRevenueEscrow"),
                keccak256("1"),
                block.chainid,
                address(this)
            )
        );
    }

    function digest(address account, bytes32 id, bytes32 nonce, uint64 deadline)
        public
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encodePacked(
                bytes2(0x1901),
                domainSeparator(),
                keccak256(abi.encode(R.CONSENT_TYPEHASH, account, id, nonce, deadline))
            )
        );
    }

    function submit(
        address account,
        bytes32 id,
        bytes32 nonce,
        uint64 deadline,
        bytes calldata signature
    ) public {
        _available(account, id, nonce);
        if (
            deadline < block.timestamp
                || !_valid(account, digest(account, id, nonce, deadline), signature)
        ) {
            revert S.EscrowRecoveryConsentInvalid();
        }
        _record(account, id, nonce);
    }

    function record(bytes32 id, bytes32 nonce) public {
        _available(msg.sender, id, nonce);
        _record(msg.sender, id, nonce);
    }

    function revoke(bytes32 id) public {
        S.State storage s = S.state();
        if (
            s.recoveries[id].record.status == R.EscrowRecoveryStatus.EXECUTED
                || !s.consents[id][msg.sender]
        ) revert S.EscrowRecoveryConsentInvalid();
        s.consents[id][msg.sender] = false;
        emit EscrowRecoveryConsentRevoked(1, id, msg.sender);
    }

    function recorded(bytes32 id, address account) public view returns (bool) {
        return S.state().consents[id][account];
    }

    function nonceUsed(address account, bytes32 nonce) public view returns (bool) {
        return S.state().usedConsentNonces[account][nonce];
    }

    function _available(address account, bytes32 id, bytes32 nonce) private view {
        S.State storage s = S.state();
        if (
            account == address(0) || id == 0 || s.usedConsentNonces[account][nonce]
                || s.recoveries[id].record.status == R.EscrowRecoveryStatus.EXECUTED
                || s.recoveries[id].record.status == R.EscrowRecoveryStatus.CANCELLED
        ) {
            revert S.EscrowRecoveryConsentInvalid();
        }
    }

    function _record(address account, bytes32 id, bytes32 nonce) private {
        S.State storage s = S.state();
        s.usedConsentNonces[account][nonce] = true;
        s.consents[id][account] = true;
        emit EscrowRecoveryConsentRecorded(1, id, account, nonce);
    }

    // Same EOA/EIP-2098/EIP-7702 and exact-word ERC-1271 rules as the original
    // revenue release authorization. Only its domain and governed host differ.
    function _valid(address account, bytes32 hash, bytes calldata signature)
        private
        view
        returns (bool)
    {
        uint256 size = account.code.length;
        bool delegated;
        if (size == 23) {
            uint256 prefix;
            assembly ("memory-safe") {
                let ptr := mload(0x40)
                extcodecopy(account, ptr, 0, 3)
                prefix := shr(232, mload(ptr))
            }
            delegated = prefix == 0xef0100;
        }
        if (size == 0 || delegated) {
            bytes32 r;
            bytes32 s;
            uint8 v;
            if (signature.length == 65) {
                assembly ("memory-safe") {
                    r := calldataload(signature.offset)
                    s := calldataload(add(signature.offset, 32))
                    v := byte(0, calldataload(add(signature.offset, 64)))
                }
            } else if (signature.length == 64) {
                bytes32 vs;
                assembly ("memory-safe") {
                    r := calldataload(signature.offset)
                    vs := calldataload(add(signature.offset, 32))
                }
                s = vs & bytes32(type(uint256).max >> 1);
                v = uint8(uint256(vs) >> 255) + 27;
            }
            if (
                uint256(s) <= HALF_ORDER && (v == 27 || v == 28)
                    && ecrecover(hash, v, r, s) == account
            ) return true;
            if (size == 0) return false;
        }
        bytes memory payload = abi.encodeWithSelector(MAGIC, hash, signature);
        uint256 cap = G(address(this)).gasParameter(ERC1271_GAS);
        uint256 available = gasleft();
        if (cap > available || available - cap < cap / 63 + (cap % 63 == 0 ? 0 : 1) + 20_000) {
            revert S.EscrowRecoveryConsentInvalid();
        }
        bool ok;
        uint256 result;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := staticcall(cap, account, add(payload, 32), mload(payload), ptr, 32)
            ok := and(ok, eq(returndatasize(), 32))
            result := mload(ptr)
        }
        return ok && result == uint256(uint32(MAGIC)) << 224;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamRevenueEscrow } from "./StreamRevenueEscrow.sol";
import { StreamEscrowRecoveryState as S } from "./StreamEscrowRecoveryState.sol";
import { StreamEscrowRecoveryGovernance as Governance } from "./StreamEscrowRecoveryGovernance.sol";
import { StreamEscrowRecoveryProof as Proof } from "./StreamEscrowRecoveryProof.sol";
import {
    StreamEscrowRecoveryTypes as R
} from "../../interfaces/stream/revenue/StreamEscrowRecoveryTypes.sol";
import {
    IStreamRevenueEscrowRecoveryManifest as M
} from "../../interfaces/stream/revenue/IStreamRevenueEscrowRecoveryManifest.sol";
import {
    IStreamRevenueEscrow as E
} from "../../interfaces/stream/revenue/IStreamRevenueEscrow.sol";
import { IStreamSplitFactory as F } from "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import { IStreamSplitWallet as W } from "../../interfaces/stream/revenue/IStreamSplitWallet.sol";
import {
    IStreamGasParameterHost as G
} from "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import { IERC20 } from "../../interfaces/standards/IERC20.sol";

/// @notice Fixed incident execution over the host's original Credit/totalOwed storage.
/// @dev Host holds the original nonReentrant guard. Every failure restores both ledgers,
///      consent facts, recovery status and any attempted callback/governance mutation.
library StreamEscrowRecoveryExecution {
    bytes32 private constant DEPOSIT_GAS = keccak256("6529STREAM_GGP_WALLET_DEPOSIT_GAS_LIMIT");
    event EscrowRecoveryExecuted(
        uint16 schemaVersion,
        bytes32 indexed recoveryId,
        bytes32 indexed revenueClass,
        bytes32 indexed profileId,
        address oldWallet,
        address successorWallet,
        uint256 movedAmount,
        bytes32 recoveryManifestContentHash,
        bytes32 reasonHash,
        string reasonURI
    );

    function execute(
        mapping(bytes32 => StreamRevenueEscrow.Credit) storage credits,
        mapping(address => uint256) storage totalOwed,
        S.Context memory c,
        bytes32 id
    ) public {
        M.ManifestDocument memory d = Governance.requireExecution(c, id);
        S.Recovery storage item = S.state().recoveries[id];
        R.EscrowRecoveryRecord storage p = item.record;
        StreamRevenueEscrow.Credit storage credit = credits[S.keyHash(d.creditKey)];
        uint256 amount = credit.amount;
        if (amount != p.expectedAmount || credit.factory != p.storedFactory) {
            revert S.InvalidEscrowRecoveryState(id);
        }
        uint256 cap = G(address(this)).gasParameter(DEPOSIT_GAS);
        address asset = p.creditKey.asset;
        uint256 beforeBalance =
            asset == address(0) ? address(this).balance : _balance(asset, address(this), cap);
        if (beforeBalance < totalOwed[asset]) {
            revert E.EscrowInsolvent(asset, beforeBalance, totalOwed[asset]);
        }
        credit.amount = 0;
        totalOwed[asset] -= amount;
        p.status = R.EscrowRecoveryStatus.EXECUTED;

        _deployAndVerify(d, cap);
        if (asset == address(0)) {
            uint256 walletBefore = d.successorWallet.balance;
            _native(d.successorWallet, amount, cap);
            // Forced ETH is surplus. A callback donation does not erase this owed debit
            // or invalidate otherwise authorized recovery.
            if (
                d.successorWallet.balance < walletBefore + amount
                    || address(this).balance < beforeBalance - amount
            ) {
                revert E.EscrowTransferInvariantBroken(asset);
            }
        } else {
            uint256 walletBefore = _balance(asset, d.successorWallet, cap);
            if (
                _callWord(asset, abi.encodeCall(IERC20.transfer, (d.successorWallet, amount)), cap)
                    != 1
            ) {
                revert E.EscrowTransferInvariantBroken(asset);
            }
            if (
                _balance(asset, address(this), cap) != beforeBalance - amount
                    || _balance(asset, d.successorWallet, cap) != walletBefore + amount
            ) {
                revert E.EscrowTransferInvariantBroken(asset);
            }
        }
        Proof.validateAfter(c, d);
        if (d.route == 1) {
            Governance.requireConsents(id, S.state().manifests[p.recoveryManifest.contentHash]);
        }
        if (p.status != R.EscrowRecoveryStatus.EXECUTED || Governance.identifier(p) != id) {
            revert S.InvalidEscrowRecoveryState(id);
        }
        uint256 remainingBalance =
            asset == address(0) ? address(this).balance : _balance(asset, address(this), cap);
        if (remainingBalance < totalOwed[asset]) {
            revert E.EscrowInsolvent(asset, remainingBalance, totalOwed[asset]);
        }
        emit EscrowRecoveryExecuted(
            1,
            id,
            p.creditKey.revenueClass,
            p.creditKey.profileId,
            p.creditKey.wallet,
            p.successorWallet,
            amount,
            p.recoveryManifest.contentHash,
            p.reasonHash,
            p.reasonURI
        );
    }

    function _deployAndVerify(M.ManifestDocument memory d, uint256 cap) private {
        if (d.successorWallet.code.length == 0) {
            uint256 available = gasleft();
            if (available <= 100_000 || cap > (available - 100_000) / 6) {
                revert E.InsufficientEscrowCallGas(cap, available, 100_000);
            }
            uint256 deployGas = gasleft() - (cap * 6 + 100_000);
            deployGas -= deployGas / 64;
            if (
                _callWord(
                        d.successorFactory,
                        abi.encodeCall(F.deployWallet, (d.successorProfileId)),
                        deployGas
                    ) != uint256(uint160(d.successorWallet))
            ) {
                revert E.EscrowWalletMismatch(d.successorProfileId, d.successorWallet);
            }
        }
        if (
            d.successorWallet.codehash != d.successorRuntimeCodeHash
                || Proof.word(
                        d.successorFactory,
                        abi.encodeCall(F.splitWalletExists, (d.successorProfileId)),
                        cap
                    ) != 1
                || Proof.word(d.successorWallet, abi.encodeCall(W.factory, ()), cap)
                    != uint256(uint160(d.successorFactory))
                || bytes32(Proof.word(d.successorWallet, abi.encodeCall(W.profileId, ()), cap))
                    != d.successorProfileId
        ) {
            revert E.EscrowWalletMismatch(d.successorProfileId, d.successorWallet);
        }
    }

    function _balance(address asset, address account, uint256 cap) private view returns (uint256) {
        return Proof.word(asset, abi.encodeCall(IERC20.balanceOf, (account)), cap);
    }

    function _callWord(address target, bytes memory data, uint256 cap)
        private
        returns (uint256 word)
    {
        _gas(cap);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            ok := call(cap, target, 0, add(data, 32), mload(data), ptr, 32)
            size := returndatasize()
            word := mload(ptr)
        }
        if (!ok || size != 32) _failed(target, bytes4(data), size);
    }

    function _native(address target, uint256 amount, uint256 cap) private {
        _gas(cap);
        if (cap < 2300) revert E.InsufficientEscrowCallGas(cap, gasleft(), 2300);
        uint256 forwarded = cap - 2300;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := call(forwarded, target, amount, 0, 0, 0, 0)
            size := returndatasize()
        }
        if (!ok) _failed(target, 0, size);
    }

    function _gas(uint256 cap) private view {
        uint256 available = gasleft();
        if (cap > available || available - cap < cap / 63 + (cap % 63 == 0 ? 0 : 1) + 30_000) {
            revert E.InsufficientEscrowCallGas(cap, available, 30_000);
        }
    }

    function _failed(address target, bytes4 selector, uint256 size) private pure {
        uint256 length = size > 256 ? 256 : size;
        bytes memory prefix = new bytes(length);
        assembly ("memory-safe") { returndatacopy(add(prefix, 32), 0, length) }
        revert E.EscrowExternalCallFailed(target, selector, size, prefix);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamEscrowRecoveryState as S } from "./StreamEscrowRecoveryState.sol";
import { StreamEscrowRecoveryProof as Proof } from "./StreamEscrowRecoveryProof.sol";
import {
    StreamEscrowRecoveryTypes as R
} from "../../interfaces/stream/revenue/StreamEscrowRecoveryTypes.sol";
import {
    IStreamRevenueEscrowRecoveryManifest as M
} from "../../interfaces/stream/revenue/IStreamRevenueEscrowRecoveryManifest.sol";
import {
    IStreamGovernedParameterAuthority as A
} from "../../interfaces/stream/parameters/IStreamGovernedParameterAuthority.sol";

/// @notice Original recovery ID and distinct FUNDS_RECOVERY / TERMINAL_FREEZE authorization.
/// @dev Governance has already enforced its own delay/class/catalog; this worker additionally
///      starts the notice floors at actual retained publication and actual escrow scheduling.
library StreamEscrowRecoveryGovernance {
    uint256 private constant FUNDS_DELAY = 14 days;
    uint256 private constant TERMINAL_DELAY = 72 hours;

    struct Action {
        uint256 executing;
        bytes32 id;
        uint256 actionClass;
        bytes32 scope;
        bytes32 oldState;
        bytes32 newState;
    }
    event EscrowRecoveryScheduled(
        uint16 schemaVersion,
        bytes32 indexed recoveryId,
        bytes32 indexed revenueClass,
        bytes32 indexed profileId,
        address wallet,
        address asset,
        address successorWallet,
        bytes32 successorProfileId,
        uint256 expectedAmount,
        bytes32 recoveryManifestContentHash,
        uint64 executeAfter,
        bytes32 reasonHash,
        string reasonURI
    );
    event EscrowRecoveryCancelled(
        uint16 schemaVersion,
        bytes32 indexed recoveryId,
        bytes32 indexed revenueClass,
        bytes32 indexed profileId,
        bytes32 reasonHash,
        string reasonURI
    );
    event EscrowRecoveryTerminalAuthorized(
        uint16 schemaVersion,
        bytes32 indexed recoveryId,
        bytes32 indexed actionId,
        bytes32 indexed manifestContentHash,
        uint64 authorizedAt
    );

    function identifier(R.EscrowRecoveryRecord memory p) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                R.RECOVERY_DOMAIN,
                block.chainid,
                address(this),
                p.creditKey.revenueClass,
                p.creditKey.profileId,
                p.creditKey.wallet,
                p.creditKey.asset,
                p.successorWallet,
                p.successorProfileId,
                p.successorRuntimeCodeHash,
                p.expectedAmount,
                p.recoveryManifest.contentHash,
                p.executeAfter,
                p.reasonHash
            )
        );
    }

    function transition(S.Context memory c, R.EscrowRecoveryRecord memory p)
        public
        view
        returns (bytes32 id, bytes32 scope, bytes32 oldState, bytes32 newState)
    {
        _reason(p.reasonHash, p.reasonURI);
        id = identifier(p);
        S.Recovery storage item = S.state().recoveries[id];
        if (item.record.status != R.EscrowRecoveryStatus.NONE) {
            revert S.InvalidEscrowRecoveryState(id);
        }
        S.Manifest storage manifest = S.state().manifests[p.recoveryManifest.contentHash];
        S.requireReference(p.recoveryManifest);
        if (manifest.publishedAt == 0) revert S.InvalidEscrowRecoveryManifest();
        M.ManifestDocument memory d = S.document(manifest);
        if (
            S.keyHash(d.creditKey) != S.keyHash(p.creditKey)
                || d.successorWallet != p.successorWallet
                || d.successorProfileId != p.successorProfileId
                || d.successorRuntimeCodeHash != p.successorRuntimeCodeHash
                || d.expectedAmount != p.expectedAmount || p.storedFactory != c.factory
                || p.status != R.EscrowRecoveryStatus.SCHEDULED
        ) revert S.InvalidEscrowRecoveryManifest();
        Proof.validate(c, d);
        uint256 earliest = uint256(manifest.publishedAt) + FUNDS_DELAY;
        if (d.route == 2) earliest += TERMINAL_DELAY;
        if (p.executeAfter < earliest) revert S.EscrowRecoveryDelayNotElapsed(earliest);
        if (d.route == 1) requireConsents(id, manifest);
        scope = keccak256(abi.encode(S.TRANSITION_DOMAIN, block.chainid, address(this), id));
        oldState = keccak256(abi.encode(scope, R.EscrowRecoveryStatus.NONE));
        newState = keccak256(abi.encode(scope, p, manifest.publishedAt));
    }

    function schedule(S.Context memory c, R.EscrowRecoveryRecord memory p)
        public
        returns (bytes32 id)
    {
        bytes32 scope;
        bytes32 oldState;
        bytes32 newState;
        (id, scope, oldState, newState) = transition(c, p);
        Action memory action = requireAction(c.authority, 4, scope, oldState, newState);
        S.Manifest storage manifest = S.state().manifests[p.recoveryManifest.contentHash];
        if (block.timestamp < uint256(manifest.publishedAt) + FUNDS_DELAY) {
            revert S.EscrowRecoveryDelayNotElapsed(uint256(manifest.publishedAt) + FUNDS_DELAY);
        }
        if (block.timestamp > type(uint64).max) revert S.InvalidEscrowRecoveryAction();
        S.Recovery storage item = S.state().recoveries[id];
        item.record = p;
        item.scheduledActionId = action.id;
        item.scheduledAt = uint64(block.timestamp);
        emit EscrowRecoveryScheduled(
            1,
            id,
            p.creditKey.revenueClass,
            p.creditKey.profileId,
            p.creditKey.wallet,
            p.creditKey.asset,
            p.successorWallet,
            p.successorProfileId,
            p.expectedAmount,
            p.recoveryManifest.contentHash,
            p.executeAfter,
            p.reasonHash,
            p.reasonURI
        );
    }

    function cancellation(bytes32 id, bytes32 reasonHash, string memory reasonURI)
        public
        view
        returns (bytes32 scope, bytes32 oldState, bytes32 newState)
    {
        _reason(reasonHash, reasonURI);
        S.Recovery storage item = S.state().recoveries[id];
        if (item.record.status != R.EscrowRecoveryStatus.SCHEDULED) {
            revert S.InvalidEscrowRecoveryState(id);
        }
        scope = keccak256(abi.encode(S.TRANSITION_DOMAIN, block.chainid, address(this), id));
        oldState = keccak256(
            abi.encode(scope, item.record, item.scheduledActionId, item.terminalActionId)
        );
        newState = keccak256(
            abi.encode(
                scope, R.EscrowRecoveryStatus.CANCELLED, reasonHash, keccak256(bytes(reasonURI))
            )
        );
    }

    function cancel(address authority, bytes32 id, bytes32 reasonHash, string memory reasonURI)
        public
    {
        (bytes32 scope, bytes32 oldState, bytes32 newState) =
            cancellation(id, reasonHash, reasonURI);
        Action memory action = requireAction(authority, 0, scope, oldState, newState);
        S.Recovery storage item = S.state().recoveries[id];
        item.record.status = R.EscrowRecoveryStatus.CANCELLED;
        item.cancelledActionId = action.id;
        emit EscrowRecoveryCancelled(
            1,
            id,
            item.record.creditKey.revenueClass,
            item.record.creditKey.profileId,
            reasonHash,
            reasonURI
        );
    }

    function terminalHashes(bytes32 id)
        public
        view
        returns (bytes32 scope, bytes32 oldState, bytes32 newState)
    {
        S.Recovery storage item = S.state().recoveries[id];
        if (item.record.status != R.EscrowRecoveryStatus.SCHEDULED || item.terminalActionId != 0) {
            revert S.InvalidEscrowRecoveryState(id);
        }
        S.Manifest storage manifest = S.state().manifests[item.record.recoveryManifest.contentHash];
        if (S.document(manifest).route != 2) revert S.InvalidEscrowRecoveryManifest();
        scope =
            keccak256(abi.encode(S.TRANSITION_DOMAIN, block.chainid, address(this), id, uint8(2)));
        oldState = keccak256(
            abi.encode(scope, item.record, item.scheduledActionId, item.scheduledAt, bytes32(0))
        );
        newState = keccak256(
            abi.encode(scope, item.record.recoveryManifest.contentHash, manifest.publishedAt, true)
        );
    }

    function terminal(S.Context memory c, bytes32 id) public {
        (bytes32 scope, bytes32 oldState, bytes32 newState) = terminalHashes(id);
        Action memory action = requireAction(c.authority, 2, scope, oldState, newState);
        S.Recovery storage item = S.state().recoveries[id];
        if (action.id == item.scheduledActionId) revert S.InvalidEscrowRecoveryAction();
        uint256 earliest = uint256(item.scheduledAt) + TERMINAL_DELAY;
        if (block.timestamp < earliest) revert S.EscrowRecoveryDelayNotElapsed(earliest);
        S.Manifest storage manifest = S.state().manifests[item.record.recoveryManifest.contentHash];
        Proof.validate(c, S.document(manifest));
        if (block.timestamp > type(uint64).max) revert S.InvalidEscrowRecoveryAction();
        item.terminalActionId = action.id;
        item.terminalAuthorizedAt = uint64(block.timestamp);
        emit EscrowRecoveryTerminalAuthorized(
            1, id, action.id, item.record.recoveryManifest.contentHash, uint64(block.timestamp)
        );
    }

    function requireExecution(S.Context memory c, bytes32 id)
        public
        view
        returns (M.ManifestDocument memory d)
    {
        S.Recovery storage item = S.state().recoveries[id];
        R.EscrowRecoveryRecord storage p = item.record;
        if (
            p.status != R.EscrowRecoveryStatus.SCHEDULED || item.scheduledActionId == 0
                || identifier(p) != id
        ) {
            revert S.InvalidEscrowRecoveryState(id);
        }
        if (block.timestamp < p.executeAfter) {
            revert S.EscrowRecoveryDelayNotElapsed(p.executeAfter);
        }
        S.Manifest storage manifest = S.state().manifests[p.recoveryManifest.contentHash];
        d = S.document(manifest);
        Proof.validate(c, d);
        if (d.route == 1) requireConsents(id, manifest);
        if (
            d.route == 2
                && (item.terminalActionId == 0
                    || item.terminalAuthorizedAt == 0
                    || item.terminalAuthorizedAt < uint256(item.scheduledAt) + TERMINAL_DELAY)
        ) revert S.InvalidEscrowRecoveryAction();
    }

    function requireConsents(bytes32 id, S.Manifest storage manifest) internal view {
        for (uint256 i; i < manifest.affectedAccounts.length; ++i) {
            address account = manifest.affectedAccounts[i];
            if (!S.state().consents[id][account]) {
                revert S.EscrowRecoveryConsentMissing(id, account);
            }
        }
    }

    function requireAction(
        address authority,
        uint8 cls,
        bytes32 scope,
        bytes32 oldState,
        bytes32 newState
    ) internal view returns (Action memory action) {
        if (msg.sender != authority || authority.codehash != S.state().origin.authorityCodeHash) {
            revert S.InvalidEscrowRecoveryAction();
        }
        action = abi.decode(
            Proof.read(authority, abi.encodeCall(A.currentAction, ()), 192, Proof.budget()),
            (Action)
        );
        if (
            action.executing != 1 || action.id == 0 || action.actionClass != cls
                || action.scope != scope || action.oldState != oldState
                || action.newState != newState
        ) {
            revert S.InvalidEscrowRecoveryAction();
        }
    }

    function _reason(bytes32 reasonHash, string memory reasonURI) private pure {
        if (reasonHash == 0 || bytes(reasonURI).length == 0 || bytes(reasonURI).length > 2048) {
            revert S.InvalidEscrowRecoveryManifest();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamEscrowRecoveryState as S } from "./StreamEscrowRecoveryState.sol";
import { StreamEscrowRecoveryProof as Proof } from "./StreamEscrowRecoveryProof.sol";
import {
    StreamEscrowRecoveryTypes as R
} from "../../interfaces/stream/revenue/StreamEscrowRecoveryTypes.sol";
import {
    IStreamRevenueEscrowRecoveryManifest as M
} from "../../interfaces/stream/revenue/IStreamRevenueEscrowRecoveryManifest.sol";

/// @notice Retains the exact canonical recovery document and computed affected recipients.
/// @dev Artist notice coverage and cited source events are explicit governance evidence, not
///      fabricated onchain receipt proofs. Actual notice delivery remains an operational duty.
library StreamEscrowRecoveryManifest {
    event EscrowRecoveryManifestPublished(
        uint16 schemaVersion,
        bytes32 indexed contentHash,
        address indexed publisher,
        bytes32 indexed creditKeyHash,
        bytes32 oldEntriesHash,
        bytes32 successorEntriesHash,
        bytes32 affectedAccountsHash,
        uint8 route,
        uint64 publishedAt,
        bytes canonicalDocument
    );

    function publish(
        S.Context memory c,
        M.ManifestDocument calldata supplied,
        R.EscrowRecoveryManifestRef calldata ref
    ) public returns (bytes32 contentHash) {
        M.ManifestDocument memory d = supplied;
        contentHash = keccak256(abi.encode(S.MANIFEST_DOMAIN, block.chainid, address(this), d));
        S.requireReference(ref);
        if (
            ref.contentHash != contentHash || block.timestamp == 0
                || block.timestamp > type(uint64).max
        ) revert S.InvalidEscrowRecoveryManifest();
        S.Manifest storage item = S.state().manifests[contentHash];
        // Publication authenticates the retained content, not a publisher-selected URI.
        // The later governed schedule binds its own complete, independently checked reference.
        if (item.publishedAt != 0) return contentHash;
        (bytes32 oldHash, bytes32 newHash, address[] memory affected) = Proof.validate(c, d);
        _notices(d, affected);
        bytes memory canonical = abi.encode(d);
        // This profile retains its actual bytes, including source-event and collection citations.
        item.canonicalDocument = canonical;
        item.oldEntriesHash = oldHash;
        item.successorEntriesHash = newHash;
        item.affectedAccounts = affected;
        item.publishedAt = uint64(block.timestamp);
        emit EscrowRecoveryManifestPublished(
            1,
            contentHash,
            msg.sender,
            S.keyHash(d.creditKey),
            oldHash,
            newHash,
            keccak256(abi.encode(affected)),
            d.route,
            item.publishedAt,
            canonical
        );
    }

    function encoded(bytes32 contentHash) public view returns (bytes memory, uint64) {
        S.Manifest storage item = S.state().manifests[contentHash];
        return (item.canonicalDocument, item.publishedAt);
    }

    function count(bytes32 contentHash) public view returns (uint256) {
        return S.state().manifests[contentHash].affectedAccounts.length;
    }

    function accountAt(bytes32 contentHash, uint256 index) public view returns (address) {
        address[] storage affected = S.state().manifests[contentHash].affectedAccounts;
        if (index >= affected.length) revert S.InvalidEscrowRecoveryManifest();
        return affected[index];
    }

    function _notices(M.ManifestDocument memory d, address[] memory affected) private view {
        if (d.route != 2) {
            if (
                d.recipientNotices.length != 0 || d.collectionNotices.length != 0
                    || d.sourceCredits.length != 0 || d.coverageStatementHash != 0
            ) revert S.InvalidEscrowRecoveryManifest();
            return;
        }
        if (
            d.coverageStatementHash == 0 || d.recipientNotices.length != affected.length
                || d.collectionNotices.length == 0 || d.sourceCredits.length == 0
        ) revert S.InvalidEscrowRecoveryManifest();
        for (uint256 i; i < affected.length; ++i) {
            M.RecipientNotice memory n = d.recipientNotices[i];
            if (n.account != affected[i]) revert S.InvalidEscrowRecoveryManifest();
            _notice(n.evidenceHash, n.noticedAt);
        }
        bool[] memory represented = new bool[](d.collectionNotices.length);
        for (uint256 i; i < d.collectionNotices.length; ++i) {
            M.CollectionNotice memory n = d.collectionNotices[i];
            if (n.core == address(0) || n.collectionId == 0) {
                revert S.InvalidEscrowRecoveryManifest();
            }
            if (i != 0) {
                M.CollectionNotice memory prior = d.collectionNotices[i - 1];
                if (
                    uint160(prior.core) > uint160(n.core)
                        || (prior.core == n.core && prior.collectionId >= n.collectionId)
                ) {
                    revert S.InvalidEscrowRecoveryManifest();
                }
            }
            if (n.artistBound) {
                if (n.artistAuthority == address(0)) revert S.InvalidEscrowRecoveryManifest();
                _notice(n.evidenceHash, n.noticedAt);
            } else if (n.artistAuthority != address(0) || n.evidenceHash != 0 || n.noticedAt != 0) {
                revert S.InvalidEscrowRecoveryManifest();
            }
        }
        for (uint256 i; i < d.sourceCredits.length; ++i) {
            M.SourceCredit memory source = d.sourceCredits[i];
            if (
                source.producer == address(0) || source.transactionHash == 0
                    || source.blockHash == 0 || source.blockNumber == 0
                    || source.blockNumber >= block.number
                    || source.collectionIndex >= represented.length
            ) revert S.InvalidEscrowRecoveryManifest();
            if (i != 0) {
                M.SourceCredit memory prior = d.sourceCredits[i - 1];
                if (
                    uint256(prior.transactionHash) > uint256(source.transactionHash)
                        || (prior.transactionHash == source.transactionHash
                            && prior.logIndex >= source.logIndex)
                ) {
                    revert S.InvalidEscrowRecoveryManifest();
                }
            }
            represented[source.collectionIndex] = true;
        }
        for (uint256 i; i < represented.length; ++i) {
            if (!represented[i]) revert S.InvalidEscrowRecoveryManifest();
        }
    }

    function _notice(bytes32 evidence, uint64 at) private view {
        if (evidence == 0 || at == 0 || at > block.timestamp) {
            revert S.InvalidEscrowRecoveryManifest();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamEscrowRecoveryState as S } from "./StreamEscrowRecoveryState.sol";
import { StreamRevenueRuntimeBinding as B } from "./StreamRevenueRuntimeBinding.sol";
import {
    IStreamRevenueEscrow as E
} from "../../interfaces/stream/revenue/IStreamRevenueEscrow.sol";
import {
    IStreamRevenueEscrowRecoveryManifest as M
} from "../../interfaces/stream/revenue/IStreamRevenueEscrowRecoveryManifest.sol";
import { IStreamSplitFactory as F } from "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import { IStreamSplitWallet as W } from "../../interfaces/stream/revenue/IStreamSplitWallet.sol";
import {
    IStreamRevenueRuntimeRegistry as L
} from "../../interfaces/stream/revenue/IStreamRevenueRuntimeRegistry.sol";
import {
    IStreamGasParameterHost as G
} from "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";

/// @notice Exact immutable terms, captured credit and current incident/successor proof.
/// @dev Canonical original profile preimages remain checkable if the old factory is unavailable.
library StreamEscrowRecoveryProof {
    bytes32 private constant POLICY_GAS = keccak256("6529STREAM_GGP_ASSET_POLICY_GAS_LIMIT");

    function validate(S.Context memory c, M.ManifestDocument memory d)
        public
        view
        returns (bytes32 oldHash, bytes32 newHash, address[] memory affected)
    {
        return _validate(c, d, d.expectedAmount);
    }

    function validateAfter(S.Context memory c, M.ManifestDocument memory d) public view {
        _validate(c, d, 0);
    }

    function _validate(S.Context memory c, M.ManifestDocument memory d, uint256 expectedOwed)
        private
        view
        returns (bytes32 oldHash, bytes32 newHash, address[] memory affected)
    {
        if (c.authority.codehash != S.state().origin.authorityCodeHash) {
            revert S.InvalidEscrowRecoveryAction();
        }
        if (
            d.creditKey.revenueClass == 0 || d.creditKey.profileId == 0 || d.expectedAmount == 0
                || d.successorWallet == address(0) || d.successorWallet == d.creditKey.wallet
                || d.successorProfileId == 0 || d.successorRuntimeCodeHash == 0
                || d.incidentEvidenceHash == 0 || d.route > 2
        ) revert S.InvalidEscrowRecoveryManifest();
        uint256 cap = budget();
        if (
            word(
                    address(this),
                    abi.encodeCall(
                        E.escrowOwed,
                        (
                            d.creditKey.revenueClass,
                            d.creditKey.profileId,
                            d.creditKey.wallet,
                            d.creditKey.asset
                        )
                    ),
                    cap
                ) != expectedOwed
        ) revert S.InvalidEscrowRecoveryManifest();
        bytes memory identity = read(
            address(this),
            abi.encodeCall(
                E.escrowCreditIdentity,
                (
                    d.creditKey.revenueClass,
                    d.creditKey.profileId,
                    d.creditKey.wallet,
                    d.creditKey.asset
                )
            ),
            96,
            cap
        );
        (address factory, bytes32 factoryHash, bytes32 runtime) =
            abi.decode(identity, (address, bytes32, bytes32));
        if (factory != c.factory || factoryHash != c.factoryCodeHash || runtime != c.walletCodeHash)
        {
            revert S.InvalidEscrowRecoveryManifest();
        }
        oldHash = canonicalEntriesHash(d.oldEntries);
        newHash = canonicalEntriesHash(d.successorEntries);
        _original(c, d, oldHash, cap);
        _incident(c, d, cap);
        _successor(c, d, newHash, cap);
        affected = affectedAccounts(d.oldEntries, d.successorEntries);
        if ((d.route == 0) != (oldHash == newHash)) revert S.InvalidEscrowRecoveryManifest();
    }

    function canonicalEntriesHash(W.SplitEntry[] memory entries) public pure returns (bytes32) {
        if (entries.length == 0 || entries.length > 64) revert S.InvalidEscrowRecoveryManifest();
        uint256 total;
        for (uint256 i; i < entries.length; ++i) {
            W.SplitEntry memory e = entries[i];
            if (e.account == address(0) || e.sharePpm == 0 || e.sharePpm > 1_000_000) {
                revert S.InvalidEscrowRecoveryManifest();
            }
            if (i != 0) {
                W.SplitEntry memory p = entries[i - 1];
                if (
                    uint160(p.account) > uint160(e.account)
                        || (p.account == e.account && uint256(p.labelId) >= uint256(e.labelId))
                ) {
                    revert S.InvalidEscrowRecoveryManifest();
                }
            }
            total += e.sharePpm;
        }
        if (total != 1_000_000) revert S.InvalidEscrowRecoveryManifest();
        return keccak256(abi.encode(entries));
    }

    function affectedAccounts(W.SplitEntry[] memory oldEntries, W.SplitEntry[] memory nextEntries)
        public
        pure
        returns (address[] memory accounts)
    {
        accounts = new address[](oldEntries.length);
        uint256 count;
        uint256 i;
        while (i < oldEntries.length) {
            address account = oldEntries[i].account;
            uint256 oldShare;
            while (i < oldEntries.length && oldEntries[i].account == account) {
                oldShare += oldEntries[i++].sharePpm;
            }
            uint256 nextShare;
            for (uint256 j; j < nextEntries.length; ++j) {
                if (nextEntries[j].account == account) nextShare += nextEntries[j].sharePpm;
            }
            if (nextShare < oldShare) accounts[count++] = account;
        }
        assembly ("memory-safe") { mstore(accounts, count) }
    }

    function _original(
        S.Context memory c,
        M.ManifestDocument memory d,
        bytes32 entriesHash,
        uint256 cap
    ) private view {
        if (
            c.originalProfileDomain == 0 || c.originalInitCodeHash == 0
                || c.originalSchemaVersion == 0 || c.originalWalletVersion == 0
                || d.creditKey.profileId
                    != keccak256(
                        abi.encode(
                            c.originalProfileDomain,
                            uint256(block.chainid),
                            c.factory,
                            c.originalSchemaVersion,
                            c.originalWalletVersion,
                            c.originalInitCodeHash,
                            c.walletCodeHash,
                            c.assetRegistry,
                            entriesHash,
                            d.oldMetadataURIHash
                        )
                    )
        ) revert S.InvalidEscrowRecoveryManifest();
        // Captured factory code authenticated the original profile at credit creation. When
        // still available, require its stored hash too; a code-loss incident cannot rewrite
        // the immutable original profile-ID preimage supplied above.
        if (c.factory.codehash == c.factoryCodeHash) {
            if (
                bytes32(
                        word(
                            c.factory,
                            abi.encodeCall(F.profileEntriesHash, (d.creditKey.profileId)),
                            cap
                        )
                    ) != entriesHash
            ) {
                revert S.InvalidEscrowRecoveryManifest();
            }
        }
    }

    function _incident(S.Context memory c, M.ManifestDocument memory d, uint256 cap) private view {
        if (c.runtimeRegistry.codehash != c.runtimeRegistryCodeHash) {
            revert S.InvalidEscrowRecoveryManifest();
        }
        L.FactoryRecord memory f = abi.decode(
            read(c.runtimeRegistry, abi.encodeCall(L.factoryRecord, (c.factory)), 192, cap),
            (L.FactoryRecord)
        );
        L.RuntimeRecord memory r = abi.decode(
            read(c.runtimeRegistry, abi.encodeCall(L.runtimeRecord, (c.walletCodeHash)), 128, cap),
            (L.RuntimeRecord)
        );
        if (
            f.codeHash != c.factoryCodeHash || f.runtimeCodeHash != c.walletCodeHash
                || f.revision == 0 || r.revision == 0
        ) revert S.InvalidEscrowRecoveryManifest();
        bool poisoned =
            d.creditKey.wallet.code.length != 0 && d.creditKey.wallet.codehash != c.walletCodeHash;
        if (!poisoned && f.status != 3 && r.status != 3) revert S.EscrowRecoveryIncidentRequired();
        if (poisoned && d.successorProfileId == d.creditKey.profileId) {
            revert S.InvalidEscrowRecoveryManifest();
        }
        if (r.status == 3 && d.incidentEvidenceHash != r.incidentManifestHash) {
            revert S.InvalidEscrowRecoveryManifest();
        }
        if (r.status != 3 && f.status == 3 && d.incidentEvidenceHash != f.incidentManifestHash) {
            revert S.InvalidEscrowRecoveryManifest();
        }
    }

    function _successor(
        S.Context memory c,
        M.ManifestDocument memory d,
        bytes32 entriesHash,
        uint256 cap
    ) private view {
        B.requireState(d.successorFactory, c.runtimeRegistry, c.runtimeRegistryCodeHash, true);
        (address registry, bytes32 codeHash) = B.factoryBinding(d.successorFactory);
        if (registry != c.runtimeRegistry || codeHash != c.runtimeRegistryCodeHash) {
            revert S.InvalidEscrowRecoveryManifest();
        }
        if (
            word(d.successorFactory, abi.encodeCall(F.profileExists, (d.successorProfileId)), cap)
                    != 1
                || word(
                        d.successorFactory, abi.encodeCall(F.walletFor, (d.successorProfileId)), cap
                    ) != uint256(uint160(d.successorWallet))
                || bytes32(
                        word(
                            d.successorFactory,
                            abi.encodeCall(F.profileEntriesHash, (d.successorProfileId)),
                            cap
                        )
                    ) != entriesHash
                || bytes32(
                        word(
                            d.successorFactory,
                            abi.encodeCall(F.splitWalletRuntimeCodeHash, ()),
                            cap
                        )
                    ) != d.successorRuntimeCodeHash
        ) revert S.InvalidEscrowRecoveryManifest();
        if (d.successorWallet.code.length != 0) {
            if (
                d.successorWallet.codehash != d.successorRuntimeCodeHash
                    || word(
                            d.successorFactory,
                            abi.encodeCall(F.splitWalletExists, (d.successorProfileId)),
                            cap
                        ) != 1
                    || word(d.successorWallet, abi.encodeCall(W.factory, ()), cap)
                        != uint256(uint160(d.successorFactory))
                    || bytes32(word(d.successorWallet, abi.encodeCall(W.profileId, ()), cap))
                        != d.successorProfileId
            ) revert S.InvalidEscrowRecoveryManifest();
        }
    }

    function budget() public view returns (uint256) {
        return G(address(this)).gasParameter(POLICY_GAS);
    }

    function word(address target, bytes memory data, uint256 cap) public view returns (uint256) {
        return abi.decode(read(target, data, 32, cap), (uint256));
    }

    function read(address target, bytes memory data, uint256 length, uint256 cap)
        public
        view
        returns (bytes memory output)
    {
        uint256 available = gasleft();
        if (cap == 0 || cap > available || available - cap < cap / 63 + 1 + 30_000) {
            revert S.EscrowRecoveryReadFailed(target, bytes4(data));
        }
        output = new bytes(length);
        bool ok;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(data, 32), mload(data), add(output, 32), length)
            ok := and(ok, eq(returndatasize(), length))
        }
        if (!ok) revert S.EscrowRecoveryReadFailed(target, bytes4(data));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamEscrowRecoveryTypes as R
} from "../../interfaces/stream/revenue/StreamEscrowRecoveryTypes.sol";
import {
    IStreamRevenueEscrowRecoveryManifest as M
} from "../../interfaces/stream/revenue/IStreamRevenueEscrowRecoveryManifest.sol";

/// @notice Additive recovery records only; original escrow credits remain the sole owed ledger.
library StreamEscrowRecoveryState {
    bytes32 internal constant SLOT = keccak256("6529STREAM_ESCROW_RECOVERY_STORAGE_V1");
    bytes32 internal constant MANIFEST_DOMAIN = keccak256("6529STREAM_ESCROW_RECOVERY_MANIFEST_V1");
    bytes32 internal constant MANIFEST_SCHEMA = keccak256("STREAM_ESCROW_RECOVERY_MANIFEST_V1");
    bytes32 internal constant CANONICALIZATION = keccak256("6529STREAM_ESCROW_RECOVERY_ABI_V1");
    bytes32 internal constant TRANSITION_DOMAIN =
        keccak256("6529STREAM_ESCROW_RECOVERY_TRANSITION_V1");

    struct Context {
        address factory;
        address authority;
        address assetRegistry;
        bytes32 factoryCodeHash;
        bytes32 walletCodeHash;
        bytes32 originalInitCodeHash;
        bytes32 originalProfileDomain;
        uint16 originalSchemaVersion;
        uint16 originalWalletVersion;
        address runtimeRegistry;
        bytes32 runtimeRegistryCodeHash;
    }

    struct Origin {
        bytes32 authorityCodeHash;
        bytes32 profileDomain;
        bytes32 initCodeHash;
        uint16 schemaVersion;
        uint16 walletVersion;
    }

    struct Manifest {
        bytes canonicalDocument;
        bytes32 oldEntriesHash;
        bytes32 successorEntriesHash;
        address[] affectedAccounts;
        uint64 publishedAt;
    }

    struct Recovery {
        R.EscrowRecoveryRecord record;
        bytes32 scheduledActionId;
        bytes32 cancelledActionId;
        bytes32 terminalActionId;
        uint64 scheduledAt;
        uint64 terminalAuthorizedAt;
    }

    struct State {
        Origin origin;
        mapping(bytes32 => Manifest) manifests;
        mapping(bytes32 => Recovery) recoveries;
        mapping(address => mapping(bytes32 => bool)) usedConsentNonces;
        mapping(bytes32 => mapping(address => bool)) consents;
    }

    error InvalidEscrowRecoveryManifest();
    error InvalidEscrowRecoveryState(bytes32 recoveryId);
    error InvalidEscrowRecoveryAction();
    error EscrowRecoveryConsentMissing(bytes32 recoveryId, address account);
    error EscrowRecoveryConsentInvalid();
    error EscrowRecoveryReadFailed(address target, bytes4 selector);
    error EscrowRecoveryDelayNotElapsed(uint256 earliest);
    error EscrowRecoveryIncidentRequired();

    function state() internal pure returns (State storage s) {
        bytes32 slot = SLOT;
        assembly ("memory-safe") { s.slot := slot }
    }

    function keyHash(R.EscrowCreditKey memory key) internal pure returns (bytes32) {
        return keccak256(abi.encode(key.revenueClass, key.profileId, key.wallet, key.asset));
    }

    function requireReference(R.EscrowRecoveryManifestRef memory ref) internal pure {
        if (
            ref.contentHash == 0 || ref.schemaId != MANIFEST_SCHEMA
                || ref.canonicalizationHash != CANONICALIZATION || bytes(ref.uri).length == 0
                || bytes(ref.uri).length > 2048 || ref.uriHash != keccak256(bytes(ref.uri))
        ) revert InvalidEscrowRecoveryManifest();
    }

    function document(Manifest storage item) internal view returns (M.ManifestDocument memory) {
        return abi.decode(item.canonicalDocument, (M.ManifestDocument));
    }
}

