// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamPreparedNativeSettlementValidation.sol";
import "../../interfaces/stream/auctions/IStreamNativeCustodyAuction.sol";
import "../../interfaces/stream/revenue/IStreamNativeCustodyPrimarySettlement.sol";

/// @notice Governance explicitly trusts one immutable house implementation for custody history.
/// @dev This pin is not an independent arbitrary-house mint-origin receipt.
library StreamNativeCustodyPrimaryAdmission {
    struct Context {
        address core;
        bytes32 coreHash;
        address registry;
        bytes32 registryHash;
        address authority;
        bytes32 authorityHash;
    }

    event CanonicalCustodyHouseBound(
        address indexed house,
        bytes32 indexed codeHash,
        bytes32 indexed actionId,
        StreamNativeCustodySettlementTypes.CanonicalHouse binding
    );

    function validateAuthority(address authority) public view returns (bytes32) {
        if (
            !StreamSettlementAdmission.isContract(authority)
                || uint256(
                        StreamPreparedNativeSettlementValidation.word(
                            authority, "isStreamGovernedParameterAuthority()"
                        )
                    ) != 1
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes memory raw = StreamPreparedNativeSettlementValidation.read(
            authority, abi.encodeWithSignature("currentAction()"), 192
        );
        (bool executing, bytes32 id, uint8 kind, bytes32 scope, bytes32 old_, bytes32 next) =
            abi.decode(raw, (bool, bytes32, uint8, bytes32, bytes32, bytes32));
        if (keccak256(raw) != keccak256(abi.encode(executing, id, kind, scope, old_, next))) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        return authority.codehash;
    }

    function transition(
        Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory prior,
        address house
    ) public view returns (bytes32 scope, bytes32 oldState, bytes32 newState) {
        StreamNativeCustodySettlementTypes.CanonicalHouse memory next = candidate(x, house);
        scope = keccak256(
            abi.encode(
                keccak256("6529STREAM_CANONICAL_CUSTODY_HOUSE_SCOPE_V1"),
                block.chainid,
                address(this),
                x.core,
                x.registry
            )
        );
        oldState = stateHash(scope, prior);
        newState = stateHash(scope, next);
    }

    function bind(
        Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse storage saved,
        address house
    ) public {
        if (saved.house != address(0)) {
            revert IStreamNativeCustodyPrimarySettlement.NativeCustodyHouseAlreadyBound();
        }
        if (msg.sender != x.authority || x.authority.codehash != x.authorityHash) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        StreamNativeCustodySettlementTypes.CanonicalHouse memory next = candidate(x, house);
        (bytes32 scope, bytes32 oldState, bytes32 newState) = transition(x, saved, house);
        bytes memory raw = StreamPreparedNativeSettlementValidation.read(
            x.authority, abi.encodeWithSignature("currentAction()"), 192
        );
        (bool executing, bytes32 id, uint8 kind, bytes32 actualScope, bytes32 old_, bytes32 next_) =
            abi.decode(raw, (bool, bytes32, uint8, bytes32, bytes32, bytes32));
        if (
            !executing || id == 0 || kind != 1 || actualScope != scope || old_ != oldState
                || next_ != newState
                || keccak256(raw)
                    != keccak256(abi.encode(executing, id, kind, actualScope, old_, next_))
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        saved.house = next.house;
        saved.codeHash = next.codeHash;
        saved.boundAt = next.boundAt;
        saved.revision = next.revision;
        saved.recorderBoundAt = next.recorderBoundAt;
        saved.recorderRevision = next.recorderRevision;
        emit CanonicalCustodyHouseBound(house, next.codeHash, id, next);
    }

    function requireCurrent(
        Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        address house
    ) public view {
        if (pin.house == address(0) || house != pin.house || house.codehash != pin.codeHash) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bindings(x, house);
        StreamPreparedNativeSettlementAdmission.requireModule(x.registry, house);
        StreamPreparedNativeSettlementAdmission.requireRecorder(
            x.registry, address(this), pin.recorderBoundAt, pin.recorderRevision
        );
    }

    function candidate(Context memory x, address house)
        private
        view
        returns (StreamNativeCustodySettlementTypes.CanonicalHouse memory next)
    {
        bindings(x, house);
        StreamNativeSettlementTypes.SaleLifecycleBinding memory life =
            StreamPreparedNativeSettlementAdmission.capture(x.registry, house);
        (uint64 at_, uint64 rev) =
            StreamPreparedNativeSettlementAdmission.captureRecorder(x.registry, address(this));
        next = StreamNativeCustodySettlementTypes.CanonicalHouse(
            house, house.codehash, life.saleCreatedAt, life.saleAdapterRegistryRevision, at_, rev
        );
    }

    function bindings(Context memory x, address house) private view {
        StreamSettlementAdmission.requireRegistry(x.core, x.coreHash, x.registry, x.registryHash);
        if (
            !StreamSettlementAdmission.isContract(house)
                || StreamPreparedNativeSettlementValidation.addressWord(house, "core()") != x.core
                || StreamPreparedNativeSettlementValidation.word(house, "coreCodeHash()")
                    != x.coreHash
                || StreamPreparedNativeSettlementValidation.addressWord(house, "moduleRegistry()")
                    != x.registry
                || StreamPreparedNativeSettlementValidation.word(house, "moduleRegistryCodeHash()")
                    != x.registryHash
                || StreamPreparedNativeSettlementValidation.addressWord(
                        house, "primarySaleSettlement()"
                    ) != address(this)
                || StreamPreparedNativeSettlementValidation.word(house, "settlementCodeHash()")
                    != address(this).codehash
                || StreamPreparedNativeSettlementValidation.addressWord(
                        house, "governanceAuthority()"
                    ) != x.authority
                || StreamPreparedNativeSettlementValidation.addressWord(house, "revenueResolver()")
                    != StreamPreparedNativeSettlementValidation.addressWord(
                        address(this), "revenueResolver()"
                    )
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes memory raw = StreamPreparedNativeSettlementValidation.read(
            house,
            abi.encodeWithSelector(
                bytes4(0x01ffc9a7), type(IStreamNativeCustodyAuction).interfaceId
            ),
            32
        );
        if (abi.decode(raw, (uint256)) != 1) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
    }

    function stateHash(bytes32 scope, StreamNativeCustodySettlementTypes.CanonicalHouse memory pin)
        private
        view
        returns (bytes32)
    {
        // Timestamps are authenticated observations at execution, not unknowable scheduling inputs.
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_CANONICAL_CUSTODY_HOUSE_STATE_V1"),
                block.chainid,
                address(this),
                scope,
                pin.house,
                pin.codeHash,
                pin.revision,
                pin.recorderRevision
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamNativeCustodyPrimaryValidation.sol";
import "./StreamTokenProfileCustodyHash.sol";
import "./StreamCustodyRightsHash.sol";
import "./StreamPlatformCustodyHash.sol";
import "./StreamNativePrimaryExecution.sol";
import "./StreamPrimarySettlementEmission.sol";
import "./StreamPrimarySettlementHash.sol";

/// @notice Official payment before custody delivery, with no mint or ledger operation.
library StreamNativeCustodyPrimaryRecording {
    struct Context {
        StreamNativeCustodyPrimaryAdmission.Context admission;
        bytes32 resolverHash;
        StreamNativePrimaryExecution.Context funding;
    }
    event NativeCustodyRevenueRecorded(
        bytes32 indexed settlementKey,
        bytes32 indexed saleKey,
        bytes32 indexed factsHash,
        StreamNativeCustodySettlementTypes.Facts facts,
        StreamPrimarySettlementTypes.PrimarySettlementResult result
    );

    function execute(
        Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        mapping(bytes32 => bool) storage saleConsumed,
        mapping(bytes32 => bool) storage consumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage results,
        mapping(bytes32 => bytes32) storage factsHashes,
        mapping(bytes32 => uint256) storage official,
        mapping(address => uint256) storage total,
        bytes32 id
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory r) {
        requireContext(x);
        StreamNativeCustodySettlementTypes.Facts memory f =
            StreamNativeCustodyPrimaryValidation.read(x.admission, pin, id);
        if (
            IERC165(msg.sender)
                    .supportsInterface(type(IStreamPlatformNativeRightsAuction).interfaceId)
                && IStreamPlatformNativeRightsAuction(msg.sender)
                        .platformAuctionDeclaration(f.auction.saleId) != 0
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        StreamTokenProfileCustodyHash.requireLegacy(msg.sender, id);
        StreamCustodyRightsHash.requireLegacy(msg.sender, id);
        if (
            msg.value != f.auction.winner.amount
                || f.auction.winner.payer == address(x.funding.escrow)
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected
        ) = StreamNativeCustodyPrimaryValidation.derive(
            x.funding.rights, f, msg.sender, address(this)
        );
        if (c.sale.payer == selected.wallet) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 saleKey = StreamPreparedNativeSettlementHash.saleKey(
            address(this), msg.sender, f.auction.saleId, f.auction.saleNonce
        );
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            address(this), msg.sender, c.executionBinding.executionId
        );
        if (saleConsumed[saleKey] || consumed[key]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(key);
        }
        saleConsumed[saleKey] = true;
        consumed[key] = true;
        bool escrowed = StreamNativePrimaryExecution.fund(
            x.funding, c.sale.collectionId, c.sale.amount, selected
        );
        requireContext(x);
        StreamNativeCustodySettlementTypes.Facts memory after_ =
            StreamNativeCustodyPrimaryValidation.read(x.admission, pin, id);
        (StreamPrimarySettlementTypes.ERC20SettlementCandidate memory afterCandidate,) = StreamNativeCustodyPrimaryValidation.derive(
            x.funding.rights, after_, msg.sender, address(this)
        );
        if (
            keccak256(abi.encode(f)) != keccak256(abi.encode(after_))
                || keccak256(abi.encode(c)) != keccak256(abi.encode(afterCandidate))
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 factsHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_NATIVE_CUSTODY_TRANSFER_FACTS_V1"),
                block.chainid,
                address(this),
                msg.sender,
                f
            )
        );
        r = StreamPrimarySettlementTypes.PrimarySettlementResult(
            keccak256(
                abi.encode(
                    keccak256("6529STREAM_NATIVE_CUSTODY_TRANSFER_CANDIDATE_V1"),
                    block.chainid,
                    address(this),
                    msg.sender,
                    f,
                    c
                )
            ),
            key,
            selected.profileId,
            selected.wallet,
            address(0),
            c.sale.amount,
            c.executor,
            c.executionBinding.executionId,
            escrowed,
            0,
            0,
            0
        );
        results[key] = r;
        factsHashes[key] = factsHash;
        official[
            keccak256(
                abi.encode(
                    keccak256("6529STREAM_OFFICIAL_PRIMARY_SETTLED_V1"),
                    keccak256("PRIMARY_SALE"),
                    selected.profileId,
                    selected.wallet,
                    address(0)
                )
            )
        ] += r.amount;
        total[address(0)] += r.amount;
        StreamPrimarySettlementEmission.emitSettlement(
            c, r, address(0), f.auction.config.expectedPrimaryPolicyHash
        );
        emit NativeCustodyRevenueRecorded(key, saleKey, factsHash, f, r);
    }

    function requireContext(Context memory x) private view {
        StreamSettlementAdmission.requireRegistry(
            x.admission.core, x.admission.coreHash, x.admission.registry, x.admission.registryHash
        );
        if (
            address(x.funding.rights.resolver).codehash != x.resolverHash
                || address(x.funding.rights.factory).codehash != x.funding.factoryHash
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
    }
}

