pragma solidity ^0.8.19;

import "./StreamNativePrimaryExecution.sol";
import "./StreamNativeSettlementAdmission.sol";
import "./StreamPrimarySettlementValidation.sol";
import "./StreamPrimarySettlementEmission.sol";
import "./StreamPrimarySettlementHash.sol";
import "./StreamDeferredNativeSettlementValidation.sol";

/// @notice Existing native and deferred recorder execution behind a fixed compiler link.
/// @dev The original recorder owns the nonReentrant guard and supplies its exact immutable
/// context and storage references. Delegatecall preserves recorder identity, caller, value,
/// event emitter and all-or-nothing payment/replay/result effects; no new authority is added.
library StreamNativePrimaryRecording {
    bytes32 private constant _CLASS = keccak256("PRIMARY_SALE");
    bytes32 private constant _TOTAL = keccak256("6529STREAM_OFFICIAL_PRIMARY_SETTLED_V1");
    error InvalidSettlementContext(address target);

    struct Context {
        address core;
        bytes32 coreHash;
        address registry;
        bytes32 registryHash;
        bytes32 resolverHash;
        StreamNativePrimaryExecution.Context funding;
    }

    function settleNative(
        Context memory x,
        mapping(bytes32 => bool) storage settlementConsumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage _results,
        mapping(bytes32 => uint256) storage _officialSettled,
        mapping(address => uint256) storage totalOfficialSettled,
        StreamNativeSettlementTypes.NativeSettlementCandidate calldata candidate
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory result) {
        StreamNativeSettlementTypes.NativeSettlementCandidate memory n = candidate;
        _validateNative(x, n);
        return _settleNative(
            x, settlementConsumed, _results, _officialSettled, totalOfficialSettled, n, false, 0
        );
    }

    function settlePublicNative(
        Context memory x,
        mapping(bytes32 => bool) storage settlementConsumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage _results,
        mapping(bytes32 => uint256) storage _officialSettled,
        mapping(address => uint256) storage totalOfficialSettled,
        StreamNativeSettlementTypes.NativeSettlementCandidate calldata candidate
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory result) {
        StreamNativeSettlementTypes.NativeSettlementCandidate memory n = candidate;
        StreamPrimarySettlementValidation.Bindings memory bindings = _bindings(x);
        StreamPrimarySettlementValidation.nativePublicFields(bindings, n);
        _requireNativeContext(x);
        StreamNativeSettlementAdmission.requireAdmission(x.registry, n);
        bytes32 recordHash = StreamPrimarySettlementValidation.nativePublicBindings(bindings, n);
        return _settleNative(
            x,
            settlementConsumed,
            _results,
            _officialSettled,
            totalOfficialSettled,
            n,
            true,
            recordHash
        );
    }

    function _settleNative(
        Context memory x,
        mapping(bytes32 => bool) storage settlementConsumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage _results,
        mapping(bytes32 => uint256) storage _officialSettled,
        mapping(address => uint256) storage totalOfficialSettled,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory n,
        bool publicSale,
        bytes32 publicRecordHash
    ) private returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory result) {
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            address(this), n.saleAdapter, n.executionBinding.executionId
        );
        if (settlementConsumed[key]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(key);
        }
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c =
            StreamNativeSettlementHash.accountingContext(n);
        StreamSaleTemplate.Selection memory selected = _resolve(x, c);
        settlementConsumed[key] = true;
        bool escrowed = StreamNativePrimaryExecution.fund(
            x.funding, c.sale.collectionId, c.sale.amount, selected
        );
        _requireNativeContext(x);
        StreamNativeSettlementAdmission.requireAdmission(x.registry, n);
        if (
            publicSale
                && StreamPrimarySettlementValidation.nativePublicBindings(_bindings(x), n)
                    != publicRecordHash
        ) revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        _requireCurrent(x, c, selected);
        result = StreamPrimarySettlementTypes.PrimarySettlementResult(
            StreamNativeSettlementHash.candidateCommitment(address(this), n),
            key,
            selected.profileId,
            selected.wallet,
            address(0),
            c.sale.amount,
            c.executor,
            c.executionBinding.executionId,
            escrowed,
            c.operationIdentityCommitment,
            c.currentPolicyHash,
            c.boundPolicyHash
        );
        _results[key] = result;
        _officialSettled[
            _totalKey(_CLASS, selected.profileId, selected.wallet, address(0))
        ] += c.sale.amount;
        totalOfficialSettled[address(0)] += c.sale.amount;
        StreamPrimarySettlementEmission.emitSettlement(
            c, result, address(0), c.sale.expectedPrimaryPolicyHash
        );
    }

    function settleDeferred(
        Context memory x,
        mapping(bytes32 => bool) storage settlementConsumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage _results,
        mapping(bytes32 => uint256) storage _officialSettled,
        mapping(address => uint256) storage totalOfficialSettled,
        mapping(bytes32 => bool) storage deferredPurchaseConsumed,
        StreamDeferredNativeSettlementTypes.DeferredNativeCandidate calldata candidate
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory result) {
        StreamDeferredNativeSettlementTypes.DeferredNativeCandidate memory d = candidate;
        _requireNativeContext(x);
        StreamDeferredNativeSettlementValidation.validate(
            StreamDeferredNativeSettlementValidation.Bindings(
                x.core, x.registry, address(x.funding.rights.resolver), address(x.funding.escrow)
            ),
            d
        );
        bytes32 purchaseKey = StreamDeferredNativeSettlementHash.purchaseKey(
            address(this), d.execution.saleAdapter, d.purchaseId
        );
        if (deferredPurchaseConsumed[purchaseKey]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(purchaseKey);
        }
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            address(this), d.execution.saleAdapter, d.execution.executionBinding.executionId
        );
        if (settlementConsumed[key]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(key);
        }
        deferredPurchaseConsumed[purchaseKey] = true;
        settlementConsumed[key] = true;
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c =
            StreamNativeSettlementHash.accountingContext(d.execution);
        StreamSaleTemplate.Selection memory selected = _resolve(x, c);
        bool escrowed = StreamNativePrimaryExecution.fund(
            x.funding, c.sale.collectionId, c.sale.amount, selected
        );
        _requireNativeContext(x);
        StreamDeferredNativeSettlementAdmission.requireAdmission(x.registry, d.execution);
        _requireCurrent(x, c, selected);
        result = StreamPrimarySettlementTypes.PrimarySettlementResult(
            StreamDeferredNativeSettlementHash.candidateCommitment(address(this), d),
            key,
            selected.profileId,
            selected.wallet,
            address(0),
            c.sale.amount,
            c.executor,
            c.executionBinding.executionId,
            escrowed,
            c.operationIdentityCommitment,
            c.currentPolicyHash,
            c.boundPolicyHash
        );
        _results[key] = result;
        _officialSettled[
            _totalKey(_CLASS, selected.profileId, selected.wallet, address(0))
        ] += c.sale.amount;
        totalOfficialSettled[address(0)] += c.sale.amount;
        StreamPrimarySettlementEmission.emitSettlement(
            c, result, address(0), d.originalPrimaryPolicyHash
        );
    }

    function _validateNative(
        Context memory x,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) private view {
        StreamPrimarySettlementValidation.Bindings memory
            bindings = StreamPrimarySettlementValidation.Bindings(
            x.core, x.registry, address(x.funding.rights.resolver), address(x.funding.escrow)
        );
        StreamPrimarySettlementValidation.nativeFields(bindings, c);
        _requireNativeContext(x);
        StreamNativeSettlementAdmission.requireAdmission(x.registry, c);
        StreamPrimarySettlementValidation.nativeBindings(bindings, c);
    }

    function _bindings(Context memory x)
        private
        pure
        returns (StreamPrimarySettlementValidation.Bindings memory)
    {
        return StreamPrimarySettlementValidation.Bindings(
            x.core, x.registry, address(x.funding.rights.resolver), address(x.funding.escrow)
        );
    }

    function _requireNativeContext(Context memory x) private view {
        StreamSettlementAdmission.requireRegistry(x.core, x.coreHash, x.registry, x.registryHash);
        if (address(x.funding.rights.resolver).codehash != x.resolverHash) {
            revert InvalidSettlementContext(address(x.funding.rights.resolver));
        }
        if (address(x.funding.rights.factory).codehash != x.funding.factoryHash) {
            revert InvalidSettlementContext(address(x.funding.rights.factory));
        }
    }

    function _resolve(
        Context memory x,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) private view returns (StreamSaleTemplate.Selection memory) {
        return StreamPrimarySettlementRights.resolve(
            x.funding.rights, c.sale.collectionId, c.rights, c.sale.expectedPrimaryPolicyHash
        );
    }

    function _requireCurrent(
        Context memory x,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        StreamSaleTemplate.Selection memory rights
    ) private view {
        StreamPrimarySettlementRights.requireCurrent(
            x.funding.rights,
            c.sale.collectionId,
            c.rights,
            c.sale.expectedPrimaryPolicyHash,
            rights
        );
    }

    function _totalKey(bytes32 revenueClass, bytes32 profileId, address wallet, address asset)
        private
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(_TOTAL, revenueClass, profileId, wallet, asset));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamSettlementAdmission.sol";
import "../../interfaces/stream/revenue/IStreamNativeSaleBinding.sol";

/// @notice Linked native-only policy over the canonical registry, separate from20 admission.
/// @dev Record/lifecycle predicates preserve the accepted85557c99 bounded reader semantics.
library StreamNativeSettlementAdmission {
    bytes32 private constant VERSION = keccak256("6529STREAM_UNIVERSAL_SETTLEMENT_V1");
    bytes32 private constant ROLE = keccak256("NATIVE_PRIMARY_SALE_ADAPTER");

    struct ModuleFacts {
        uint8 status;
        uint64 registeredAt;
        uint64 statusUpdatedAt;
        uint64 revision;
    }
    error SettlementModuleReadFailed(address module);
    error SettlementModuleReadMalformed(address module, uint256 length);
    error SettlementModuleNotAdmitted(address module);
    error SaleLifecycleReadFailed(address module);
    error SaleLifecycleReadMalformed(address module, uint256 length);
    error SaleLifecycleMismatch(address module, bytes32 saleId);

    function capture(address registry, address sale)
        public
        view
        returns (StreamNativeSettlementTypes.SaleLifecycleBinding memory)
    {
        ModuleFacts memory facts =
            _record(registry, sale, ROLE, type(IStreamNativeSaleBinding).interfaceId);
        if (facts.status != 1) revert SettlementModuleNotAdmitted(sale);
        if (block.timestamp == 0 || block.timestamp > type(uint64).max) {
            revert SaleLifecycleMismatch(sale, 0);
        }
        return
            StreamNativeSettlementTypes.SaleLifecycleBinding(
                uint64(block.timestamp), facts.revision
            );
    }

    function requireAdmission(
        address registry,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) public view {
        ModuleFacts memory facts =
            _record(registry, c.saleAdapter, ROLE, type(IStreamNativeSaleBinding).interfaceId);
        bytes memory data = abi.encodeCall(
            IStreamNativeSaleBinding.nativeSaleLifecycleBinding, (c.sale.settlementId)
        );
        uint256[2] memory words;
        bool ok;
        uint256 size;
        address sale = c.saleAdapter;
        assembly ("memory-safe") {
            ok := staticcall(gas(), sale, add(data, 32), mload(data), words, 64)
            size := returndatasize()
        }
        if (!ok) revert SaleLifecycleReadFailed(sale);
        if (size != 64 || words[0] > type(uint64).max || words[1] > type(uint64).max) {
            revert SaleLifecycleReadMalformed(sale, size);
        }
        if (
            words[0] == 0 || words[0] > block.timestamp
                || words[0] != c.lifecycleBinding.saleCreatedAt
                || words[1] != c.lifecycleBinding.saleAdapterRegistryRevision
        ) revert SaleLifecycleMismatch(sale, c.sale.settlementId);
        _requireLifecycle(facts, sale, uint64(words[0]), uint64(words[1]));
    }

    function isContract(address target) private view returns (bool) {
        return StreamSettlementAdmission.isContract(target);
    }

    function _requireLifecycle(
        ModuleFacts memory facts,
        address module,
        uint64 created,
        uint64 revision
    ) private pure {
        if (
            revision == 0 || revision > facts.revision || created < facts.registeredAt
                || (facts.status == 2
                    && (created >= facts.statusUpdatedAt || revision >= facts.revision))
        ) revert SettlementModuleNotAdmitted(module);
    }

    function _record(address registry, address module, bytes32 role, bytes4 interfaceId)
        private
        view
        returns (ModuleFacts memory facts)
    {
        if (!isContract(module)) revert SettlementModuleNotAdmitted(module);
        bytes memory data = abi.encodeCall(IStreamModuleRegistry.moduleRecord, (module));
        // Dynamic struct return: outer offset; twelve-word head; URI byte length.
        uint256[14] memory words;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), registry, add(data, 32), mload(data), words, 448)
            size := returndatasize()
        }
        if (!ok) revert SettlementModuleReadFailed(module);
        if (
            size < 448 || words[0] != 32 || words[1] > 3 || words[5] > type(uint32).max
                || words[9] != 384 || words[10] > type(uint64).max || words[11] > type(uint64).max
                || words[12] > type(uint64).max || words[13] > size - 448
                || size - 448 != ((words[13] + 31) / 32) * 32
        ) revert SettlementModuleReadMalformed(module, size);
        if (
            (words[1] != 1 && words[1] != 2) || bytes32(words[2]) != role
                || bytes32(words[3]) != VERSION || words[4] != uint256(uint32(interfaceId)) << 224
                || bytes32(words[6]) != module.codehash || words[7] == 0 || words[8] == 0
                || words[10] == 0 || words[10] > block.timestamp || words[11] < words[10]
                || words[11] > block.timestamp || words[12] == 0
        ) revert SettlementModuleNotAdmitted(module);
        // Match canonical registry live eligibility's exact-code ERC165 policy, including
        // its available-gas probes; DEPRECATED cannot use isModuleEligible's ACTIVE-only path.
        if (
            !_interface(module, 0x01ffc9a7, true) || !_interface(module, 0xffffffff, false)
                || !_interface(module, interfaceId, true)
        ) {
            revert SettlementModuleNotAdmitted(module);
        }
        facts =
            ModuleFacts(uint8(words[1]), uint64(words[10]), uint64(words[11]), uint64(words[12]));
    }

    function _interface(address target, bytes4 id, bool expected) private view returns (bool) {
        bytes memory data = abi.encodeWithSelector(bytes4(0x01ffc9a7), id);
        bool ok;
        uint256 size;
        uint256 word;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            word := mload(0)
        }
        return ok && size == 32 && word == (expected ? 1 : 0);
    }
}

