// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/auctions/IStreamPlatformCustodyAuction.sol";
import "../../interfaces/stream/auctions/IStreamPlatformNativeRightsAuction.sol";
import "../../interfaces/stream/auctions/IStreamNativeRightsAuction.sol";

library StreamPlatformCustodyHash {
    function acquisitionFromCalldata(bytes calldata input) public view returns (bytes32) {
        require(
            bytes4(input[:4])
                == IStreamPlatformCustodyAuction.platformCustodyAcquisitionDigest.selector
        );
        return acquisition(
            abi.decode(input[4:], (IStreamPlatformCustodyAuction.PlatformCustodyAuthorization))
        );
    }

    function acquisition(IStreamPlatformCustodyAuction.PlatformCustodyAuthorization memory a)
        public
        view
        returns (bytes32)
    {
        bytes32 domain = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256("6529StreamPlatformPreparedCustodyAuction"),
                keccak256("1"),
                block.chainid,
                address(this)
            )
        );
        return keccak256(
            abi.encodePacked(
                hex"1901",
                domain,
                keccak256(
                    abi.encode(
                        keccak256(
                            "PlatformPreparedCustodyAcquisition(bytes32 configHash,bytes32 declarationHash,bytes32 tokenDataHash,uint256 expectedSaleNonce,uint256 expectedTokenId,uint256 expectedCollectionSerial,uint256 expectedOperationNonce,bytes32 contextHash,address executor,uint256 revealFeeDeposit,bytes32 nonce,uint64 deadline)"
                        ),
                        a
                    )
                )
            )
        );
    }

    function facts(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        bytes32 declaration,
        StreamPreparedNativeRightsTypes.OriginalPolicy memory original
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PLATFORM_CUSTODY_FACTS_V1"),
                block.chainid,
                recorder,
                house,
                f,
                declaration,
                original
            )
        );
    }

    function candidate(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        bytes32 declaration,
        StreamPreparedNativeRightsTypes.OriginalPolicy memory original,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        bytes32 beneficiaries
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PLATFORM_CUSTODY_CANDIDATE_V1"),
                block.chainid,
                recorder,
                house,
                f,
                declaration,
                original,
                c,
                beneficiaries
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamPlatformCustodyValidation.sol";
import "../../interfaces/stream/revenue/IStreamPlatformCustodyPrimarySettlement.sol";
import "./StreamNativePrimaryExecution.sol";
import "./StreamScopedNativePrimaryExecution.sol";
import "./StreamPrimarySettlementEmission.sol";
import "./StreamPrimarySettlementHash.sol";

/// @notice Official payment before custody delivery, with no mint or ledger operation.
import "./StreamPlatformTokenCustodyHash.sol";

library StreamPlatformCustodyRecording {
    struct Context {
        StreamNativeCustodyPrimaryAdmission.Context admission;
        bytes32 resolverHash;
        StreamNativePrimaryExecution.Context funding;
    }
    event PlatformCustodyRevenueRecorded(
        uint16 schemaVersion,
        bytes32 indexed settlementKey,
        bytes32 indexed saleKey,
        bytes32 indexed factsHash,
        bytes32 declarationHash,
        StreamPreparedNativeRightsTypes.OriginalPolicy original,
        StreamNativeCustodySettlementTypes.Facts facts,
        bytes32 beneficiaryHash,
        StreamPrimarySettlementTypes.PrimarySettlementResult result
    );

    function execute(
        Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        mapping(bytes32 => bool) storage saleConsumed,
        mapping(bytes32 => bool) storage consumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage results,
        mapping(bytes32 => bytes32) storage factsHashes,
        mapping(bytes32 => uint256) storage official,
        mapping(address => uint256) storage total,
        bytes32 id
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory r) {
        StreamPlatformTokenCustodyHash.requireLegacy(msg.sender, id);
        requireContext(x);
        StreamNativeCustodySettlementTypes.Facts memory f =
            StreamPlatformCustodyValidation.read(x.admission, pin, id);
        (bytes32 declaration, StreamPreparedNativeRightsTypes.OriginalPolicy memory original) =
            StreamPlatformCustodyValidation.binding(x.funding.rights.resolver, msg.sender, f);
        if (
            msg.value != f.auction.winner.amount
                || f.auction.winner.payer == address(x.funding.escrow)
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected,
            bytes32 beneficiaryHash
        ) = StreamPlatformCustodyValidation.derive(x.funding.rights, f, msg.sender, address(this));
        if (c.sale.payer == selected.wallet) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 saleKey = StreamPreparedNativeSettlementHash.saleKey(
            address(this), msg.sender, f.auction.saleId, f.auction.saleNonce
        );
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            address(this), msg.sender, c.executionBinding.executionId
        );
        if (saleConsumed[saleKey] || consumed[key]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(key);
        }
        saleConsumed[saleKey] = true;
        consumed[key] = true;
        bool escrowed = StreamScopedNativePrimaryExecution.fund(
            x.funding,
            c.sale.collectionId,
            c.sale.tokenId,
            original.mode,
            c.sale.poster,
            c.sale.amount,
            selected,
            beneficiaryHash
        );
        requireContext(x);
        StreamNativeCustodySettlementTypes.Facts memory after_ =
            StreamPlatformCustodyValidation.read(x.admission, pin, id);
        (
            bytes32 afterDeclaration,
            StreamPreparedNativeRightsTypes.OriginalPolicy memory afterOriginal
        ) = StreamPlatformCustodyValidation.binding(x.funding.rights.resolver, msg.sender, after_);
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory afterCandidate,,
            bytes32 afterBeneficiaries
        ) = StreamPlatformCustodyValidation.derive(
            x.funding.rights, after_, msg.sender, address(this)
        );
        if (
            keccak256(abi.encode(f)) != keccak256(abi.encode(after_))
                || declaration != afterDeclaration
                || keccak256(abi.encode(original)) != keccak256(abi.encode(afterOriginal))
                || keccak256(abi.encode(c)) != keccak256(abi.encode(afterCandidate))
                || beneficiaryHash != afterBeneficiaries
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 factsHash =
            StreamPlatformCustodyHash.facts(address(this), msg.sender, f, declaration, original);
        r = StreamPrimarySettlementTypes.PrimarySettlementResult(
            StreamPlatformCustodyHash.candidate(
                address(this), msg.sender, f, declaration, original, c, beneficiaryHash
            ),
            key,
            selected.profileId,
            selected.wallet,
            address(0),
            c.sale.amount,
            c.executor,
            c.executionBinding.executionId,
            escrowed,
            0,
            0,
            0
        );
        results[key] = r;
        factsHashes[key] = factsHash;
        official[
            keccak256(
                abi.encode(
                    keccak256("6529STREAM_OFFICIAL_PRIMARY_SETTLED_V1"),
                    keccak256("PRIMARY_SALE"),
                    selected.profileId,
                    selected.wallet,
                    address(0)
                )
            )
        ] += r.amount;
        total[address(0)] += r.amount;
        StreamPrimarySettlementEmission.emitSettlement(
            c, r, address(0), f.auction.config.expectedPrimaryPolicyHash
        );
        emit PlatformCustodyRevenueRecorded(
            1, key, saleKey, factsHash, declaration, original, f, beneficiaryHash, r
        );
    }

    function requireContext(Context memory x) private view {
        StreamSettlementAdmission.requireRegistry(
            x.admission.core, x.admission.coreHash, x.admission.registry, x.admission.registryHash
        );
        if (
            address(x.funding.rights.resolver).codehash != x.resolverHash
                || address(x.funding.rights.factory).codehash != x.funding.factoryHash
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamNativeCustodyPrimaryValidation.sol";
import "./StreamPlatformCustodyHash.sol";
import "./StreamPlatformPrimaryProfile.sol";
import "./StreamPreparedNativeRightsProjection.sol";

library StreamPlatformCustodyValidation {
    function read(
        StreamNativeCustodyPrimaryAdmission.Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        bytes32 id
    ) public view returns (StreamNativeCustodySettlementTypes.Facts memory f) {
        return StreamNativeCustodyPrimaryValidation.read(x, pin, id);
    }

    function binding(
        IStreamRevenueResolver resolver,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f
    )
        public
        view
        returns (
            bytes32 declaration,
            StreamPreparedNativeRightsTypes.OriginalPolicy memory original
        )
    {
        original = IStreamNativeRightsAuction(house).originalAuctionRights(f.auctionId);
        declaration =
            IStreamPlatformNativeRightsAuction(house).platformAuctionDeclaration(f.auction.saleId);
        if (
            (original.mode < 8 || original.mode > 11)
                || ((original.mode <= 9) != (original.templateId != 0))
                || original.assignmentHash == 0 || declaration == 0 || f.auction.artistId != 0
                || f.auction.bindingGeneration != 0 || f.auction.bindingHash != 0
                || StreamPlatformSaleTemplate.declaration(resolver, f.auction.config.collectionId)
                    != declaration
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
    }

    function selection(
        IStreamRevenueResolver resolver,
        uint256 collection,
        uint256 token,
        uint8 mode,
        address poster
    ) public view returns (StreamSaleTemplate.Selection memory, bytes32) {
        if (mode == 8 || mode == 9) {
            return StreamPlatformSaleTemplate.resolve(resolver, collection, token, mode, poster);
        }
        return StreamPlatformPrimaryProfile.resolve(resolver, collection, token, mode, poster);
    }

    function derive(
        StreamPrimarySettlementRights.Context memory x,
        StreamNativeCustodySettlementTypes.Facts memory f,
        address house,
        address recorder
    )
        public
        view
        returns (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected,
            bytes32 beneficiaryHash
        )
    {
        (bytes32 declaration, StreamPreparedNativeRightsTypes.OriginalPolicy memory original) =
            binding(x.resolver, house, f);
        IStreamNativeEnglishAuction.Auction memory a = f.auction;
        (selected, beneficiaryHash) = selection(
            x.resolver, a.config.collectionId, a.tokenId, original.mode, a.config.poster
        );
        c.saleAdapter = house;
        c.executor = a.winner.executor;
        c.sale = StreamPrimarySettlementTypes.PrimarySale(
            a.saleId,
            keccak256("PRIMARY_SALE"),
            1,
            a.config.collectionId,
            a.tokenId,
            a.saleNonce,
            a.winner.payer,
            a.config.poster,
            a.winner.deliverTo,
            a.winner.amount,
            StreamPreparedNativeRightsProjection.policyHash(
                x.resolver, a.config.collectionId, a.tokenId, selected
            )
        );
        c.lifecycleBinding.saleCreatedAt = a.lifecycle.saleCreatedAt;
        c.lifecycleBinding.saleAdapterRegistryRevision = a.lifecycle.saleAdapterRegistryRevision;
        c.executionBinding = StreamPrimarySettlementTypes.SaleExecutionBinding(
            keccak256(
                abi.encode(
                    keccak256("6529STREAM_PLATFORM_CUSTODY_EXECUTION_V1"),
                    block.chainid,
                    recorder,
                    house,
                    f,
                    declaration,
                    original,
                    beneficiaryHash
                )
            ),
            a.winner.bidIndex,
            a.winner.signed ? 1 : 2,
            a.winner.authorizationDigest
        );
        c.orchestrationOrder = 3;
        // No current mint operation exists in this paid transfer. Original acquisition is
        // retained separately in f.origin; never alias it into these current-mint fields.
        c.rights = StreamPrimarySettlementTypes.PrimaryRights(
            selected.profileId,
            selected.wallet,
            selected.templateId,
            selected.assignmentHash,
            selected.entriesHash
        );
        c.saleExecutionHash =
            StreamPlatformCustodyHash.facts(recorder, house, f, declaration, original);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamPrimarySettlementRights.sol";
import "../mint/StreamPlatformSaleTemplate.sol";

/// @notice Verified collection/default fixed profiles under current declared platform authority.
library StreamPlatformPrimaryProfile {
    error InvalidPlatformPrimaryProfile();

    function resolve(
        IStreamRevenueResolver resolver,
        uint256 collection,
        uint256 token,
        uint8 mode,
        address poster
    ) public view returns (StreamSaleTemplate.Selection memory selected, bytes32 witness) {
        if ((mode != 10 && mode != 11) || collection == 0 || poster == address(0)) {
            revert InvalidPlatformPrimaryProfile();
        }
        bytes32 declaration = StreamPlatformSaleTemplate.declaration(resolver, collection);
        IStreamRevenueResolver.ResolvedPrimaryAssignment memory a =
            resolver.resolvePrimaryAssignment(collection, token, keccak256("PRIMARY_SALE"));
        if (
            !a.exists || a.assignmentType != 1 || a.profileId == 0 || a.templateId != 0
                || a.assignmentHash == 0 || a.policyHash != 0 || a.scope != (mode == 10 ? 1 : 0)
                || a.scopeId != (mode == 10 ? collection : 0)
        ) revert InvalidPlatformPrimaryProfile();
        if (
            token != 0
                && keccak256(abi.encode(a))
                    != keccak256(
                        abi.encode(
                            resolver.resolvePrimaryAssignment(
                                collection, 0, keccak256("PRIMARY_SALE")
                            )
                        )
                    )
        ) revert InvalidPlatformPrimaryProfile();
        IStreamSplitFactory factory = IStreamSplitFactory(resolver.splitFactory());
        selected = StreamSaleTemplate.Selection(
            a.profileId,
            factory.walletFor(a.profileId),
            0,
            a.assignmentHash,
            factory.profileEntriesHash(a.profileId)
        );
        StreamPrimarySettlementRights.requireWallet(
            StreamPrimarySettlementRights.Context(
                resolver, factory, factory.splitWalletRuntimeCodeHash()
            ),
            selected
        );
        if (
            selected.wallet == address(0) || selected.entriesHash == 0
                || StreamPlatformSaleTemplate.declaration(resolver, collection) != declaration
                || keccak256(abi.encode(a))
                    != keccak256(
                        abi.encode(
                            resolver.resolvePrimaryAssignment(
                                collection, token, keccak256("PRIMARY_SALE")
                            )
                        )
                    )
        ) revert InvalidPlatformPrimaryProfile();
        witness = keccak256(
            abi.encode(
                keccak256("6529STREAM_PLATFORM_PRIMARY_PROFILE_WITNESS_V1"),
                block.chainid,
                address(resolver),
                collection,
                token,
                mode,
                declaration,
                poster,
                a,
                selected
            )
        );
    }
}

