pragma solidity ^0.8.19;
import "../../interfaces/stream/auctions/IStreamPlatformTokenCustodyAuction.sol";
import "../../interfaces/stream/auctions/IStreamPlatformNativeRightsAuction.sol";
import "../../interfaces/stream/auctions/IStreamNativeRightsAuction.sol";
import "../../vendor/openzeppelin/IERC165.sol";
import "../../interfaces/stream/revenue/StreamNativeCustodySettlementTypes.sol";

library StreamPlatformTokenCustodyHash {
    function digest(address house, StreamPlatformTokenCustodyTypes.Authorization memory a)
        public
        view
        returns (bytes32)
    {
        bytes32 domain = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256("6529StreamPlatformTokenCustodyRights"),
                keccak256("1"),
                block.chainid,
                house
            )
        );
        return keccak256(
            abi.encodePacked(
                hex"1901",
                domain,
                keccak256(
                    abi.encode(
                        keccak256(
                            "PlatformTokenCustodyRights(bytes32 auctionId,bytes32 baseConfigHash,bytes32 originHash,uint256 tokenId,bytes32 declarationHash,uint8 rightsMode,bytes32 assignmentHash,bytes32 primaryPolicyHash,uint8 primaryPolicyMode,bytes32 nonce,uint64 deadline)"
                        ),
                        a
                    )
                )
            )
        );
    }

    function configuration(address house, StreamPlatformTokenCustodyTypes.Activation memory a)
        public
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PLATFORM_TOKEN_CUSTODY_ALLOW_CURRENT_CONFIG_V1"),
                block.chainid,
                house,
                a.authorization,
                a.authorizationDigest
            )
        );
    }

    function readOptional(address house, bytes32 id)
        public
        view
        returns (StreamPlatformTokenCustodyTypes.Activation memory a)
    {
        if (IERC165(house).supportsInterface(type(IStreamPlatformTokenCustodyAuction).interfaceId)) return IStreamPlatformTokenCustodyAuction(
                house
            ).platformTokenCustodyActivation(id);
    }

    function requireLegacy(address house, bytes32 id) public view {
        if (readOptional(house, id).authorizationDigest != 0) {
            revert IStreamPlatformTokenCustodyAuction.PlatformTokenCustodyEntryRequired(id);
        }
    }

    function facts(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamPlatformTokenCustodyTypes.Activation memory activation,
        StreamPreparedNativeRightsTypes.OriginalPolicy memory original
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PLATFORM_TOKEN_CUSTODY_FACTS_V1"),
                block.chainid,
                recorder,
                house,
                f,
                activation,
                original
            )
        );
    }

    function candidate(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamPlatformTokenCustodyTypes.Activation memory activation,
        StreamPreparedNativeRightsTypes.OriginalPolicy memory original,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        bytes32 beneficiaries
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PLATFORM_TOKEN_CUSTODY_CANDIDATE_V1"),
                block.chainid,
                recorder,
                house,
                f,
                activation,
                original,
                c,
                beneficiaries
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamPlatformTokenCustodyValidation.sol";
import "../../interfaces/stream/revenue/IStreamPlatformTokenCustodySettlement.sol";
import "./StreamNativePrimaryExecution.sol";
import "./StreamScopedNativePrimaryExecution.sol";
import "./StreamPrimarySettlementEmission.sol";
import "./StreamPrimarySettlementHash.sol";

/// @notice Official payment before custody delivery, with no mint or ledger operation.
library StreamPlatformTokenCustodyRecording {
    struct Context {
        StreamNativeCustodyPrimaryAdmission.Context admission;
        bytes32 resolverHash;
        StreamNativePrimaryExecution.Context funding;
    }
    event PlatformTokenCustodyRevenueRecorded(
        uint16 schemaVersion,
        bytes32 indexed settlementKey,
        bytes32 indexed saleKey,
        bytes32 indexed factsHash,
        StreamPlatformTokenCustodyTypes.Activation activation,
        StreamPreparedNativeRightsTypes.OriginalPolicy original,
        StreamNativeCustodySettlementTypes.Facts facts,
        bytes32 beneficiaryHash,
        StreamPrimarySettlementTypes.PrimarySettlementResult result
    );

    function execute(
        Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        mapping(bytes32 => bool) storage saleConsumed,
        mapping(bytes32 => bool) storage consumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage results,
        mapping(bytes32 => bytes32) storage factsHashes,
        mapping(bytes32 => uint256) storage official,
        mapping(address => uint256) storage total,
        bytes32 id
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory r) {
        requireContext(x);
        StreamNativeCustodySettlementTypes.Facts memory f =
            StreamPlatformTokenCustodyValidation.read(x.admission, pin, id);
        (
            StreamPlatformTokenCustodyTypes.Activation memory activation,
            StreamPreparedNativeRightsTypes.OriginalPolicy memory original
        ) = StreamPlatformTokenCustodyValidation.activation(
            x.funding.rights.resolver, msg.sender, f
        );
        if (
            msg.value != f.auction.winner.amount
                || f.auction.winner.payer == address(x.funding.escrow)
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected,
            bytes32 beneficiaryHash
        ) = StreamPlatformTokenCustodyValidation.derive(
            x.funding.rights, f, msg.sender, address(this)
        );
        if (c.sale.payer == selected.wallet) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 saleKey = StreamPreparedNativeSettlementHash.saleKey(
            address(this), msg.sender, f.auction.saleId, f.auction.saleNonce
        );
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            address(this), msg.sender, c.executionBinding.executionId
        );
        if (saleConsumed[saleKey] || consumed[key]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(key);
        }
        saleConsumed[saleKey] = true;
        consumed[key] = true;
        bool escrowed = StreamScopedNativePrimaryExecution.fund(
            x.funding,
            c.sale.collectionId,
            c.sale.tokenId,
            activation.authorization.rightsMode,
            c.sale.poster,
            c.sale.amount,
            selected,
            beneficiaryHash
        );
        requireContext(x);
        StreamNativeCustodySettlementTypes.Facts memory after_ =
            StreamPlatformTokenCustodyValidation.read(x.admission, pin, id);
        (
            StreamPlatformTokenCustodyTypes.Activation memory afterActivation,
            StreamPreparedNativeRightsTypes.OriginalPolicy memory afterOriginal
        ) = StreamPlatformTokenCustodyValidation.activation(
            x.funding.rights.resolver, msg.sender, after_
        );
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory afterCandidate,,
            bytes32 afterBeneficiaries
        ) = StreamPlatformTokenCustodyValidation.derive(
            x.funding.rights, after_, msg.sender, address(this)
        );
        if (
            keccak256(abi.encode(f)) != keccak256(abi.encode(after_))
                || keccak256(abi.encode(activation)) != keccak256(abi.encode(afterActivation))
                || keccak256(abi.encode(original)) != keccak256(abi.encode(afterOriginal))
                || keccak256(abi.encode(c)) != keccak256(abi.encode(afterCandidate))
                || beneficiaryHash != afterBeneficiaries
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 factsHash = StreamPlatformTokenCustodyHash.facts(
            address(this), msg.sender, f, activation, original
        );
        r = StreamPrimarySettlementTypes.PrimarySettlementResult(
            StreamPlatformTokenCustodyHash.candidate(
                address(this), msg.sender, f, activation, original, c, beneficiaryHash
            ),
            key,
            selected.profileId,
            selected.wallet,
            address(0),
            c.sale.amount,
            c.executor,
            c.executionBinding.executionId,
            escrowed,
            0,
            0,
            0
        );
        results[key] = r;
        factsHashes[key] = factsHash;
        official[
            keccak256(
                abi.encode(
                    keccak256("6529STREAM_OFFICIAL_PRIMARY_SETTLED_V1"),
                    keccak256("PRIMARY_SALE"),
                    selected.profileId,
                    selected.wallet,
                    address(0)
                )
            )
        ] += r.amount;
        total[address(0)] += r.amount;
        StreamPrimarySettlementEmission.emitSettlement(
            c, r, address(0), f.auction.config.expectedPrimaryPolicyHash
        );
        emit PlatformTokenCustodyRevenueRecorded(
            1, key, saleKey, factsHash, activation, original, f, beneficiaryHash, r
        );
    }

    function requireContext(Context memory x) private view {
        StreamSettlementAdmission.requireRegistry(
            x.admission.core, x.admission.coreHash, x.admission.registry, x.admission.registryHash
        );
        if (
            address(x.funding.rights.resolver).codehash != x.resolverHash
                || address(x.funding.rights.factory).codehash != x.funding.factoryHash
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
    }
}

