/// @notice New prepared recorder entry through a fixed linked boundary and exact storage refs.
/// @dev No storage overlay, callback-selected state or new authority. Original recorder context
/// and full facts are rechecked after funding; every effect remains in the same transaction.
library StreamPreparedNativeRightsRecording {
    struct Context {
        address core;
        bytes32 coreHash;
        address registry;
        bytes32 registryHash;
        bytes32 resolverHash;
        StreamNativePrimaryExecution.Context funding;
    }
    error InvalidSettlementContext(address target);
    event PreparedNativeRightsRevenueRecorded(
        bytes32 indexed settlementKey,
        bytes32 indexed saleKey,
        bytes32 indexed factsHash,
        StreamPreparedNativeRightsTypes.Facts facts,
        StreamPreparedNativeRightsTypes.Intent intent,
        bytes32 currentPrimaryPolicyHash
    );

    event DynamicPreparedPrimaryBeneficiariesBound(
        uint16 schemaVersion,
        bytes32 indexed settlementKey,
        bytes32 indexed templateId,
        bytes32 beneficiaryHash,
        address poster
    );

    event PlatformPreparedPrimaryBound(
        uint16 schemaVersion,
        bytes32 indexed settlementKey,
        bytes32 indexed saleKey,
        bytes32 indexed declarationHash,
        uint8 mode,
        bytes32 beneficiaryHash,
        address poster,
        bytes32 currentPrimaryPolicyHash
    );

    function execute(
        Context memory x,
        mapping(bytes32 => bool) storage saleConsumed,
        mapping(bytes32 => bool) storage settlementConsumed,
        mapping(bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult) storage results,
        mapping(bytes32 => bytes32) storage factsHashes,
        mapping(bytes32 => uint256) storage officialSettled,
        mapping(address => uint256) storage totals,
        StreamPreparedNativeRightsTypes.Facts calldata rights,
        StreamPreparedNativeRightsTypes.Intent calldata original
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory result) {
        StreamPreparedNativeSettlementTypes.Facts memory facts = rights.mint;
        StreamPreparedNativeSettlementTypes.Intent memory intent = original.sale;
        requireContext(x);
        if (
            msg.sender != facts.saleAdapter || facts.recorder != address(this)
                || facts.recorderCodeHash != address(this).codehash || msg.value != intent.amount
                || intent.payer == address(this) || intent.payer == facts.saleAdapter
                || intent.payer == address(x.funding.escrow)
        ) revert IStreamPreparedNativePrimarySaleSettlement.InvalidPreparedNativeSettlement();
        StreamNativeSettlementTypes.SaleLifecycleBinding memory lifecycle =
            StreamPreparedNativeRightsValidation.requireActive(x.core, x.registry, rights, original);
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected,
            bytes32 beneficiaryHash
        ) = StreamPreparedNativeRightsAccounting.derive(
            x.funding.rights, rights, original, lifecycle
        );
        if (intent.payer == selected.wallet) {
            revert IStreamPreparedNativePrimarySaleSettlement.InvalidPreparedNativeSettlement();
        }
        bytes32 saleKey = StreamPreparedNativeSettlementHash.saleKey(
            address(this), facts.saleAdapter, intent.saleId, intent.saleNonce
        );
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            address(this), facts.saleAdapter, c.executionBinding.executionId
        );
        if (saleConsumed[saleKey]) {
            revert IStreamPreparedNativePrimarySaleSettlement.PreparedNativeSaleAlreadySettled(saleKey);
        }
        if (settlementConsumed[key]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(key);
        }
        saleConsumed[saleKey] = true;
        settlementConsumed[key] = true;
        bool escrowed;
        if (original.original.mode >= 5 && original.original.mode <= 11) {
            escrowed = StreamScopedNativePrimaryExecution.fund(
                x.funding,
                c.sale.collectionId,
                c.sale.tokenId,
                original.original.mode,
                intent.poster,
                c.sale.amount,
                selected,
                beneficiaryHash
            );
        } else if (
            original.original.mode == StreamPreparedNativeRightsTypes.DYNAMIC_COLLECTION_TEMPLATE
        ) {
            escrowed = StreamNativePrimaryExecution.fundForPoster(
                x.funding,
                c.sale.collectionId,
                c.sale.amount,
                selected,
                intent.poster,
                beneficiaryHash
            );
        } else {
            escrowed = StreamNativePrimaryExecution.fund(
                x.funding, c.sale.collectionId, c.sale.amount, selected
            );
        }
        requireContext(x);
        StreamNativeSettlementTypes.SaleLifecycleBinding memory current =
            StreamPreparedNativeRightsValidation.requireActive(x.core, x.registry, rights, original);
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory after_,,
            bytes32 currentBeneficiaries
        ) = StreamPreparedNativeRightsAccounting.derive(x.funding.rights, rights, original, current);
        if (
            keccak256(abi.encode(after_)) != keccak256(abi.encode(c))
                || currentBeneficiaries != beneficiaryHash
        ) {
            revert IStreamPreparedNativePrimarySaleSettlement.InvalidPreparedNativeSettlement();
        }
        result = StreamPrimarySettlementTypes.PrimarySettlementResult(
            StreamPreparedNativeRightsHash.candidateCommitment(rights, original, c),
            key,
            selected.profileId,
            selected.wallet,
            address(0),
            intent.amount,
            intent.executor,
            c.executionBinding.executionId,
            escrowed,
            facts.operationRoot,
            facts.currentPolicyHash,
            facts.boundPolicyHash
        );
        results[key] = result;
        factsHashes[key] = StreamPreparedNativeRightsHash.factsHash(rights);
        officialSettled[
            keccak256(
                abi.encode(
                    keccak256("6529STREAM_OFFICIAL_PRIMARY_SETTLED_V1"),
                    keccak256("PRIMARY_SALE"),
                    selected.profileId,
                    selected.wallet,
                    address(0)
                )
            )
        ] += intent.amount;
        totals[address(0)] += intent.amount;
        StreamPrimarySettlementEmission.emitSettlement(
            c, result, address(0), intent.originalPrimaryPolicyHash
        );
        if (original.original.mode >= 8 && original.original.mode <= 11) {
            emit PlatformPreparedPrimaryBound(
                1,
                key,
                saleKey,
                StreamPlatformSaleTemplate.declaration(
                    x.funding.rights.resolver, c.sale.collectionId
                ),
                original.original.mode,
                beneficiaryHash,
                intent.poster,
                c.sale.expectedPrimaryPolicyHash
            );
        } else if (beneficiaryHash != 0) {
            emit DynamicPreparedPrimaryBeneficiariesBound(
                1, key, selected.templateId, beneficiaryHash, intent.poster
            );
        }
        emit PreparedNativeRightsRevenueRecorded(
            key, saleKey, factsHashes[key], rights, original, c.sale.expectedPrimaryPolicyHash
        );
    }

    function requireContext(Context memory x) private view {
        StreamSettlementAdmission.requireRegistry(x.core, x.coreHash, x.registry, x.registryHash);
        if (address(x.funding.rights.resolver).codehash != x.resolverHash) {
            revert InvalidSettlementContext(address(x.funding.rights.resolver));
        }
        if (address(x.funding.rights.factory).codehash != x.funding.factoryHash) {
            revert InvalidSettlementContext(address(x.funding.rights.factory));
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamPreparedNativeSettlementValidation.sol";
import "./StreamPreparedNativeRightsHash.sol";
import "../../interfaces/stream/mint/IStreamPreparedNativeRightsMint.sol";
import "../../interfaces/stream/revenue/IStreamPreparedNativeRightsPrimarySettlement.sol";

/// @notice Original authority and actual Core preparation joins for the distinct rights entry.
library StreamPreparedNativeRightsValidation {
    function readIntent(address sale, address recorder, bytes32 hash)
        public
        view
        returns (StreamPreparedNativeRightsTypes.Intent memory intent)
    {
        bytes memory raw = StreamPreparedNativeSettlementValidation.read(
            sale,
            abi.encodeCall(
                IStreamPreparedNativeRightsSaleBinding.activePreparedNativeRightsIntent, (hash)
            ),
            672
        );
        intent = abi.decode(raw, (StreamPreparedNativeRightsTypes.Intent));
        if (
            hash == 0 || keccak256(raw) != keccak256(abi.encode(intent))
                || StreamPreparedNativeRightsHash.intentHash(sale, recorder, intent) != hash
        ) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
    }

    function requireBindings(
        address core,
        address registry,
        address manager,
        address sale,
        address recorder,
        bytes32 recorderHash
    ) public view {
        StreamPreparedNativeSettlementValidation.requireBindings(
            core, registry, manager, sale, recorder, recorderHash
        );
        bytes memory raw = StreamPreparedNativeSettlementValidation.read(
            recorder,
            abi.encodeWithSelector(
                bytes4(0x01ffc9a7), type(IStreamPreparedNativeRightsPrimarySettlement).interfaceId
            ),
            32
        );
        if (abi.decode(raw, (uint256)) != 1) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
    }

    function requireIntentFields(
        StreamPreparedNativeRightsTypes.Facts memory facts,
        StreamPreparedNativeRightsTypes.Intent memory intent
    ) public pure {
        if (
            (intent.original.mode != StreamPreparedNativeRightsTypes.COLLECTION_TEMPLATE
                    && intent.original.mode
                        != StreamPreparedNativeRightsTypes.CONSENTED_COLLECTION_TEMPLATE
                    && intent.original.mode
                        != StreamPreparedNativeRightsTypes.DYNAMIC_COLLECTION_TEMPLATE
                    && intent.original.mode != StreamPreparedNativeRightsTypes.DEFAULT_PROFILE
                    && intent.original.mode != StreamPreparedNativeRightsTypes.DEFAULT_TEMPLATE
                    && intent.original.mode
                        != StreamPreparedNativeRightsTypes.CONSENTED_DEFAULT_TEMPLATE
                    && intent.original.mode
                        != StreamPreparedNativeRightsTypes.DYNAMIC_DEFAULT_TEMPLATE
                    && intent.original.mode
                        != StreamPreparedNativeRightsTypes.PLATFORM_COLLECTION_TEMPLATE
                    && intent.original.mode
                        != StreamPreparedNativeRightsTypes.PLATFORM_DEFAULT_TEMPLATE
                    && intent.original.mode
                        != StreamPreparedNativeRightsTypes.PLATFORM_COLLECTION_PROFILE
                    && intent.original.mode
                        != StreamPreparedNativeRightsTypes.PLATFORM_DEFAULT_PROFILE)
                || intent.original.assignmentHash == 0
                || ((intent.original.mode == StreamPreparedNativeRightsTypes.DEFAULT_PROFILE
                        || intent.original.mode
                            == StreamPreparedNativeRightsTypes.PLATFORM_COLLECTION_PROFILE
                        || intent.original.mode
                            == StreamPreparedNativeRightsTypes.PLATFORM_DEFAULT_PROFILE)
                        ? intent.original.templateId != 0
                        : intent.original.templateId == 0)
                || keccak256(abi.encode(facts.original)) != keccak256(abi.encode(intent.original))
        ) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
        StreamPreparedNativeSettlementValidation.requireIntentFields(facts.mint, intent.sale);
    }

    function requireActive(
        address core,
        address registry,
        StreamPreparedNativeRightsTypes.Facts memory rights,
        StreamPreparedNativeRightsTypes.Intent memory original
    ) public view returns (StreamNativeSettlementTypes.SaleLifecycleBinding memory lifecycle) {
        StreamPreparedNativeSettlementTypes.Facts memory facts = rights.mint;
        StreamPreparedNativeSettlementTypes.Intent memory intent = original.sale;
        requireIntentFields(rights, original);
        lifecycle = StreamPreparedNativeSettlementAdmission.requireAdmission(
            registry, facts.saleAdapter, intent.saleId
        );
        requireBindings(
            core,
            registry,
            facts.mintManager,
            facts.saleAdapter,
            facts.recorder,
            facts.recorderCodeHash
        );
        StreamPreparedNativeRightsTypes.Intent memory saved =
            readIntent(facts.saleAdapter, facts.recorder, facts.intentHash);
        if (keccak256(abi.encode(saved)) != keccak256(abi.encode(original))) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
        bytes memory raw = StreamPreparedNativeSettlementValidation.read(
            facts.mintManager,
            abi.encodeCall(IStreamPreparedNativeRightsMint.activePreparedNativeRights, ()),
            672
        );
        if (keccak256(raw) != keccak256(abi.encode(rights))) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
        raw = StreamPreparedNativeSettlementValidation.read(
            core, abi.encodeCall(IStreamCoreMint.preparedMint, (facts.tokenId)), 96
        );
        StreamPreparedMintRecord memory prepared = abi.decode(raw, (StreamPreparedMintRecord));
        if (
            !prepared.exists || prepared.operationId != facts.operationId
                || prepared.collectionId != facts.collectionId
                || keccak256(raw) != keccak256(abi.encode(prepared))
                || uint256(
                        StreamPreparedNativeSettlementValidation.word(
                            core, "pendingPreparedMintTokenId()"
                        )
                    ) != facts.tokenId || facts.tokenId == 0
        ) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
        raw = StreamPreparedNativeSettlementValidation.read(
            core, abi.encodeCall(IStreamCoreIdentity.tokenCollectionIdentity, (facts.tokenId)), 128
        );
        (bool exists, uint256 collection, uint256 serial, bool burned) =
            abi.decode(raw, (bool, uint256, uint256, bool));
        if (
            !exists || burned || collection != facts.collectionId
                || serial != facts.collectionSerial
                || keccak256(raw) != keccak256(abi.encode(exists, collection, serial, burned))
        ) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
        raw = StreamPreparedNativeSettlementValidation.read(
            core, abi.encodeCall(IStreamCoreIdentity.tokenLifecycle, (facts.tokenId)), 32
        );
        if (abi.decode(raw, (uint256)) != 1) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
        address ledger =
            StreamPreparedNativeSettlementValidation.addressWord(facts.mintManager, "mintLedger()");
        raw = StreamPreparedNativeSettlementValidation.read(
            ledger,
            abi.encodeCall(
                IStreamMintLedger.isManagerOperationRootUsed,
                (facts.mintManager, facts.operationRoot)
            ),
            32
        );
        if (abi.decode(raw, (uint256)) != 1) {
            revert IStreamPreparedNativeRightsPrimarySettlement.InvalidPreparedNativeRights();
        }
    }
}

