pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/StreamPrimarySettlementTypes.sol";
import "./StreamPrimarySaleFloorCall.sol";

/// @notice Canonical official settlement events emitted in the recorder's linked call context.
/// @dev Immediate calls supply equal expected/current hashes; deferred calls retain the purchase hash.
library StreamPrimarySettlementEmission {
    bytes32 private constant _CLASS = keccak256("PRIMARY_SALE");
    event PrimaryRevenueSettled(
        bytes32 indexed settlementKey,
        bytes32 indexed revenueClass,
        bytes32 indexed profileId,
        uint16 schemaVersion,
        address wallet,
        address asset,
        address payer,
        uint256 amount,
        bytes32 saleContextHash,
        bool policyDrift,
        uint8 assignmentType
    );
    event PrimaryRevenueSettlementContext(
        bytes32 indexed settlementKey,
        bytes32 indexed revenueClass,
        bytes32 indexed profileId,
        uint16 schemaVersion,
        address settlementCaller,
        bytes32 settlementId,
        uint8 policyMode,
        uint256 collectionId,
        uint256 tokenId,
        bytes32 operationRoot,
        bytes32 operationId,
        uint256 saleNonce,
        address poster,
        address beneficiary,
        bytes32 templateId
    );
    event PrimaryRevenueSettlementPolicy(
        bytes32 indexed settlementKey,
        bytes32 indexed revenueClass,
        bytes32 indexed profileId,
        uint16 schemaVersion,
        bytes32 expectedPrimaryPolicyHash,
        bytes32 resolvedPrimaryPolicyHash,
        bytes32 resolvedAssignmentHash,
        bytes32 templateId
    );
    event PrimaryRevenueExecutionBound(
        bytes32 indexed settlementKey,
        address indexed saleAdapter,
        bytes32 indexed executionId,
        uint16 schemaVersion,
        address executor,
        address paymentAdapter,
        bytes32 candidateCommitment,
        bytes32 currentPolicyHash,
        bytes32 boundPolicyHash
    );

    struct ContextEventData {
        uint16 schemaVersion;
        address settlementCaller;
        bytes32 settlementId;
        uint8 policyMode;
        uint256 collectionId;
        uint256 tokenId;
        bytes32 operationRoot;
        bytes32 operationId;
        uint256 saleNonce;
        address poster;
        address beneficiary;
        bytes32 templateId;
    }
    bytes32 private constant _CONTEXT_EVENT = keccak256(
        "PrimaryRevenueSettlementContext(bytes32,bytes32,bytes32,uint16,address,bytes32,uint8,uint256,uint256,bytes32,bytes32,uint256,address,address,bytes32)"
    );

    function emitSettlement(
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory r,
        address paymentAdapter,
        bytes32 expectedPolicyHash
    ) public {
        StreamPrimarySaleFloorCall.record(c, r);
        _emitSettlement(c, r, paymentAdapter, expectedPolicyHash);
    }

    function emitSupplementalSettlement(
        StreamNativeSupplementalTypes.NativeSupplementalCandidate memory original,
        StreamNativeSupplementalTypes.NativeSupplementalResult memory supplemental,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory context,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory result
    ) public {
        StreamPrimarySaleFloorCall.supplemental(original, supplemental);
        _emitSettlement(context, result, address(0), supplemental.originalExpectedPrimaryPolicyHash);
    }

    function _emitSettlement(
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory r,
        address paymentAdapter,
        bytes32 expectedPolicyHash
    ) private {
        emit PrimaryRevenueSettled(
            r.settlementKey,
            _CLASS,
            r.profileId,
            1,
            r.wallet,
            r.asset,
            c.sale.payer,
            r.amount,
            keccak256(abi.encode(c.sale)),
            expectedPolicyHash != c.sale.expectedPrimaryPolicyHash,
            c.rights.templateId == 0 ? 1 : 2
        );
        _emitContext(c, r);
        emit PrimaryRevenueSettlementPolicy(
            r.settlementKey,
            _CLASS,
            r.profileId,
            1,
            expectedPolicyHash,
            c.sale.expectedPrimaryPolicyHash,
            c.rights.assignmentHash,
            c.rights.templateId
        );
        emit PrimaryRevenueExecutionBound(
            r.settlementKey,
            c.saleAdapter,
            r.executionId,
            1,
            c.executor,
            paymentAdapter,
            r.candidateCommitment,
            c.currentPolicyHash,
            c.boundPolicyHash
        );
    }

    function _emitContext(
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
        StreamPrimarySettlementTypes.PrimarySettlementResult memory r
    ) private {
        ContextEventData memory context;
        context.schemaVersion = 1;
        context.settlementCaller = c.saleAdapter;
        context.settlementId = c.sale.settlementId;
        context.policyMode = c.sale.policyMode;
        context.collectionId = c.sale.collectionId;
        context.tokenId = c.sale.tokenId;
        context.operationRoot = c.operationIdentityCommitment;
        context.operationId = c.operationId;
        context.saleNonce = c.sale.saleNonce;
        context.poster = c.sale.poster;
        context.beneficiary = c.sale.beneficiary;
        context.templateId = c.rights.templateId;
        // A static tuple is the exact twelve nonindexed ABI words. Explicit LOG4 avoids
        // the legacy compiler's stack limit without changing the normative event layout.
        bytes memory data = abi.encode(context);
        bytes32 topic = _CONTEXT_EVENT;
        bytes32 key = r.settlementKey;
        bytes32 profile = r.profileId;
        bytes32 revenueClass = _CLASS;
        assembly ("memory-safe") {
            log4(add(data, 32), mload(data), topic, key, revenueClass, profile)
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/revenue/StreamPrimarySettlementTypes.sol";

/// @notice Exact domain-separated, abi.encode-only universal settlement preimages.
library StreamPrimarySettlementHash {
    bytes32 internal constant CANDIDATE = keccak256("6529STREAM_ERC20_SETTLEMENT_CANDIDATE_V2");
    bytes32 internal constant KEY = keccak256("6529STREAM_PRIMARY_SETTLEMENT_KEY_V2");
    bytes32 internal constant EXECUTION = keccak256("6529STREAM_ERC20_SALE_EXECUTION_V1");

    function candidateCommitment(
        address paymentAdapter,
        address recorder,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory candidate
    ) internal view returns (bytes32) {
        return keccak256(abi.encode(CANDIDATE, block.chainid, paymentAdapter, recorder, candidate));
    }

    /// @dev One official entry per exact sale execution, independent of alternative asset,
    ///      policy, payer or destination fields. Such alternatives cannot reopen a consumed key.
    function settlementKey(address recorder, address saleAdapter, bytes32 executionIdentity)
        internal
        view
        returns (bytes32)
    {
        return keccak256(abi.encode(KEY, block.chainid, recorder, saleAdapter, executionIdentity));
    }

    function executionId(StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                EXECUTION,
                block.chainid,
                c.saleAdapter,
                c.sale.settlementId,
                c.sale.payer,
                c.executor,
                c.executionBinding.executionNonce,
                c.executionBinding.authorityMode,
                c.executionBinding.saleAuthorizationDigest,
                c.currentPolicyHash,
                c.boundPolicyHash,
                c.operationIdentityCommitment
            )
        );
    }
}

