pragma solidity ^0.8.19;
import "./StreamNativeSettlementHash.sol";
import "./StreamPrimarySettlementHash.sol";
import "./StreamSettlementAdmission.sol";
import "../../interfaces/stream/revenue/IStreamPrimarySaleSettlement.sol";
import "../../interfaces/stream/revenue/IStreamNativePublicSaleBinding.sol";
import "../../interfaces/stream/revenue/IStreamERC20PublicSaleBinding.sol";

/// @notice Compiler-linked field and exact immutable reads for existing recorder entries.
/// @dev The recorder preserves surrounding admission/replay/funding order and supplies its own pins.
library StreamPrimarySettlementValidation {
    struct Bindings {
        address core;
        address registry;
        address resolver;
        address escrow;
    }
    bytes32 private constant _CLASS = keccak256("PRIMARY_SALE");
    error SettlementReadFailed(address target, bytes4 selector);

    function nativeFields(
        Bindings memory x,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) public view {
        if (
            msg.sender != c.saleAdapter || c.saleAdapter == address(0) || c.executor == address(0)
                || c.sale.settlementId == 0 || c.sale.revenueClass != _CLASS
                || c.sale.policyMode != 0 || c.sale.collectionId == 0 || c.sale.tokenId != 0
                || c.sale.saleNonce == 0 || c.sale.payer == address(0)
                || c.sale.payer == address(this) || c.sale.payer == c.saleAdapter
                || c.sale.payer == c.rights.wallet || c.sale.payer == x.escrow
                || c.sale.payer != c.executor || c.sale.beneficiary == address(0)
                || c.sale.amount == 0 || msg.value != c.sale.amount
                || c.sale.expectedPrimaryPolicyHash == 0 || c.orchestrationOrder != 1
                || c.executionBinding.authorityMode != 1 || c.executionBinding.executionNonce == 0
                || c.executionBinding.saleAuthorizationDigest == 0
                || c.operationIdentityCommitment == 0 || c.operationId == 0
                || c.currentPolicyHash == 0 || c.boundPolicyHash == 0 || c.saleExecutionHash == 0
                || c.executionBinding.executionId != StreamNativeSettlementHash.executionId(c)
        ) {
            revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        }
    }

    function nativePublicFields(
        Bindings memory x,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) public view {
        if (
            msg.sender != c.saleAdapter || c.saleAdapter == address(0) || c.executor == address(0)
                || c.sale.settlementId == 0 || c.sale.revenueClass != _CLASS
                || c.sale.policyMode != 0 || c.sale.collectionId == 0 || c.sale.tokenId != 0
                || c.sale.saleNonce == 0 || c.sale.payer == address(0)
                || c.sale.payer == address(this) || c.sale.payer == c.saleAdapter
                || c.sale.payer == c.rights.wallet || c.sale.payer == x.escrow
                || c.sale.payer != c.executor || c.sale.beneficiary == address(0)
                || c.sale.amount == 0 || msg.value != c.sale.amount
                || c.sale.expectedPrimaryPolicyHash == 0 || c.orchestrationOrder != 1
                || c.executionBinding.authorityMode != 2 || c.executionBinding.executionNonce == 0
                || c.executionBinding.saleAuthorizationDigest != 0
                || c.operationIdentityCommitment == 0 || c.operationId == 0
                || c.currentPolicyHash == 0 || c.boundPolicyHash == 0 || c.saleExecutionHash == 0
                || c.executionBinding.executionId != StreamNativeSettlementHash.executionId(c)
        ) {
            revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        }
    }

    /// @notice Authenticate only the caller's exact public record and active candidate.
    /// @dev The native tuple has no phase/config fields; the full active commitment authenticates
    /// the candidate, while the immutable sale record supplies its nonzero phase/config binding.
    function nativePublicBindings(
        Bindings memory x,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) public view returns (bytes32 recordHash) {
        nativeBindings(x, c);
        bytes memory data = abi.encodeCall(
            IStreamNativePublicSaleBinding.publicNativeSaleBinding, (c.sale.settlementId)
        );
        uint256[4] memory words;
        address adapter = c.saleAdapter;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), adapter, add(data, 32), mload(data), words, 128)
            size := returndatasize()
        }
        if (!ok || size != 128) revert SettlementReadFailed(adapter, bytes4(data));
        if (
            words[0] != c.sale.collectionId || words[1] == 0 || words[2] == 0 || words[3] != 2
                || bytes32(
                        _read(
                            adapter,
                            abi.encodeCall(
                                IStreamNativePublicSaleBinding.activePublicNativeCandidate,
                                (c.executionBinding.executionId)
                            ),
                            gasleft()
                        )
                    ) != StreamNativeSettlementHash.candidateCommitment(address(this), c)
        ) revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        return keccak256(abi.encode(words));
    }

    function nativeBindings(
        Bindings memory x,
        StreamNativeSettlementTypes.NativeSettlementCandidate memory c
    ) public view {
        if (
            _read(c.saleAdapter, abi.encodeWithSignature("primarySaleSettlement()"), gasleft())
                    != uint256(uint160(address(this)))
                || _read(c.saleAdapter, abi.encodeWithSignature("core()"), gasleft())
                    != uint256(uint160(x.core))
                || _read(c.saleAdapter, abi.encodeWithSignature("moduleRegistry()"), gasleft())
                    != uint256(uint160(x.registry))
                || _read(c.saleAdapter, abi.encodeWithSignature("revenueResolver()"), gasleft())
                    != uint256(uint160(x.resolver))
                || _read(c.saleAdapter, abi.encodeWithSignature("mintManager()"), gasleft())
                    != uint256(uint160(c.mintManager))
                || !StreamSettlementAdmission.isContract(c.mintManager)
                || _read(c.mintManager, abi.encodeWithSignature("core()"), gasleft())
                    != uint256(uint160(x.core))
                || _read(c.mintManager, abi.encodeWithSignature("moduleRegistry()"), gasleft())
                    != uint256(uint160(x.registry))
        ) {
            revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        }
    }

    function erc20Fields(
        Bindings memory x,
        address paymentAdapter,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) public view {
        if (
            msg.sender != c.saleAdapter || c.saleAdapter == address(0) || c.executor == address(0)
                || c.sale.settlementId == 0 || c.sale.revenueClass != _CLASS
                || c.sale.policyMode != 0 || c.sale.collectionId == 0 || c.sale.tokenId != 0
                || c.sale.saleNonce == 0 || c.sale.payer == address(0)
                || c.sale.payer == address(this) || c.sale.payer == paymentAdapter
                || c.sale.payer == c.rights.wallet || c.sale.payer == x.escrow
                || c.sale.beneficiary == address(0) || c.sale.amount == 0
                || c.sale.expectedPrimaryPolicyHash == 0 || c.orchestrationOrder != 1
                || c.executionBinding.authorityMode != 1 || c.executionBinding.executionNonce == 0
                || c.executionBinding.saleAuthorizationDigest == 0
                || c.operationIdentityCommitment == 0 || c.operationId == 0
                || c.currentPolicyHash == 0 || c.boundPolicyHash == 0 || c.saleExecutionHash == 0
                || c.executionBinding.executionId != StreamPrimarySettlementHash.executionId(c)
        ) {
            revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        }
    }

    function erc20PublicFields(
        Bindings memory x,
        address paymentAdapter,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) public view {
        if (
            msg.sender != c.saleAdapter || c.saleAdapter == address(0) || c.executor == address(0)
                || c.sale.settlementId == 0 || c.sale.revenueClass != _CLASS
                || c.sale.policyMode != 0 || c.sale.collectionId == 0 || c.sale.tokenId != 0
                || c.sale.saleNonce == 0 || c.sale.payer == address(0)
                || c.sale.payer == address(this) || c.sale.payer == paymentAdapter
                || c.sale.payer == c.rights.wallet || c.sale.payer == x.escrow
                || c.sale.beneficiary == address(0) || c.sale.amount == 0
                || c.sale.expectedPrimaryPolicyHash == 0 || c.orchestrationOrder != 1
                || c.executionBinding.authorityMode != 2 || c.executionBinding.executionNonce == 0
                || c.executionBinding.saleAuthorizationDigest != 0
                || c.operationIdentityCommitment == 0 || c.operationId == 0
                || c.currentPolicyHash == 0 || c.boundPolicyHash == 0 || c.saleExecutionHash == 0
                || c.executionBinding.executionId != StreamPrimarySettlementHash.executionId(c)
        ) {
            revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        }
    }

    /// @dev The original token tuple has no phase/config fields. The exact active candidate
    /// authenticates the complete payment context; the immutable record supplies its phase/config.
    function erc20PublicBindings(
        Bindings memory x,
        address paymentAdapter,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) public view returns (bytes32 recordHash) {
        erc20Bindings(x, paymentAdapter, c);
        bytes memory data = abi.encodeCall(
            IStreamERC20PublicSaleBinding.publicERC20SaleBinding, (c.sale.settlementId)
        );
        uint256[4] memory words;
        address adapter = c.saleAdapter;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), adapter, add(data, 32), mload(data), words, 128)
            size := returndatasize()
        }
        if (!ok || size != 128) revert SettlementReadFailed(adapter, bytes4(data));
        if (
            words[0] != c.sale.collectionId || words[1] == 0 || words[2] == 0 || words[3] != 2
                || bytes32(
                        _read(
                            adapter,
                            abi.encodeCall(
                                IStreamERC20PublicSaleBinding.activePublicERC20Candidate,
                                (c.executionBinding.executionId)
                            ),
                            gasleft()
                        )
                    )
                    != StreamPrimarySettlementHash.candidateCommitment(
                        paymentAdapter, address(this), c
                    )
        ) revert IStreamPrimarySaleSettlement.InvalidPrimarySale();
        return keccak256(abi.encode(words));
    }

    function erc20Bindings(
        Bindings memory x,
        address paymentAdapter,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) public view {
        if (
            _read(paymentAdapter, abi.encodeWithSignature("primarySaleSettlement()"), gasleft())
                    != uint256(uint160(address(this)))
                || _read(paymentAdapter, abi.encodeWithSignature("core()"), gasleft())
                    != uint256(uint160(x.core))
                || _read(paymentAdapter, abi.encodeWithSignature("moduleRegistry()"), gasleft())
                    != uint256(uint160(x.registry))
                || _read(paymentAdapter, abi.encodeWithSignature("revenueResolver()"), gasleft())
                    != uint256(uint160(x.resolver))
                || _read(
                        c.saleAdapter, abi.encodeWithSignature("primarySaleSettlement()"), gasleft()
                    ) != uint256(uint160(address(this)))
                || _read(c.saleAdapter, abi.encodeWithSignature("core()"), gasleft())
                    != uint256(uint160(x.core))
                || _read(c.saleAdapter, abi.encodeWithSignature("mintManager()"), gasleft())
                    != uint256(uint160(c.mintManager))
        ) {
            revert IStreamPrimarySaleSettlement.PrimarySettlementPaymentBindingInvalid(paymentAdapter);
        }
    }

    function _read(address target, bytes memory data, uint256 cap)
        private
        view
        returns (uint256 word)
    {
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(data, 32), mload(data), 0, 32)
            size := returndatasize()
            word := mload(0)
        }
        if (!ok || size != 32) revert SettlementReadFailed(target, bytes4(data));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { IStreamRevenueResolver } from "../../interfaces/stream/revenue/IStreamRevenueResolver.sol";
import { IStreamSplitWallet } from "../../interfaces/stream/revenue/IStreamSplitWallet.sol";
import {
    IStreamArtistBeneficiaryFacts
} from "../../interfaces/stream/artist/IStreamArtistBeneficiaryFacts.sol";

/// @notice Existing concrete-profile body at a fixed compiler-linked boundary.
/// @dev Host supplies only its pinned registry/live cap and original sale context.
library StreamPrimaryTemplateMaterialization {
    bytes32 private constant ACCOUNT_SOURCE_COLLECTION_ARTIST = keccak256("COLLECTION_ARTIST");
    bytes32 private constant ACCOUNT_SOURCE_SALE_POSTER = keccak256("SALE_POSTER");
    bytes32 private constant _MATERIALIZED_PROFILE_METADATA_DOMAIN =
        keccak256("6529STREAM_MATERIALIZED_PRIMARY_PROFILE_METADATA_V1");

    struct Context {
        address artistRegistry;
        uint256 cap;
        uint256 collectionId;
        address salePoster;
        bytes32 artistId;
        address payout;
        bytes32 designation;
    }
    error MissingArtistMaterializationContext();
    error UnsupportedAccountSource(bytes32 source);
    error InvalidMaterializedAccount(bytes32 source);
    error InsufficientArtistBeneficiaryGas(uint256 cap, uint256 available);
    error UnresolvableArtistBeneficiary(uint256 collectionId);

    function legacy(
        IStreamRevenueResolver.PrimaryTemplateEntry[] memory entries,
        bytes32 templateId,
        Context memory context
    )
        public
        view
        returns (
            IStreamSplitWallet.SplitEntry[] memory concreteEntries,
            bytes32 entriesHash,
            bytes32 metadataURIHash,
            Context memory
        )
    {
        // Resolve once; all entries in this materialization share the same current witness.
        for (uint256 i; i < entries.length; ++i) {
            if (entries[i].accountSource == ACCOUNT_SOURCE_COLLECTION_ARTIST) {
                if (context.collectionId == 0) revert MissingArtistMaterializationContext();
                (context.artistId, context.payout, context.designation) =
                    _artistBeneficiary(context.collectionId, context.artistRegistry, context.cap);
                break;
            }
        }
        concreteEntries = new IStreamSplitWallet.SplitEntry[](entries.length);
        for (uint256 i; i < entries.length; ++i) {
            IStreamRevenueResolver.PrimaryTemplateEntry memory entry = entries[i];
            address account = entry.account;
            if (account == address(0)) {
                if (entry.accountSource == ACCOUNT_SOURCE_COLLECTION_ARTIST) {
                    account = context.payout;
                } else if (entry.accountSource == ACCOUNT_SOURCE_SALE_POSTER) {
                    account = context.salePoster;
                } else {
                    revert UnsupportedAccountSource(entry.accountSource);
                }
                if (account == address(0)) revert InvalidMaterializedAccount(entry.accountSource);
            }
            concreteEntries[i] =
                IStreamSplitWallet.SplitEntry(account, entry.sharePpm, entry.labelId);
        }
        concreteEntries = _canonicalizeConcreteEntries(concreteEntries);
        entriesHash = keccak256(abi.encode(concreteEntries));
        metadataURIHash = keccak256(
            abi.encode(
                _MATERIALIZED_PROFILE_METADATA_DOMAIN,
                uint256(block.chainid),
                address(this),
                templateId,
                entriesHash
            )
        );
        return (concreteEntries, entriesHash, metadataURIHash, context);
    }

    function canonical(IStreamSplitWallet.SplitEntry[] memory entries)
        public
        pure
        returns (IStreamSplitWallet.SplitEntry[] memory)
    {
        return _canonicalizeConcreteEntries(entries);
    }

    function _artistBeneficiary(uint256 collectionId, address artistRegistry, uint256 cap)
        private
        view
        returns (bytes32 artistId, address payout, bytes32 designation)
    {
        bytes memory input = abi.encodeCall(
            IStreamArtistBeneficiaryFacts.collectionArtistBeneficiary, (collectionId)
        );
        // Covers EIP-150 plus cold-account/call setup; never silently underforward the live cap.
        uint256 available = gasleft();
        if (cap > type(uint64).max || available < cap + (cap + 62) / 63 + 12_000) {
            revert InsufficientArtistBeneficiaryGas(cap, available);
        }
        bool ok;
        uint256 size;
        uint256 payoutWord;
        address target = artistRegistry;
        assembly ("memory-safe") {
            let output := mload(0x40)
            ok := staticcall(cap, target, add(input, 32), mload(input), output, 96)
            size := returndatasize()
            artistId := mload(output)
            payoutWord := mload(add(output, 32))
            designation := mload(add(output, 64))
        }
        if (
            !ok || size != 96 || artistId == bytes32(0) || designation == bytes32(0)
                || payoutWord == 0 || payoutWord > type(uint160).max
        ) {
            revert UnresolvableArtistBeneficiary(collectionId);
        }
        // The exact ABI-word check above rejects every nonzero upper address bit.
        // forge-lint: disable-next-line(unsafe-typecast)
        payout = address(uint160(payoutWord));
    }

    function _canonicalizeConcreteEntries(IStreamSplitWallet.SplitEntry[] memory entries)
        private
        pure
        returns (IStreamSplitWallet.SplitEntry[] memory canonicalEntries)
    {
        _sortSplitEntries(entries);
        uint256 uniqueCount = 0;
        for (uint256 i = 0; i < entries.length; i++) {
            if (
                i == 0 || entries[i].account != entries[i - 1].account
                    || entries[i].labelId != entries[i - 1].labelId
            ) {
                uniqueCount++;
            }
        }
        canonicalEntries = new IStreamSplitWallet.SplitEntry[](uniqueCount);
        uint256 cursor = 0;
        for (uint256 i = 0; i < entries.length; i++) {
            if (
                i == 0 || entries[i].account != entries[i - 1].account
                    || entries[i].labelId != entries[i - 1].labelId
            ) {
                if (i != 0) {
                    cursor++;
                }
                canonicalEntries[cursor] = entries[i];
            } else {
                canonicalEntries[cursor].sharePpm += entries[i].sharePpm;
            }
        }
    }

    function _sortSplitEntries(IStreamSplitWallet.SplitEntry[] memory entries) private pure {
        for (uint256 i = 1; i < entries.length; i++) {
            IStreamSplitWallet.SplitEntry memory current = entries[i];
            uint256 j = i;
            while (j > 0 && _splitEntryLess(current, entries[j - 1])) {
                entries[j] = entries[j - 1];
                j--;
            }
            entries[j] = current;
        }
    }

    function _splitEntryLess(
        IStreamSplitWallet.SplitEntry memory left,
        IStreamSplitWallet.SplitEntry memory right
    ) private pure returns (bool) {
        if (left.account != right.account) {
            return uint160(left.account) < uint160(right.account);
        }
        if (left.labelId != right.labelId) {
            return uint256(left.labelId) < uint256(right.labelId);
        }
        return left.sharePpm < right.sharePpm;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    IStreamRevenueResolver as R
} from "../../interfaces/stream/revenue/IStreamRevenueResolver.sol";

/// @notice Immutable template grammar and canonicalization in a fixed compiler-linked boundary.
/// @dev No authority, payout resolution, storage mutation or caller-selected delegate exists here.
library StreamPrimaryTemplateRules {
    uint16 private constant MAX_TEMPLATE_ENTRIES = 64;
    uint16 private constant MAX_DYNAMIC_ACCOUNT_SOURCES = 8;
    uint32 private constant SHARE_DENOMINATOR_PPM = 1_000_000;
    bytes32 private constant ACCOUNT_SOURCE_SALE_POSTER = keccak256("SALE_POSTER");
    bytes32 private constant ACCOUNT_SOURCE_COLLECTION_ARTIST = keccak256("COLLECTION_ARTIST");
    bytes32 private constant ARTIST_LABEL = keccak256("artist");

    error InvalidPrimaryTemplateEntry(uint256 index);
    error InvalidPrimaryTemplateTotal(uint256 totalShare);
    error UnsupportedAccountSource(bytes32 accountSource);
    error UnsupportedArtistPrimaryTemplate(bytes32 templateId);

    /// @dev Existing initial facts use 500000; prospective positive-share facts use 1.
    function artistShare(
        R.PrimaryTemplateEntry[] memory entries,
        bytes32 templateId,
        uint32 minimum
    ) public pure returns (uint32 share) {
        for (uint256 i; i < entries.length; ++i) {
            R.PrimaryTemplateEntry memory entry = entries[i];
            if (
                entry.accountSource == ACCOUNT_SOURCE_COLLECTION_ARTIST
                    && entry.account == address(0) && entry.labelId == ARTIST_LABEL
            ) {
                share += entry.sharePpm;
            } else if (
                entry.account == address(0) || entry.accountSource != bytes32(0)
                    || entry.labelId == ARTIST_LABEL
            ) {
                revert UnsupportedArtistPrimaryTemplate(templateId);
            }
        }
        if (share < minimum) revert UnsupportedArtistPrimaryTemplate(templateId);
    }

    function canonicalize(R.PrimaryTemplateEntry[] calldata entries)
        public
        pure
        returns (R.PrimaryTemplateEntry[] memory canonicalEntries, bytes32 entriesHash)
    {
        uint256 length = entries.length;
        if (length == 0 || length > MAX_TEMPLATE_ENTRIES) {
            revert InvalidPrimaryTemplateEntry(length);
        }
        canonicalEntries = new R.PrimaryTemplateEntry[](length);
        for (uint256 i = 0; i < length; i++) {
            canonicalEntries[i] = entries[i];
        }
        _sortTemplateEntries(canonicalEntries);

        uint256 totalShare = 0;
        uint256 dynamicSourceCount = 0;
        bytes32[MAX_DYNAMIC_ACCOUNT_SOURCES] memory dynamicSources;
        for (uint256 i = 0; i < length; i++) {
            R.PrimaryTemplateEntry memory entry = canonicalEntries[i];
            bool hasAccount = entry.account != address(0);
            bool hasSource = entry.accountSource != bytes32(0);
            if (hasAccount == hasSource || entry.sharePpm == 0) {
                revert InvalidPrimaryTemplateEntry(i);
            }
            if (i != 0 && _sameTemplateIdentity(canonicalEntries[i - 1], entry)) {
                revert InvalidPrimaryTemplateEntry(i);
            }
            if (hasSource) {
                if (
                    entry.accountSource != ACCOUNT_SOURCE_SALE_POSTER
                        && entry.accountSource != ACCOUNT_SOURCE_COLLECTION_ARTIST
                ) {
                    revert UnsupportedAccountSource(entry.accountSource);
                }
                if (
                    entry.accountSource == ACCOUNT_SOURCE_COLLECTION_ARTIST
                        && entry.labelId != ARTIST_LABEL
                ) {
                    revert InvalidPrimaryTemplateEntry(i);
                }
                bool seen = false;
                for (uint256 j = 0; j < dynamicSourceCount; j++) {
                    if (dynamicSources[j] == entry.accountSource) {
                        seen = true;
                        break;
                    }
                }
                if (!seen) {
                    if (dynamicSourceCount == MAX_DYNAMIC_ACCOUNT_SOURCES) {
                        revert InvalidPrimaryTemplateEntry(i);
                    }
                    dynamicSources[dynamicSourceCount] = entry.accountSource;
                    dynamicSourceCount++;
                }
            }
            totalShare += entry.sharePpm;
        }
        if (totalShare != SHARE_DENOMINATOR_PPM) {
            revert InvalidPrimaryTemplateTotal(totalShare);
        }
        entriesHash = keccak256(abi.encode(canonicalEntries));
    }

    function _sortTemplateEntries(R.PrimaryTemplateEntry[] memory entries) private pure {
        for (uint256 i = 1; i < entries.length; i++) {
            R.PrimaryTemplateEntry memory current = entries[i];
            uint256 j = i;
            while (j > 0 && _templateEntryLess(current, entries[j - 1])) {
                entries[j] = entries[j - 1];
                j--;
            }
            entries[j] = current;
        }
    }

    function _templateEntryLess(
        R.PrimaryTemplateEntry memory left,
        R.PrimaryTemplateEntry memory right
    ) private pure returns (bool) {
        if (left.account != right.account) {
            return uint160(left.account) < uint160(right.account);
        }
        if (left.accountSource != right.accountSource) {
            return uint256(left.accountSource) < uint256(right.accountSource);
        }
        if (left.labelId != right.labelId) {
            return uint256(left.labelId) < uint256(right.labelId);
        }
        return left.sharePpm < right.sharePpm;
    }

    function _sameTemplateIdentity(
        R.PrimaryTemplateEntry memory left,
        R.PrimaryTemplateEntry memory right
    ) private pure returns (bool) {
        return left.account == right.account && left.accountSource == right.accountSource
            && left.labelId == right.labelId;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamPrimaryResolverState as S } from "./StreamPrimaryResolverState.sol";
import {
    IStreamRevenueResolver as R
} from "../../interfaces/stream/revenue/IStreamRevenueResolver.sol";
import {
    IStreamDynamicPrimaryTemplates as D
} from "../../interfaces/stream/revenue/IStreamDynamicPrimaryTemplates.sol";
import { IStreamSplitWallet } from "../../interfaces/stream/revenue/IStreamSplitWallet.sol";
import { IStreamSplitFactory } from "../../interfaces/stream/revenue/IStreamSplitFactory.sol";
import {
    IStreamGasParameterHost
} from "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import { StreamPrimaryTemplateRules } from "./StreamPrimaryTemplateRules.sol";
import {
    StreamDynamicPrimaryTemplateRules as DynamicRules
} from "./StreamDynamicPrimaryTemplateRules.sol";
import {
    StreamDynamicPrimaryBeneficiaries as DynamicBeneficiaries
} from "./StreamDynamicPrimaryBeneficiaries.sol";
import {
    StreamPrimaryTemplateMaterialization as Materialization
} from "./StreamPrimaryTemplateMaterialization.sol";

/// @notice Fixed registration and concrete template cache worker in the actual Resolver context.
/// @dev Host guards run before entry. Context contains only immutable pins; cap reads remain live.
library StreamPrimaryTemplateRuntime {
    struct Context {
        IStreamSplitFactory factory;
        address artist;
    }

    struct MaterializationContext {
        uint256 collectionId;
        address salePoster;
        bool deploy;
        bytes32 artistId;
        address payout;
        bytes32 designation;
        bytes32 beneficiaryHash;
        bool dynamicTemplate;
    }

    uint16 private constant SCHEMA_VERSION = 1;
    uint16 private constant TEMPLATE_VERSION = 1;
    bytes32 private constant _PRIMARY_TEMPLATE_DOMAIN = keccak256("6529STREAM_PRIMARY_TEMPLATE_V1");
    bytes32 private constant _MATERIALIZED_PROFILE_METADATA_DOMAIN =
        keccak256("6529STREAM_MATERIALIZED_PRIMARY_PROFILE_METADATA_V1");
    bytes32 private constant ACCOUNT_SOURCE_COLLECTION_ARTIST = keccak256("COLLECTION_ARTIST");
    bytes32 private constant ARTIST_BENEFICIARY_READ_GAS =
        keccak256("6529STREAM_GGP_ARTIST_BENEFICIARY_READ_GAS");
    event PrimaryTemplateCreated(
        bytes32 indexed templateId,
        bytes32 indexed entriesHash,
        bytes32 indexed metadataURIHash,
        uint16 schemaVersion,
        uint16 templateVersion
    );
    event PrimaryTemplateEntryRecorded(
        bytes32 indexed templateId,
        uint16 indexed index,
        address indexed account,
        bytes32 accountSource,
        uint32 sharePpm,
        bytes32 labelId
    );
    event PrimaryTemplateMaterialized(
        bytes32 indexed templateId,
        bytes32 indexed profileId,
        address indexed wallet,
        bytes32 entriesHash,
        bytes32 metadataURIHash,
        address salePoster
    );
    event CollectionTemplateMaterialized(
        bytes32 indexed templateId,
        bytes32 indexed profileId,
        uint256 indexed collectionId,
        uint16 schemaVersion,
        bytes32 artistId,
        address payoutAccount,
        bytes32 designationRecordHash,
        address wallet,
        bytes32 entriesHash,
        bool walletDeployed
    );
    event DynamicCollectionTemplateMaterialized(
        uint16 schemaVersion,
        bytes32 indexed templateId,
        bytes32 indexed profileId,
        uint256 indexed collectionId,
        bytes32 beneficiaryHash,
        address salePoster
    );

    function registerTemplate(
        mapping(bytes32 => S.PrimaryTemplate) storage templates,
        R.PrimaryTemplateEntry[] calldata entries,
        bytes32 metadataURIHash,
        D.CollaboratorReference[] memory references,
        bool dynamicTemplate
    ) public returns (bytes32) {
        R.PrimaryTemplateEntry[] memory canonicalEntries;
        bytes32 entriesHash;
        if (dynamicTemplate) {
            (canonicalEntries, entriesHash) = DynamicRules.canonicalize(entries, references);
        } else {
            (canonicalEntries, entriesHash) = StreamPrimaryTemplateRules.canonicalize(entries);
        }
        return _registerTemplate(templates, canonicalEntries, entriesHash, metadataURIHash);
    }

    function isDynamic(S.PrimaryTemplate storage template) public view returns (bool) {
        return DynamicRules.isDynamic(template.entries);
    }

    function artistShare(S.PrimaryTemplate storage template, bytes32 templateId, uint32 minimum)
        public
        view
        returns (uint32)
    {
        return StreamPrimaryTemplateRules.artistShare(template.entries, templateId, minimum);
    }

    function _registerTemplate(
        mapping(bytes32 => S.PrimaryTemplate) storage templates,
        R.PrimaryTemplateEntry[] memory canonicalEntries,
        bytes32 entriesHash,
        bytes32 metadataURIHash
    ) private returns (bytes32 templateId) {
        templateId = keccak256(
            abi.encode(
                _PRIMARY_TEMPLATE_DOMAIN,
                uint256(block.chainid),
                address(this),
                SCHEMA_VERSION,
                TEMPLATE_VERSION,
                entriesHash,
                metadataURIHash
            )
        );

        S.PrimaryTemplate storage template = templates[templateId];
        if (template.exists) {
            return templateId;
        }
        template.exists = true;
        template.entriesHash = entriesHash;
        template.metadataURIHash = metadataURIHash;
        for (uint256 i = 0; i < canonicalEntries.length; i++) {
            template.entries.push(canonicalEntries[i]);
        }

        emit PrimaryTemplateCreated(
            templateId, entriesHash, metadataURIHash, SCHEMA_VERSION, TEMPLATE_VERSION
        );
        for (uint256 i = 0; i < canonicalEntries.length; i++) {
            R.PrimaryTemplateEntry memory entry = canonicalEntries[i];
            emit PrimaryTemplateEntryRecorded(
                templateId,
                // Safe because MAX_TEMPLATE_ENTRIES is 64.
                // forge-lint: disable-next-line(unsafe-typecast)
                uint16(i),
                entry.account,
                entry.accountSource,
                entry.sharePpm,
                entry.labelId
            );
        }
    }

    function dynamicFacts(
        mapping(bytes32 => S.PrimaryTemplate) storage templates,
        Context memory x,
        uint256 collectionId,
        bytes32 templateId
    )
        public
        view
        returns (
            bytes32 entriesHash,
            bytes32 metadataURIHash,
            uint32 artistSharePpm,
            bytes32 beneficiaryHash
        )
    {
        S.PrimaryTemplate storage t = templates[templateId];
        if (!t.exists) revert R.UnknownPrimaryTemplate(templateId);
        (artistSharePpm, beneficiaryHash,) = DynamicBeneficiaries.facts(
            t.entries,
            DynamicBeneficiaries.Context(
                x.artist,
                collectionId,
                IStreamGasParameterHost(address(this)).gasParameter(ARTIST_BENEFICIARY_READ_GAS)
            )
        );
        return (t.entriesHash, t.metadataURIHash, artistSharePpm, beneficiaryHash);
    }

    function materialize(
        mapping(bytes32 => S.PrimaryTemplate) storage templates,
        Context memory x,
        bytes32 templateId,
        MaterializationContext memory context
    )
        public
        returns (bytes32 profileId, address wallet, bytes32 entriesHash, bytes32 beneficiaryHash)
    {
        IStreamSplitWallet.SplitEntry[] memory concreteEntries;
        bytes32 metadataURIHash;
        (concreteEntries, entriesHash, metadataURIHash) =
            _concreteProfile(templates, x, templateId, context);
        (profileId, wallet) = x.factory.registerProfile(concreteEntries, metadataURIHash);
        // Even the deferred path must not produce a usable receipt for an occupied wrong-code address.
        if (wallet.code.length != 0 && !x.factory.splitWalletExists(profileId)) {
            revert R.UnverifiedSplitProfile(profileId);
        }
        if (context.deploy) wallet = x.factory.deployWallet(profileId);
        emit PrimaryTemplateMaterialized(
            templateId, profileId, wallet, entriesHash, metadataURIHash, context.salePoster
        );
        if (context.collectionId != 0) {
            _emitCollectionMaterialization(x, templateId, profileId, wallet, entriesHash, context);
        }
        if (context.beneficiaryHash != 0) {
            emit DynamicCollectionTemplateMaterialized(
                SCHEMA_VERSION,
                templateId,
                profileId,
                context.collectionId,
                context.beneficiaryHash,
                context.salePoster
            );
        }

        beneficiaryHash = context.beneficiaryHash;
    }

    function preview(
        mapping(bytes32 => S.PrimaryTemplate) storage templates,
        Context memory x,
        bytes32 templateId,
        MaterializationContext memory context
    )
        public
        view
        returns (bytes32 profileId, address wallet, bytes32 entriesHash, bytes32 beneficiaryHash)
    {
        IStreamSplitWallet.SplitEntry[] memory entries;
        bytes32 metadata;
        (entries, entriesHash, metadata) = _concreteProfile(templates, x, templateId, context);
        profileId = x.factory.profileIdFor(entries, metadata);
        wallet = x.factory.walletFor(profileId);
        if (wallet.code.length != 0 && !x.factory.splitWalletExists(profileId)) {
            revert R.UnverifiedSplitProfile(profileId);
        }
        return (profileId, wallet, entriesHash, context.beneficiaryHash);
    }

    function _concreteProfile(
        mapping(bytes32 => S.PrimaryTemplate) storage templates,
        Context memory x,
        bytes32 templateId,
        MaterializationContext memory context
    )
        private
        view
        returns (
            IStreamSplitWallet.SplitEntry[] memory concreteEntries,
            bytes32 entriesHash,
            bytes32 metadataURIHash
        )
    {
        S.PrimaryTemplate storage t = templates[templateId];
        if (!t.exists) revert R.UnknownPrimaryTemplate(templateId);
        if (context.dynamicTemplate) {
            DynamicBeneficiaries.Witness memory w;
            (concreteEntries, context.beneficiaryHash, w) = DynamicBeneficiaries.concrete(
                t.entries,
                DynamicBeneficiaries.Context(
                    x.artist,
                    context.collectionId,
                    IStreamGasParameterHost(address(this)).gasParameter(ARTIST_BENEFICIARY_READ_GAS)
                ),
                context.salePoster
            );
            context.artistId = w.artistId;
            context.payout = w.payout;
            context.designation = w.designation;
            concreteEntries = Materialization.canonical(concreteEntries);
            entriesHash = keccak256(abi.encode(concreteEntries));
            metadataURIHash = keccak256(
                abi.encode(
                    _MATERIALIZED_PROFILE_METADATA_DOMAIN,
                    uint256(block.chainid),
                    address(this),
                    templateId,
                    entriesHash
                )
            );
        } else {
            uint256 cap;
            for (uint256 i; i < t.entries.length; ++i) {
                if (t.entries[i].accountSource == ACCOUNT_SOURCE_COLLECTION_ARTIST) {
                    if (context.collectionId == 0) revert R.MissingArtistMaterializationContext();
                    cap = IStreamGasParameterHost(address(this))
                        .gasParameter(ARTIST_BENEFICIARY_READ_GAS);
                    break;
                }
            }
            Materialization.Context memory c = Materialization.Context(
                x.artist,
                cap,
                context.collectionId,
                context.salePoster,
                bytes32(0),
                address(0),
                bytes32(0)
            );
            (concreteEntries, entriesHash, metadataURIHash, c) =
                Materialization.legacy(t.entries, templateId, c);
            context.artistId = c.artistId;
            context.payout = c.payout;
            context.designation = c.designation;
        }
    }

    function _emitCollectionMaterialization(
        Context memory x,
        bytes32 templateId,
        bytes32 profileId,
        address wallet,
        bytes32 entriesHash,
        MaterializationContext memory context
    ) private {
        emit CollectionTemplateMaterialized(
            templateId,
            profileId,
            context.collectionId,
            SCHEMA_VERSION,
            context.artistId,
            context.payout,
            context.designation,
            wallet,
            entriesHash,
            x.factory.splitWalletExists(profileId)
        );
    }
}

