        uint256 collectionId,
        uint8 scope,
        uint256 scopeId,
        bytes32 profileHash,
        bytes32 policyHash,
        bool frozen
    ) external view override returns (StreamArtistOnboardingTypes.AssignmentFact memory fact) {
