// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/auctions/IStreamTokenProfileCustodyAuction.sol";
import "../../interfaces/stream/revenue/StreamNativeCustodySettlementTypes.sol";
import "../../interfaces/stream/revenue/StreamPrimarySettlementTypes.sol";
import "../../vendor/openzeppelin/IERC165.sol";

/// @notice New domains retain the full append-only activation; old custody preimages are unchanged.
library StreamTokenProfileCustodyHash {
    function digest(address house, StreamTokenProfileCustodyTypes.Authorization memory a)
        public
        view
        returns (bytes32)
    {
        bytes32 domain = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256("6529StreamTokenProfileCustodyAllowCurrent"),
                keccak256("1"),
                block.chainid,
                house
            )
        );
        return keccak256(
            abi.encodePacked(
                hex"1901",
                domain,
                keccak256(
                    abi.encode(
                        keccak256(
                            "TokenProfileCustodyActivation(bytes32 auctionId,bytes32 baseConfigHash,bytes32 originHash,uint256 tokenId,bytes32 assignmentHash,bytes32 primaryPolicyHash,uint8 primaryPolicyMode,address artist,bytes32 nonce,uint64 deadline)"
                        ),
                        a
                    )
                )
            )
        );
    }

    function configuration(address house, StreamTokenProfileCustodyTypes.Activation memory a)
        public
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_TOKEN_PROFILE_CUSTODY_ALLOW_CURRENT_CONFIG_V1"),
                block.chainid,
                house,
                a.authorization,
                a.authorizationDigest
            )
        );
    }

    function readOptional(address house, bytes32 id)
        public
        view
        returns (StreamTokenProfileCustodyTypes.Activation memory a)
    {
        if (IERC165(house).supportsInterface(type(IStreamTokenProfileCustodyAuction).interfaceId)) {
            return IStreamTokenProfileCustodyAuction(house).tokenProfileCustodyActivation(id);
        }
    }

    function requireLegacy(address house, bytes32 id) public view {
        if (readOptional(house, id).authorizationDigest != 0) {
            revert IStreamTokenProfileCustodyAuction.TokenProfileCustodyEntryRequired(id);
        }
    }

    function execution(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamTokenProfileCustodyTypes.Activation memory a
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_TOKEN_PROFILE_CUSTODY_EXECUTION_V1"),
                block.chainid,
                recorder,
                house,
                f,
                a
            )
        );
    }

    function facts(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamTokenProfileCustodyTypes.Activation memory a
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_TOKEN_PROFILE_CUSTODY_FACTS_V1"),
                block.chainid,
                recorder,
                house,
                f,
                a
            )
        );
    }

    function candidate(
        address recorder,
        address house,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamTokenProfileCustodyTypes.Activation memory a,
        StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_TOKEN_PROFILE_CUSTODY_CANDIDATE_V1"),
                block.chainid,
                recorder,
                house,
                f,
                a,
                c
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamTokenProfileCustodyValidation.sol";
import "../../interfaces/stream/revenue/IStreamTokenProfileCustodySettlement.sol";
import "./StreamNativePrimaryExecution.sol";
import "./StreamPrimarySettlementEmission.sol";
import "./StreamPrimarySettlementHash.sol";

/// @notice Official payment before custody delivery, with no mint or ledger operation.
library StreamTokenProfileCustodyRecording {
    struct Context {
        StreamNativeCustodyPrimaryAdmission.Context admission;
        bytes32 resolverHash;
        StreamNativePrimaryExecution.Context funding;
    }
    event TokenProfileCustodyRevenueRecorded(
        uint16 schemaVersion,
        bytes32 indexed settlementKey,
        bytes32 indexed saleKey,
        bytes32 indexed factsHash,
        StreamNativeCustodySettlementTypes.Facts facts,
        StreamTokenProfileCustodyTypes.Activation activation,
        StreamPrimarySettlementTypes.PrimarySettlementResult result
    );

    function execute(
        Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        mapping(bytes32 => bool) storage saleConsumed,
        mapping(bytes32 => bool) storage consumed,
        mapping(
            bytes32 => StreamPrimarySettlementTypes.PrimarySettlementResult
        ) storage results,
        mapping(bytes32 => bytes32) storage factsHashes,
        mapping(bytes32 => uint256) storage official,
        mapping(address => uint256) storage total,
        bytes32 id
    ) public returns (StreamPrimarySettlementTypes.PrimarySettlementResult memory r) {
        requireContext(x);
        (
            StreamNativeCustodySettlementTypes.Facts memory f,
            StreamTokenProfileCustodyTypes.Activation memory activation
        ) = StreamTokenProfileCustodyValidation.read(x.admission, pin, id);
        if (
            msg.value != f.auction.winner.amount
                || f.auction.winner.payer == address(x.funding.escrow)
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected
        ) = StreamTokenProfileCustodyValidation.derive(
            x.funding.rights, f, activation, msg.sender, address(this)
        );
        if (c.sale.payer == selected.wallet) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 saleKey = StreamPreparedNativeSettlementHash.saleKey(
            address(this), msg.sender, f.auction.saleId, f.auction.saleNonce
        );
        bytes32 key = StreamPrimarySettlementHash.settlementKey(
            address(this), msg.sender, c.executionBinding.executionId
        );
        if (saleConsumed[saleKey] || consumed[key]) {
            revert IStreamPrimarySaleSettlement.SettlementAlreadyConsumed(key);
        }
        saleConsumed[saleKey] = true;
        consumed[key] = true;
        bool escrowed = StreamNativePrimaryExecution.fund(
            x.funding, c.sale.collectionId, c.sale.amount, selected
        );
        requireContext(x);
        (
            StreamNativeCustodySettlementTypes.Facts memory after_,
            StreamTokenProfileCustodyTypes.Activation memory afterActivation
        ) = StreamTokenProfileCustodyValidation.read(x.admission, pin, id);
        (StreamPrimarySettlementTypes.ERC20SettlementCandidate memory afterCandidate,) = StreamTokenProfileCustodyValidation.derive(
            x.funding.rights, after_, afterActivation, msg.sender, address(this)
        );
        if (
            keccak256(abi.encode(f)) != keccak256(abi.encode(after_))
                || keccak256(abi.encode(activation)) != keccak256(abi.encode(afterActivation))
                || keccak256(abi.encode(c)) != keccak256(abi.encode(afterCandidate))
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
        bytes32 factsHash =
            StreamTokenProfileCustodyHash.facts(address(this), msg.sender, f, activation);
        r = StreamPrimarySettlementTypes.PrimarySettlementResult(
            StreamTokenProfileCustodyHash.candidate(address(this), msg.sender, f, activation, c),
            key,
            selected.profileId,
            selected.wallet,
            address(0),
            c.sale.amount,
            c.executor,
            c.executionBinding.executionId,
            escrowed,
            0,
            0,
            0
        );
        results[key] = r;
        factsHashes[key] = factsHash;
        official[
            keccak256(
                abi.encode(
                    keccak256("6529STREAM_OFFICIAL_PRIMARY_SETTLED_V1"),
                    keccak256("PRIMARY_SALE"),
                    selected.profileId,
                    selected.wallet,
                    address(0)
                )
            )
        ] += r.amount;
        total[address(0)] += r.amount;
        StreamPrimarySettlementEmission.emitSettlement(
            c, r, address(0), activation.authorization.primaryPolicyHash
        );
        emit TokenProfileCustodyRevenueRecorded(1, key, saleKey, factsHash, f, activation, r);
    }

    function requireContext(Context memory x) private view {
        StreamSettlementAdmission.requireRegistry(
            x.admission.core, x.admission.coreHash, x.admission.registry, x.admission.registryHash
        );
        if (
            address(x.funding.rights.resolver).codehash != x.resolverHash
                || address(x.funding.rights.factory).codehash != x.funding.factoryHash
        ) {
            revert IStreamNativeCustodyPrimarySettlement.InvalidNativeCustodySettlement();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamNativeCustodyPrimaryValidation.sol";
import "./StreamTokenProfileCustodyHash.sol";

library StreamTokenProfileCustodyValidation {
    function activation(address house, StreamNativeCustodySettlementTypes.Facts memory f)
        public
        view
        returns (StreamTokenProfileCustodyTypes.Activation memory a)
    {
        a = StreamTokenProfileCustodyHash.readOptional(house, f.auctionId);
        StreamTokenProfileCustodyTypes.Authorization memory q = a.authorization;
        if (
            a.authorizationDigest == 0 || q.auctionId != f.auctionId
                || q.baseConfigHash != f.auction.configHash
                || q.originHash != keccak256(abi.encode(f.origin)) || q.tokenId != f.auction.tokenId
                || q.primaryPolicyMode != 1 || q.assignmentHash == 0 || q.primaryPolicyHash == 0
                || q.artist == address(0) || q.nonce == 0
                || a.authorizationDigest != StreamTokenProfileCustodyHash.digest(house, q)
                || a.effectiveConfigHash != StreamTokenProfileCustodyHash.configuration(house, a)
        ) {
            revert IStreamTokenProfileCustodyAuction.InvalidTokenProfileCustody();
        }
    }

    function read(
        StreamNativeCustodyPrimaryAdmission.Context memory x,
        StreamNativeCustodySettlementTypes.CanonicalHouse memory pin,
        bytes32 id
    )
        public
        view
        returns (
            StreamNativeCustodySettlementTypes.Facts memory f,
            StreamTokenProfileCustodyTypes.Activation memory a
        )
    {
        f = StreamNativeCustodyPrimaryValidation.read(x, pin, id);
        a = activation(msg.sender, f);
    }

    function selection(
        StreamPrimarySettlementRights.Context memory x,
        uint256 collection,
        uint256 token
    ) public view returns (StreamSaleTemplate.Selection memory selected, bytes32 policy) {
        if (token == 0) revert IStreamTokenProfileCustodyAuction.InvalidTokenProfileCustody();
        IStreamRevenueResolver.ResolvedPrimaryAssignment memory actual =
            x.resolver.resolvePrimaryAssignment(collection, token, keccak256("PRIMARY_SALE"));
        if (
            !actual.exists || actual.assignmentType != 1 || actual.scope != 2
                || actual.scopeId != token || actual.profileId == 0 || actual.templateId != 0
                || actual.assignmentHash == 0 || actual.policyHash != 0
        ) {
            revert IStreamTokenProfileCustodyAuction.InvalidTokenProfileCustody();
        }
        // The selected Resolver performs the exact scope2 current-binding consent read.
        // Calling Artist directly from the house/recorder would use the wrong resolver identity.
        selected = StreamSaleTemplate.Selection(
            actual.profileId,
            x.factory.walletFor(actual.profileId),
            0,
            actual.assignmentHash,
            x.factory.profileEntriesHash(actual.profileId)
        );
        StreamPrimarySettlementRights.requireWallet(x, selected);
        policy = keccak256(
            abi.encode(
                keccak256("6529STREAM_PRIMARY_POLICY_V1"),
                block.chainid,
                address(x.resolver),
                keccak256("PRIMARY_SALE"),
                collection,
                token,
                bytes32(0),
                selected.profileId,
                selected.wallet,
                selected.assignmentHash
            )
        );
    }

    function derive(
        StreamPrimarySettlementRights.Context memory x,
        StreamNativeCustodySettlementTypes.Facts memory f,
        StreamTokenProfileCustodyTypes.Activation memory a,
        address house,
        address recorder
    )
        public
        view
        returns (
            StreamPrimarySettlementTypes.ERC20SettlementCandidate memory c,
            StreamSaleTemplate.Selection memory selected
        )
    {
        bytes32 policy;
        (selected, policy) = selection(x, f.auction.config.collectionId, f.auction.tokenId);
        IStreamNativeEnglishAuction.Auction memory sale = f.auction;
        c.saleAdapter = house;
        c.executor = sale.winner.executor;
        c.sale = StreamPrimarySettlementTypes.PrimarySale(
            sale.saleId,
            keccak256("PRIMARY_SALE"),
            1,
            sale.config.collectionId,
            sale.tokenId,
            sale.saleNonce,
            sale.winner.payer,
            sale.config.poster,
            sale.winner.deliverTo,
            sale.winner.amount,
            policy
        );
        c.lifecycleBinding.saleCreatedAt = sale.lifecycle.saleCreatedAt;
        c.lifecycleBinding.saleAdapterRegistryRevision = sale.lifecycle.saleAdapterRegistryRevision;
        c.executionBinding = StreamPrimarySettlementTypes.SaleExecutionBinding(
            StreamTokenProfileCustodyHash.execution(recorder, house, f, a),
            sale.winner.bidIndex,
            sale.winner.signed ? 1 : 2,
            sale.winner.authorizationDigest
        );
        c.orchestrationOrder = 3;
        c.rights = StreamPrimarySettlementTypes.PrimaryRights(
            selected.profileId, selected.wallet, 0, selected.assignmentHash, selected.entriesHash
        );
        c.saleExecutionHash = StreamTokenProfileCustodyHash.facts(recorder, house, f, a);
    }
}

