        uint8 subjectKind;
        bytes32 subjectId;
        bytes32 subjectStateHash;
        bytes32 schemaId;
        bytes32 statementHash;
        string statementURI;
    }

    struct AttestationRecord {
        bytes32 recordHash;
        bytes32 subjectStateHash;
        bytes32 schemaId;
        bytes32 statementHash;
        uint64 generation;
        uint64 signedAt;
        address signer;
    }

    struct Ratification {
        uint256 collectionId;
        address metadataContract;
        bytes32 contentStateHash;
    }

    struct RatificationRecord {
        bytes32 recordHash;
        bytes32 contentStateHash;
        address metadataContract;
    }

    struct AssignmentFact {
        address resolver;
        bytes32 revenueClass;
        uint8 scope;
        uint256 scopeId;
        bytes32 assignmentHash;
    }

    /// @notice Actual factory profile and assignment settings covered by prospective economics consent.
    /// @dev The supported collection profile requires policyHash zero; primary also requires royaltyBps zero.
    struct FixedEconomicsCandidate {
        bytes32 profileHash;
        bytes32 policyHash;
        uint16 royaltyBps;
        bool frozen;
    }

    /// @notice Exact current royalty assignment that the artist authorizes to become permanently frozen.
    struct RoyaltyFreeze {
        address resolver;
        uint256 collectionId;
        bytes32 revenueClass;
        bytes32 expectedAssignmentHash;
    }

    /// @notice Durable authorization with its operative artist identity and binding-generation admission.
    struct RoyaltyFreezeRecord {
        bytes32 recordHash;
        bytes32 artistId;
        uint64 bindingGeneration;
    }

    /// @notice Constructor-fixed target set; owners use the ADR0023 domain order.
    struct SuiteConfiguration {
        address registry;
        address archive;
        address[7] owners;
        address core;
        address mintManager;
        address roleRegistry;
        address metadata;
        address primaryResolver;
        address royaltyResolver;
        bytes32 primaryRevenueClass;
        address validator;
    }

    error Unauthorized(address caller);
    error InvalidBinding();
    error UnsupportedProfile();
    error InvalidRecord();
    error InvalidIdentity(bytes32 artistId);
    error AddressAlreadyRegistered(address authority);
    error InvalidAttribution(uint256 collectionId);
    error StaleOwnerSnapshot(bytes32 domainId);
    error InvalidOperation(uint16 operationId);
    error Replay(bytes32 replayKey);
    error InvalidSignature();
    error ExpiredAuthorization(uint64 deadline);
    error InvalidTimestamp(uint64 timestamp);
    error BoundExceeded(uint256 actual, uint256 maximum);
    error MissingMintPrerequisite(bytes32 prerequisite);
    error ReentrantOperation();
    error ComponentChanged(address component);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice AA-PLATFORM history, separate from every Artist binding and signature domain.
library StreamArtistPlatformTypes {
    error InvalidPlatformWorks(uint256 collectionId);
    error InvalidPlatformEvidence(bytes32 evidenceHash);

    // Numeric contest vocabulary: zero NONE, one CONTESTED, two DISMISSED, three SUSTAINED.
    struct Declaration {
        bytes32 recordHash;
        bytes32 statementHash;
        address actor;
        uint64 declaredAt;
    }

    struct Claim {
        uint256 collectionId;
        address claimant;
        address proposedArtist;
        bytes32 evidenceHash;
        bytes32 reasonHash;
        uint64 filedAt;
        bytes32 recordHash;
    }

    struct Contest {
        uint256 collectionId;
        address adjudicatedArtist;
        uint8 state;
        bytes32 claimRecordHash;
        bytes32 evidenceHash;
        bytes32 reasonHash;
        bytes32 actionId;
        bytes32 previousRecordHash;
        uint64 changedAt;
        bytes32 recordHash;
    }

    struct Correction {
        uint256 collectionId;
        address proposedArtist;
        bytes32 claimRecordHash;
        bytes32 sustainedContestRecordHash;
        bytes32 evidenceHash;
        bytes32 reasonHash;
        bytes32 approvalActionId;
        uint64 approvedAt;
        uint64 correctiveGeneration;
        bool accepted;
        bytes32 recordHash;
    }

    /// @dev Canonical fixed binary document. Publication does not establish truth or authority.
    struct Evidence {
        uint16 schemaVersion;
        uint256 collectionId;
        address proposedArtist;
        bytes32 claimRecordHash;
        bytes32 narrativeHash;
    }

    struct State {
        Declaration declaration;
        uint8 contestState;
        bytes32 contestClaim;
        bytes32 contestRecord;
        uint256 claimCount;
        bytes32 latestClaim;
        Correction correction;
    }

    struct Admission {
        bytes32 declarationHash;
        uint8 contestState;
        uint64 correctiveGeneration;
        bool corrected;
    }

    struct Context {
        bytes32 scopeHash;
        bytes32 oldValueHash;
        bytes32 newValueHash;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Permanent artist recovery approval and unavailability finding records.
/// @dev Admission evidence is stored separately from the permanently specified hash preimages.
library StreamArtistRecoveryTypes {
    struct ApprovalTerms {
        address finalityRegistry;
        uint256 collectionId;
        bytes32 finalityRecordHash;
        bytes32 recoveryManifestHash;
    }

    /// @notice The saved authority and association describe admission, not future signer readiness.
    struct ApprovalRecord {
        bytes32 recordHash;
        ApprovalTerms terms;
        bytes32 artistId;
        address signer;
        uint8 authorityClass;
        uint256 nonce;
        uint64 signedAt;
        uint64 deadline;
        uint64 bindingGeneration;
        bytes32 bindingHash;
        bytes32 digest;
    }

    struct FindingRequest {
        bytes32 artistId;
        uint256 collectionId;
        bytes32 evidenceHash;
        bytes32 reasonHash;
    }

    /// @notice Observed times and captured timing configuration remain immutable.
    /// @dev Only terms, governanceActionId, noticeEndsAt and recordedAt enter the ten-word record.
    struct FindingRecord {
        bytes32 recordHash;
        FindingRequest terms;
        bytes32 governanceActionId;
        uint64 noticeEndsAt;
        uint64 recordedAt;
        uint64 noticeSeconds;
        uint64 timingRevision;
        uint64 bindingGeneration;
        bytes32 bindingHash;
    }

    error InvalidRecoveryApproval();
    error InvalidUnavailabilityFinding();
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Typed current-principal rotation facts; canonical records keep their frozen preimages.
library StreamArtistRotationTypes {
    struct GuardianSet {
        bytes32 artistId;
        address[] guardians;
        uint32 approvalThreshold;
        uint64 minContestSeconds;
    }

    struct Rotation {
        bytes32 artistId;
        address oldAddress;
        address newAddress;
        bytes32 reasonHash;
        // Checked concurrency guard, not a field in either permanent signed schema.
        bytes32 expectedPreviousTransitionRecordHash;
    }

    struct StandingRevocation {
        bytes32 artistId;
        address revokedAddress;
        bytes32 reasonHash;
        // Checked against actual retirement, outside the permanent signed schema.
        bytes32 retiredTransitionRecordHash;
    }

    /// @notice Immutable association captured when a provisional record is written.
    struct ProvisionalAssociation {
        bytes32 transitionRecordHash;
        uint64 windowEndsAt;
    }

    /// @notice Actual Identity-owned state, never a caller's readiness assertion.
    /// @dev phase: 0 absent, 1 staged, 2 executed, 3 vetoed. Contest does not time out.
    struct TransitionState {
        bytes32 artistId;
        bytes32 recordHash;
        uint64 stagedAt;
        uint64 contestEndsAt;
        uint64 executedAt;
        uint64 postWindowEndsAt;
        uint64 contestedAt;
        uint8 phase;
    }

    struct GuardianRecord {
        bytes32 recordHash;
        GuardianSet terms;
        address signer;
        uint8 authorityClass;
        uint256 nonce;
        uint64 signedAt;
        bytes32 previousOperativeRecordHash;
        ProvisionalAssociation provisional;
    }

    struct RotationRecord {
        bytes32 recordHash;
        Rotation terms;
        bytes32 guardianSetRecordHash;
        uint32 approvalThreshold;
        uint32 guardianApprovals;
        uint256 oldNonce;
        uint256 newNonce;
        uint64 effectiveWindow;
        uint64 standingTail;
        uint64 timingRevision;
        TransitionState transition;
    }

    struct StandingRecord {
        bytes32 recordHash;
        StandingRevocation terms;
        address signer;
        uint8 authorityClass;
        uint256 nonce;
        uint64 signedAt;
    }

    /// @notice Coordinator-snapshotted operative authority, separate from historical Binding.
    struct AuthorityFact {
        bytes32 artistId;
        address authorityAddress;
        uint8 authorityClass;
        uint8 status;
    }

    function eligible(
        bytes32 artistId,
        ProvisionalAssociation memory a,
        TransitionState memory t,
        uint256 timestamp
    ) internal pure returns (bool) {
        if (a.transitionRecordHash == bytes32(0)) {
            return a.windowEndsAt == 0;
        }
        return t.artistId == artistId && t.recordHash == a.transitionRecordHash && t.phase == 2
            && t.executedAt != 0 && t.postWindowEndsAt == a.windowEndsAt
            && (t.contestedAt == 0 || t.contestedAt >= a.windowEndsAt)
            && timestamp >= a.windowEndsAt;
    }

    error InvalidGuardianSet();
    error InvalidRotation(bytes32 rotationRecordHash);
    error ActiveAuthorityWindow(bytes32 transitionRecordHash, uint64 windowEndsAt);
    error RotationNotExecutable(bytes32 rotationRecordHash);
    error InvalidPriorStanding(address priorAddress);
    error ProvisionalChainOccupied(bytes32 recordHash);
    error PayoutRequiresAuthorityContext(bytes32 artistId);
    error InvalidArtistWindow(bytes32 parameter);
    error InvalidArtistWindowContext();
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Sale terms use the adapter's actual stored identity and complete configuration hash.
library StreamArtistSaleTypes {
    struct Consent {
        uint256 collectionId;
        address saleAdapter;
        bytes32 saleId;
        bytes32 saleConfigHash;
    }

    /// @notice Permanent record plus generation applicability; the latter is outside its frozen preimage.
    struct Record {
        bytes32 recordHash;
        Consent terms;
        bytes32 artistId;
        address signer;
        uint8 authorityClass;
        uint256 nonce;
        uint64 signedAt;
        uint64 bindingGeneration;
        bytes32 bindingHash;
    }

    error SaleConsentUnavailable(uint256 collectionId, bytes32 saleId, bytes32 saleConfigHash);
    error InvalidSaleAdapter(address adapter);
    error SaleFactsReadFailed(address target, bytes4 selector);
    error SaleFactsParentGas(uint256 available, uint256 required);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamArtistRecoveryTypes as Recovery } from "./StreamArtistRecoveryTypes.sol";
import { StreamArtistOnboardingTypes as T } from "./StreamArtistOnboardingTypes.sol";
import {
    StreamArtistIdentityContestTypes as Contest
} from "./StreamArtistIdentityContestTypes.sol";
import "../finality/StreamArtworkFinalityTypes.sol";

/// @notice Action-bound admission evidence outside the permanent unavailability record hash.
library StreamArtistUnavailabilityTypes {
    struct Target {
        address recoveryRegistry;
        bytes32 recoveryActionId;
        StreamFinalityScope scope;
        bytes32 originalFinalityRecordHash;
        bytes32 recoveryManifestHash;
    }

    struct Admission {
        Target target;
        bytes32 recoveryRegistryCodeHash;
        bytes32 recoveryIntentFactsHash;
        uint256 activityEpoch;
        bytes32 governanceWitnessHash;
    }

    struct Input {
        Recovery.FindingRequest terms;
        Target target;
        T.Binding binding_;
        Contest.GovernanceWitness governance;
        bytes32 recoveryRegistryCodeHash;
        bytes32 recoveryIntentFactsHash;
        uint64 recoveryNotBefore;
        uint64 recoveryExpiresAfter;
        bool priorRecoveryTerminal;
    }

    struct Context {
        bytes32 scopeHash;
        bytes32 oldValueHash;
        bytes32 newValueHash;
        uint64 noticeSeconds;
        uint64 timingRevision;
    }

    error UnavailabilityNoticeOpen(uint64 noticeEndsAt);
    error UnavailabilityFindingActive(bytes32 recordHash);
    error UnavailabilityTargetMismatch();
}

