    /// @dev keccak256("6529STREAM_SUBJECT_COLLECTION_V1")
    bytes32 internal constant STREAM_SUBJECT_COLLECTION_V1 =
        0x3a882a22dad9915c9193738f63216234155080ed4c4fc9bfae446e90f1df6e16;

